-- 清理不存在的 gpt-5.6 真实型号及其可执行配置。
-- 历史任务、账务和已发布 Skill 版本的快照保持原样；管理员需重新选择被移除的默认模型。
DROP TEMPORARY TABLE IF EXISTS tmp_aid_invalid_gpt56;
CREATE TEMPORARY TABLE tmp_aid_invalid_gpt56 (
  id BIGINT PRIMARY KEY, model_code VARCHAR(100) NOT NULL
);
INSERT INTO tmp_aid_invalid_gpt56
SELECT id,model_code FROM aid_ai_model WHERE BINARY TRIM(real_model_code)=BINARY 'gpt-5.6';

-- 同一模型的定制路由仍可保留，仅修正错误的真实型号覆盖值。
UPDATE aid_ai_model m
JOIN aid_ai_model_protocol_binding b ON b.model_id=m.id
LEFT JOIN tmp_aid_invalid_gpt56 retired ON retired.id=m.id
SET m.config_version=COALESCE(m.config_version,0)+1,m.update_time=NOW(),m.update_by='system'
WHERE retired.id IS NULL AND JSON_VALID(b.definition_json)=1
  AND BINARY JSON_UNQUOTE(JSON_EXTRACT(b.definition_json,'$.upstreamModel'))=BINARY 'gpt-5.6'
  AND COALESCE(TRIM(m.real_model_code),'')<>'';
UPDATE aid_ai_model_protocol_binding b
JOIN aid_ai_model m ON m.id=b.model_id
LEFT JOIN tmp_aid_invalid_gpt56 retired ON retired.id=m.id
SET b.definition_json=JSON_SET(b.definition_json,'$.upstreamModel',m.real_model_code),
    b.update_time=NOW(),b.update_by='system'
WHERE retired.id IS NULL AND JSON_VALID(b.definition_json)=1
  AND BINARY JSON_UNQUOTE(JSON_EXTRACT(b.definition_json,'$.upstreamModel'))=BINARY 'gpt-5.6'
  AND COALESCE(TRIM(m.real_model_code),'')<>'';
DELETE b FROM aid_ai_model_protocol_binding b
WHERE JSON_VALID(b.definition_json)=1
  AND BINARY JSON_UNQUOTE(JSON_EXTRACT(b.definition_json,'$.upstreamModel'))=BINARY 'gpt-5.6';

UPDATE aid_agent a JOIN tmp_aid_invalid_gpt56 r ON BINARY a.model_code=BINARY r.model_code
SET a.model_code=NULL,a.update_time=NOW(),a.update_by='system';
UPDATE aid_gen_agent_pool a JOIN tmp_aid_invalid_gpt56 r ON BINARY a.model_code=BINARY r.model_code
SET a.model_code=NULL,a.update_time=NOW(),a.update_by='system';
UPDATE aid_project_gen_config a JOIN tmp_aid_invalid_gpt56 r ON BINARY a.model_code=BINARY r.model_code
SET a.del_flag='1',a.update_time=NOW(),a.update_by='system',a.remark='引用模型不存在，请重新选择'
WHERE a.del_flag='0';
UPDATE aid_skill a JOIN tmp_aid_invalid_gpt56 r ON BINARY a.model_code=BINARY r.model_code
SET a.status='1',a.update_time=NOW(),a.update_by='system',a.remark='引用模型不存在，请重新配置并发布版本'
WHERE a.status<>'1';

DELETE b FROM aid_ai_business_model_binding b JOIN tmp_aid_invalid_gpt56 r ON r.id=b.model_id;
DELETE b FROM aid_ai_model_protocol_binding b JOIN tmp_aid_invalid_gpt56 r ON r.id=b.model_id;
DELETE b FROM aid_ai_model_capability b JOIN tmp_aid_invalid_gpt56 r ON r.id=b.model_id;
DELETE a FROM aid_ai_model_alias a JOIN tmp_aid_invalid_gpt56 r ON r.id=a.model_id OR BINARY r.model_code=BINARY a.legacy_model_code;
DELETE a FROM aid_role_voice_binding a JOIN tmp_aid_invalid_gpt56 r ON r.id=a.model_id;
DELETE a FROM aid_ai_voice_library a JOIN tmp_aid_invalid_gpt56 r ON r.id=a.model_id;

-- JSON 数组按真实元素位置删除，兼容数字/字符串 ID、重复 ID 和任意长度，保持其余顺序。
DROP PROCEDURE IF EXISTS aid_remove_invalid_gpt56_pool_ids;
DELIMITER $$
CREATE PROCEDURE aid_remove_invalid_gpt56_pool_ids()
BEGIN
  DECLARE done INT DEFAULT 0;
  DECLARE pool_id BIGINT;
  DECLARE pool_ids JSON;
  DECLARE idx INT;
  DECLARE item_id VARCHAR(100);
  DECLARE changed INT;
  DECLARE pool_cursor CURSOR FOR SELECT id,model_ids FROM aid_ai_model_func_config WHERE model_ids IS NOT NULL;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=1;
  OPEN pool_cursor;
  pool_loop: LOOP
    FETCH pool_cursor INTO pool_id,pool_ids;
    IF done=1 THEN LEAVE pool_loop; END IF;
    SET idx=0,changed=0;
    WHILE idx<JSON_LENGTH(pool_ids) DO
      SET item_id=JSON_UNQUOTE(JSON_EXTRACT(pool_ids,CONCAT('$[',idx,']')));
      IF EXISTS(SELECT 1 FROM tmp_aid_invalid_gpt56 WHERE BINARY CAST(id AS CHAR)=BINARY item_id) THEN
        SET pool_ids=JSON_REMOVE(pool_ids,CONCAT('$[',idx,']')),changed=1;
      ELSE
        SET idx=idx+1;
      END IF;
    END WHILE;
    IF changed=1 THEN
      UPDATE aid_ai_model_func_config SET model_ids=pool_ids,update_time=NOW(),update_by='system' WHERE id=pool_id;
    END IF;
  END LOOP;
  CLOSE pool_cursor;
END$$
CALL aid_remove_invalid_gpt56_pool_ids()$$
DROP PROCEDURE IF EXISTS aid_remove_invalid_gpt56_pool_ids$$
DELIMITER ;

DELETE m FROM aid_ai_model m JOIN tmp_aid_invalid_gpt56 r ON r.id=m.id;
DROP TEMPORARY TABLE IF EXISTS tmp_aid_invalid_gpt56;

-- 文件存储同步记录：新安装/升级均等待管理员手动核对并同步；保留已有记录与资源地址。
INSERT INTO aid_config (category, config_name, config_value, config_dict, del_flag, order_num, create_time, create_by, remark)
SELECT 'storage_sync', 'fingerprint', '', '文件存储同步状态', '0', 999, NOW(), 'system', '由明确同步配置操作维护，不通过普通配置编辑'
WHERE NOT EXISTS (SELECT 1 FROM aid_config WHERE category='storage_sync' AND config_name='fingerprint');

-- 助手会话、运行控制、预算授权与后台治理菜单：仅本次变更的商业环境幂等增量。
-- MySQL 5.7；不导入运营 Prompt、供应商、模型、价格或业务数据。
-- 授权记录只约束本次运行的可消费上限，不是余额、钱包或可转移资产。
SET NAMES utf8mb4 COLLATE utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `aid_chat_session` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `skill_id` bigint DEFAULT NULL,
  `project_id` bigint NOT NULL DEFAULT 0,
  `episode_id` bigint NOT NULL DEFAULT 0,
  `workspace_id` bigint DEFAULT NULL,
  `node_object_id` varchar(64) DEFAULT NULL,
  `session_type` varchar(20) NOT NULL DEFAULT 'SKILL',
  `client_session_id` varchar(64) DEFAULT NULL,
  `module_code` varchar(20) DEFAULT NULL,
  `mode` varchar(20) DEFAULT NULL,
  `title` varchar(100) NOT NULL,
  `base_input_json` longtext NOT NULL,
  `active_runtime_run_id` bigint DEFAULT NULL,
  `state_revision` bigint NOT NULL DEFAULT 0,
  `reasoning_enabled` tinyint(1) NOT NULL DEFAULT 0,
  `reasoning_level` varchar(20) DEFAULT NULL,
  `show_reasoning` tinyint(1) NOT NULL DEFAULT 0,
  `context_summary` longtext DEFAULT NULL,
  `summary_until_seq` bigint DEFAULT NULL,
  `context_anchor_message_id` bigint DEFAULT NULL,
  `last_message_seq` bigint NOT NULL DEFAULT 0,
  `last_event_seq` bigint NOT NULL DEFAULT 0,
  `favorite` tinyint(1) NOT NULL DEFAULT 0,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `last_active_time` datetime DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chat_client_session` (`user_id`,`client_session_id`),
  KEY `idx_chat_session_user` (`user_id`,`session_type`,`del_flag`,`last_active_time`,`id`),
  KEY `idx_chat_session_scope` (`user_id`,`project_id`,`episode_id`,`skill_id`,`del_flag`,`last_active_time`,`id`),
  KEY `idx_chat_session_skill` (`skill_id`,`del_flag`,`id`),
  KEY `idx_chat_canvas_node` (`user_id`,`workspace_id`,`node_object_id`,`last_active_time`),
  KEY `idx_chat_session_active` (`user_id`,`active_runtime_run_id`,`del_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用生成、Skill与助手共用会话';

CREATE TABLE IF NOT EXISTS `aid_chat_message` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint NOT NULL,
  `run_id` bigint DEFAULT NULL,
  `runtime_run_id` bigint DEFAULT NULL,
  `turn_id` bigint DEFAULT NULL,
  `media_task_id` bigint DEFAULT NULL,
  `seq_no` bigint NOT NULL,
  `client_message_id` varchar(64) DEFAULT NULL,
  `request_hash` varchar(64) DEFAULT NULL,
  `role` varchar(20) NOT NULL,
  `status` varchar(20) NOT NULL,
  `message_kind` varchar(30) NOT NULL DEFAULT 'STATUS',
  `media_type` varchar(20) NOT NULL DEFAULT 'TEXT',
  `model_code` varchar(100) DEFAULT NULL,
  `tool_call_id` varchar(64) DEFAULT NULL,
  `content_text` varchar(1000) DEFAULT NULL,
  `error_message` varchar(500) DEFAULT NULL,
  `context_anchor` tinyint(1) NOT NULL DEFAULT 0,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chat_message_seq` (`session_id`,`seq_no`),
  UNIQUE KEY `uk_chat_client_message` (`session_id`,`client_message_id`),
  KEY `idx_chat_message_run` (`run_id`),
  KEY `idx_chat_message_runtime` (`runtime_run_id`,`seq_no`),
  KEY `idx_chat_message_task` (`media_task_id`),
  KEY `idx_chat_message_cursor` (`session_id`,`status`,`del_flag`,`seq_no`),
  KEY `idx_chat_message_reconcile` (`role`,`del_flag`,`status`,`media_type`,`update_time`,`media_task_id`),
  KEY `idx_chat_message_anchor` (`session_id`,`context_anchor`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用会话消息';

CREATE TABLE IF NOT EXISTS `aid_chat_message_part` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `message_id` bigint NOT NULL,
  `part_seq` int NOT NULL,
  `part_type` varchar(20) NOT NULL,
  `slot_name` varchar(50) NOT NULL,
  `text_content` longtext DEFAULT NULL,
  `resource_id` bigint DEFAULT NULL,
  `resource_role` varchar(20) DEFAULT NULL,
  `resource_url` varchar(2000) DEFAULT NULL,
  `thumbnail_url` varchar(2000) DEFAULT NULL,
  `mime_type` varchar(100) DEFAULT NULL,
  `metadata_json` longtext DEFAULT NULL,
  `context_scope` varchar(30) NOT NULL DEFAULT 'CURRENT_TURN',
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_chat_message_part` (`message_id`,`part_seq`),
  KEY `idx_chat_part_type` (`part_type`),
  KEY `idx_chat_part_resource` (`resource_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用会话有序内容块';

CREATE TABLE IF NOT EXISTS `aid_runtime_run` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `session_id` bigint DEFAULT NULL,
  `turn_id` bigint DEFAULT NULL,
  `member_type` varchar(10) DEFAULT NULL,
  `member_id` bigint DEFAULT NULL,
  `version_id` bigint DEFAULT NULL,
  `version_digest` varchar(64) DEFAULT NULL,
  `model_code` varchar(100) DEFAULT NULL,
  `output_kind` varchar(10) DEFAULT NULL,
  `executor_strategy` varchar(30) DEFAULT NULL,
  `project_id` bigint DEFAULT NULL,
  `workspace_id` bigint DEFAULT NULL,
  `node_object_id` varchar(64) DEFAULT NULL,
  `active_node_key` varchar(96) GENERATED ALWAYS AS (CASE WHEN `del_flag`='0' AND `status` IN ('CREATED','RUNNING','WAITING_INPUT') AND `workspace_id` IS NOT NULL AND `node_object_id` IS NOT NULL THEN CONCAT(`workspace_id`,':',`node_object_id`) ELSE NULL END) STORED,
  `node_version` bigint DEFAULT NULL,
  `client_request_id` varchar(64) NOT NULL,
  `request_digest` varchar(64) NOT NULL,
  `request_json` longtext NOT NULL,
  `trial_grant_id` bigint DEFAULT NULL,
  `estimated_tokens_used` int NOT NULL DEFAULT 0,
  `clarification_key` varchar(64) DEFAULT NULL,
  `clarification_digest` varchar(64) DEFAULT NULL,
  `media_task_id` bigint DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'CREATED',
  `state_revision` bigint NOT NULL DEFAULT 0,
  `plan_revision` bigint NOT NULL DEFAULT 0,
  `budget_authorization_id` bigint DEFAULT NULL,
  `context_digest` char(64) DEFAULT NULL,
  `checkpoint_ref` varchar(500) DEFAULT NULL,
  `pause_reason` varchar(30) DEFAULT NULL,
  `resume_status` varchar(30) DEFAULT NULL,
  `stop_requested` tinyint(1) NOT NULL DEFAULT 0,
  `next_action` varchar(40) DEFAULT NULL,
  `lease_owner` varchar(64) DEFAULT NULL,
  `lease_until` datetime DEFAULT NULL,
  `fencing_token` bigint NOT NULL DEFAULT 0,
  `next_retry_at` datetime DEFAULT NULL,
  `result_json` longtext DEFAULT NULL,
  `error_message` varchar(1000) DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_run_request` (`user_id`,`session_id`,`client_request_id`),
  UNIQUE KEY `uk_runtime_run_legacy_request` (`user_id`,`member_type`,`member_id`,`client_request_id`),
  UNIQUE KEY `uk_runtime_active_node` (`active_node_key`),
  KEY `idx_runtime_run_task` (`media_task_id`),
  KEY `idx_runtime_run_recovery` (`status`,`update_time`,`id`),
  KEY `idx_runtime_run_next_retry` (`status`,`next_retry_at`,`id`),
  KEY `idx_runtime_run_session` (`session_id`,`id`),
  KEY `idx_runtime_run_budget_authorization` (`budget_authorization_id`),
  KEY `idx_runtime_run_history` (`user_id`,`workspace_id`,`node_object_id`,`create_time`,`id`),
  KEY `idx_runtime_canvas_active` (`workspace_id`,`status`,`create_time`,`id`),
  KEY `idx_runtime_canvas_node_history` (`workspace_id`,`node_object_id`,`create_time`,`id`),
  KEY `idx_runtime_run_version` (`member_type`,`member_id`,`version_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent、Skill与助手通用运行快照';

CREATE TABLE IF NOT EXISTS `aid_runtime_run_step` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_id` bigint NOT NULL,
  `step_index` int NOT NULL,
  `step_key` varchar(64) NOT NULL,
  `step_kind` varchar(10) NOT NULL,
  `stable_step_id` varchar(64) NOT NULL,
  `plan_revision` bigint NOT NULL DEFAULT 0,
  `plan_position` int DEFAULT NULL,
  `attempt_no` int NOT NULL DEFAULT 1,
  `operation_kind` varchar(64) DEFAULT NULL,
  `idempotency_key` varchar(128) DEFAULT NULL,
  `skill_version_id` bigint DEFAULT NULL,
  `tool_code` varchar(100) DEFAULT NULL,
  `input_digest` varchar(64) NOT NULL,
  `input_artifact_ref` longtext DEFAULT NULL,
  `output_artifact_ref` longtext DEFAULT NULL,
  `approval_id` bigint DEFAULT NULL,
  `reservation_id` bigint DEFAULT NULL,
  `media_task_id` bigint DEFAULT NULL,
  `child_run_id` bigint DEFAULT NULL,
  `child_run_kind` varchar(30) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'CREATED',
  `retry_class` varchar(30) DEFAULT NULL,
  `provider_acceptance_state` varchar(30) NOT NULL DEFAULT 'NOT_SUBMITTED',
  `lease_owner` varchar(64) DEFAULT NULL,
  `lease_until` datetime DEFAULT NULL,
  `fencing_token` bigint NOT NULL DEFAULT 0,
  `output_json` longtext DEFAULT NULL,
  `error_message` varchar(1000) DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_step` (`run_id`,`step_index`),
  UNIQUE KEY `uk_runtime_step_attempt` (`run_id`,`plan_revision`,`stable_step_id`,`attempt_no`),
  UNIQUE KEY `uk_runtime_step_idempotency` (`run_id`,`idempotency_key`),
  KEY `idx_runtime_step_plan` (`run_id`,`plan_revision`,`plan_position`,`id`),
  KEY `idx_runtime_step_lease` (`status`,`lease_until`,`id`),
  KEY `idx_runtime_step_reservation` (`reservation_id`),
  KEY `idx_runtime_step_task` (`media_task_id`),
  KEY `idx_runtime_step_child` (`child_run_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通用运行有界步骤与任务关联';

CREATE TABLE IF NOT EXISTS `aid_runtime_input_request` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_id` bigint NOT NULL,
  `request_key` varchar(64) NOT NULL,
  `round_no` int NOT NULL,
  `schema_digest` char(64) NOT NULL,
  `context_digest` char(64) NOT NULL,
  `plan_revision` bigint NOT NULL,
  `status` varchar(20) NOT NULL,
  `question_bundle_json` text NOT NULL,
  `accepted_answers_json` text DEFAULT NULL,
  `accepted_digest` char(64) DEFAULT NULL,
  `accepted_key` varchar(64) DEFAULT NULL,
  `suspended_at` datetime DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_input_request` (`run_id`,`request_key`),
  KEY `idx_runtime_input_request_status` (`run_id`,`status`,`round_no`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手结构化问题请求';

CREATE TABLE IF NOT EXISTS `aid_runtime_input_draft` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `input_request_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `question_id` varchar(64) NOT NULL,
  `draft_revision` bigint NOT NULL DEFAULT 0,
  `choice_ids_json` text DEFAULT NULL,
  `free_text` text DEFAULT NULL,
  `answer_state` varchar(20) NOT NULL,
  `last_client_operation_id` varchar(64) DEFAULT NULL,
  `last_payload_digest` char(64) DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_input_draft` (`input_request_id`,`user_id`,`question_id`),
  KEY `idx_runtime_input_draft_user` (`user_id`,`update_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手问题逐题草稿';

CREATE TABLE IF NOT EXISTS `aid_runtime_input_view` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `input_request_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `cursor_question_id` varchar(64) DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_input_view` (`input_request_id`,`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手问题浏览位置';

CREATE TABLE IF NOT EXISTS `aid_runtime_event` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint NOT NULL,
  `run_id` bigint DEFAULT NULL,
  `seq` bigint NOT NULL,
  `event_type` varchar(50) NOT NULL,
  `entity_id` varchar(64) DEFAULT NULL,
  `entity_revision` bigint DEFAULT NULL,
  `causation_id` varchar(64) DEFAULT NULL,
  `payload_json` text DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `publish_attempt` int NOT NULL DEFAULT 0,
  `next_retry_at` datetime DEFAULT NULL,
  `create_time` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_event_seq` (`session_id`,`seq`),
  KEY `idx_runtime_event_run` (`run_id`,`seq`),
  KEY `idx_runtime_event_publish` (`published_at`,`next_retry_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手权威事件与发布Outbox';

CREATE TABLE IF NOT EXISTS `aid_runtime_command` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `actor_id` bigint NOT NULL,
  `session_id` bigint NOT NULL,
  `client_request_id` varchar(64) NOT NULL,
  `payload_digest` char(64) NOT NULL,
  `command_type` varchar(40) NOT NULL,
  `status` varchar(20) NOT NULL,
  `result_json` text DEFAULT NULL,
  `error_code` varchar(64) DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_command_request` (`actor_id`,`session_id`,`client_request_id`),
  KEY `idx_runtime_command_session` (`session_id`,`create_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手幂等控制命令';

CREATE TABLE IF NOT EXISTS `aid_billing_authorization` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `payer_user_id` bigint NOT NULL,
  `runtime_run_id` bigint NOT NULL,
  `approved_total` decimal(14,4) NOT NULL,
  `reserved_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `settled_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `currency_unit` varchar(16) NOT NULL DEFAULT 'BALANCE',
  `precision_scale` tinyint NOT NULL DEFAULT 4,
  `status` varchar(16) NOT NULL,
  `revision` bigint NOT NULL DEFAULT 1,
  `state_revision` bigint NOT NULL DEFAULT 1,
  `policy_digest` char(64) NOT NULL,
  `expires_at` datetime DEFAULT NULL,
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_run` (`runtime_run_id`),
  KEY `idx_payer_status` (`payer_user_id`,`status`),
  KEY `idx_status_expiry` (`status`,`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手运行预算授权上限，不存放账户余额';

CREATE TABLE IF NOT EXISTS `aid_billing_authorization_reservation` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `authorization_id` bigint NOT NULL,
  `authorization_revision` bigint NOT NULL,
  `runtime_run_id` bigint NOT NULL,
  `runtime_step_id` bigint DEFAULT NULL,
  `stable_step_key` varchar(128) NOT NULL,
  `approval_id` bigint DEFAULT NULL,
  `attempt_no` int NOT NULL,
  `operation_kind` varchar(32) NOT NULL,
  `logical_call_key` varchar(128) NOT NULL,
  `request_digest` char(64) NOT NULL,
  `quote_id` varchar(80) NOT NULL,
  `quote_digest` char(64) NOT NULL,
  `quote_expires_at` datetime NOT NULL,
  `media_task_id` bigint DEFAULT NULL,
  `billing_trace_id` varchar(64) NOT NULL,
  `quoted_upper_bound` decimal(14,4) NOT NULL,
  `reserved_amount` decimal(14,4) NOT NULL,
  `wallet_frozen_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `settled_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `released_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `wallet_refunded_amount` decimal(14,4) NOT NULL DEFAULT 0.0000,
  `state` varchar(20) NOT NULL,
  `settlement_key` varchar(128) DEFAULT NULL,
  `revision` bigint NOT NULL DEFAULT 1,
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_logical_call_key` (`logical_call_key`),
  UNIQUE KEY `uk_quote_id` (`quote_id`),
  UNIQUE KEY `uk_billing_trace_id` (`billing_trace_id`),
  UNIQUE KEY `uk_media_task_id` (`media_task_id`),
  UNIQUE KEY `uk_settlement_key` (`settlement_key`),
  KEY `idx_authorization_state` (`authorization_id`,`state`),
  KEY `idx_runtime_step` (`runtime_run_id`,`stable_step_key`,`attempt_no`),
  KEY `idx_physical_runtime_step` (`runtime_step_id`),
  KEY `idx_reconciliation` (`state`,`update_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手预算预留与既有账本关联';

-- Runtime budget policy is the durable absolute execution boundary; account balances remain authoritative elsewhere.
CREATE TABLE IF NOT EXISTS `aid_runtime_budget_policy` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_id` bigint NOT NULL,
  `authorization_id` bigint NOT NULL,
  `authorization_revision` bigint NOT NULL,
  `mode` varchar(20) NOT NULL,
  `absolute_max_charge` decimal(14,4) NOT NULL,
  `per_call_max_charge` decimal(14,4) NOT NULL,
  `allowed_tool_codes_json` text NOT NULL,
  `allowed_model_codes_json` text NOT NULL,
  `allowed_capability_codes_json` text NOT NULL,
  `allowed_media_types_json` text NOT NULL,
  `target_refs_json` mediumtext NOT NULL,
  `automatic_forbidden_operation_kinds_json` text NOT NULL,
  `max_iterations` int NOT NULL,
  `max_operations` int NOT NULL,
  `used_iterations` int NOT NULL DEFAULT 0,
  `used_operations` int NOT NULL DEFAULT 0,
  `expires_at` datetime NOT NULL,
  `scope_digest` char(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `state_revision` bigint NOT NULL DEFAULT 0,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_budget_policy_run` (`run_id`),
  UNIQUE KEY `uk_runtime_budget_policy_authorization` (`authorization_id`),
  KEY `idx_runtime_budget_policy_expiry` (`status`,`expires_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手运行绝对预算与能力策略，不存放钱包金额';

-- 兼容已存在的 chat/runtime 表；每项先查元数据，重复执行不重复列或索引。
SET @assistant_schema := DATABASE();

-- 旧生成会话补齐显式类型；新旧读取不再依赖 NULL 通配。
UPDATE `aid_chat_session`
SET `session_type`='GENERATION',`update_by`='system',`update_time`=NOW()
WHERE `session_type` IS NULL OR TRIM(`session_type`)='';

SET @assistant_column_exists := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_chat_session' AND COLUMN_NAME='module_code');
SET @assistant_ddl := IF(@assistant_column_exists=0,'ALTER TABLE `aid_chat_session` ADD COLUMN `module_code` varchar(20) NULL AFTER `client_session_id`','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
