SET @assistant_column_exists := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_run_step' AND COLUMN_NAME='fencing_token');
SET @assistant_ddl := IF(@assistant_column_exists=0,'ALTER TABLE `aid_runtime_run_step` ADD COLUMN `fencing_token` bigint NOT NULL DEFAULT 0 AFTER `lease_until`','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
SET @assistant_index_exists := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_run_step' AND INDEX_NAME='uk_runtime_step_attempt');
SET @assistant_ddl := IF(@assistant_index_exists=0,'ALTER TABLE `aid_runtime_run_step` ADD UNIQUE INDEX `uk_runtime_step_attempt` (`run_id`,`plan_revision`,`stable_step_id`,`attempt_no`)','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
SET @assistant_index_exists := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_run_step' AND INDEX_NAME='uk_runtime_step_idempotency');
SET @assistant_ddl := IF(@assistant_index_exists=0,'ALTER TABLE `aid_runtime_run_step` ADD UNIQUE INDEX `uk_runtime_step_idempotency` (`run_id`,`idempotency_key`)','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
SET @assistant_index_exists := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_run_step' AND INDEX_NAME='idx_runtime_step_plan');
SET @assistant_ddl := IF(@assistant_index_exists=0,'ALTER TABLE `aid_runtime_run_step` ADD INDEX `idx_runtime_step_plan` (`run_id`,`plan_revision`,`plan_position`,`id`)','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
SET @assistant_index_exists := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_run_step' AND INDEX_NAME='idx_runtime_step_lease');
SET @assistant_ddl := IF(@assistant_index_exists=0,'ALTER TABLE `aid_runtime_run_step` ADD INDEX `idx_runtime_step_lease` (`status`,`lease_until`,`id`)','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
SET @assistant_index_exists := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_run_step' AND INDEX_NAME='idx_runtime_step_reservation');
SET @assistant_ddl := IF(@assistant_index_exists=0,'ALTER TABLE `aid_runtime_run_step` ADD INDEX `idx_runtime_step_reservation` (`reservation_id`)','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;

-- 公共后台助手治理入口；只增加只读菜单权限，并沿用管理员角色授权方式。
SET @assistant_parent_id := (
  SELECT `menu_id` FROM `sys_menu`
  WHERE `parent_id`=0 AND `menu_type`='M' AND `path`='ai-model'
  ORDER BY `menu_id` LIMIT 1
);
SET @assistant_menu_id := (
  SELECT `menu_id` FROM `sys_menu`
  WHERE `component`='aid/assistant/index' OR `perms`='aid:assistant:run:list'
  ORDER BY `menu_id` LIMIT 1
);
INSERT INTO `sys_menu`
(`menu_name`,`parent_id`,`order_num`,`path`,`component`,`query`,`route_name`,`is_frame`,`is_cache`,
 `menu_type`,`visible`,`status`,`perms`,`icon`,`create_by`,`create_time`,`update_by`,`update_time`,`remark`)
SELECT '助手运行治理',@assistant_parent_id,10,'assistant-governance','aid/assistant/index',NULL,'',1,0,
       'C','0','0','aid:assistant:run:list','monitor','system',NOW(),'',NULL,'助手运行、Tool、预算与问题请求只读治理'
WHERE @assistant_parent_id IS NOT NULL AND @assistant_menu_id IS NULL;
SET @assistant_menu_id := (
  SELECT `menu_id` FROM `sys_menu`
  WHERE `component`='aid/assistant/index' OR `perms`='aid:assistant:run:list'
  ORDER BY `menu_id` LIMIT 1
);
UPDATE `sys_menu`
SET `menu_name`='助手运行治理',`parent_id`=@assistant_parent_id,`order_num`=10,
    `path`='assistant-governance',`component`='aid/assistant/index',`perms`='aid:assistant:run:list',
    `visible`='0',`status`='0',`update_by`='system',`update_time`=NOW(),
    `remark`='助手运行、Tool、预算与问题请求只读治理'
WHERE `menu_id`=@assistant_menu_id AND @assistant_parent_id IS NOT NULL;
INSERT INTO `sys_menu`
(`menu_name`,`parent_id`,`order_num`,`path`,`component`,`query`,`route_name`,`is_frame`,`is_cache`,
 `menu_type`,`visible`,`status`,`perms`,`icon`,`create_by`,`create_time`,`update_by`,`update_time`,`remark`)
SELECT p.menu_name,@assistant_menu_id,p.order_num,'#',NULL,NULL,'',1,0,'F','0','0',p.perms,'#',
       'system',NOW(),'',NULL,''
FROM (
  SELECT '助手运行详情' menu_name,1 order_num,'aid:assistant:run:query' perms
  UNION ALL SELECT '助手 Tool 目录查询',2,'aid:assistant:tool:query'
  UNION ALL SELECT '助手预算列表',3,'aid:assistant:budget:list'
  UNION ALL SELECT '助手预算详情',4,'aid:assistant:budget:query'
  UNION ALL SELECT '助手问题列表',5,'aid:assistant:input:list'
  UNION ALL SELECT '助手问题详情',6,'aid:assistant:input:query'
  UNION ALL SELECT '助手 Agent 列表',7,'aid:assistant:agent:list'
  UNION ALL SELECT '助手 Agent 详情',8,'aid:assistant:agent:query'
  UNION ALL SELECT '助手 Agent 编辑',9,'aid:assistant:agent:edit'
  UNION ALL SELECT '助手 Agent 发布',10,'aid:assistant:agent:publish'
  UNION ALL SELECT '助手 Agent 激活',11,'aid:assistant:agent:activate'
) p
WHERE @assistant_menu_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM `sys_menu` m WHERE m.`perms`=p.perms);
INSERT IGNORE INTO `sys_role_menu` (`role_id`,`menu_id`)
SELECT 1,`menu_id` FROM `sys_menu`
WHERE `menu_id`=@assistant_menu_id OR `parent_id`=@assistant_menu_id;

-- 公共 Agent 治理复用同一稳定身份、活动草稿与不可变版本体系。
CREATE TABLE IF NOT EXISTS `aid_runtime_agent` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `agent_code` varchar(64) NOT NULL,
  `agent_family` varchar(20) DEFAULT NULL,
  `name` varchar(100) NOT NULL,
  `description` varchar(1000) DEFAULT NULL,
  `icon_url` varchar(500) DEFAULT NULL,
  `owner_type` varchar(20) NOT NULL DEFAULT 'USER',
  `owner_user_id` bigint DEFAULT NULL,
  `visibility` varchar(20) NOT NULL DEFAULT 'PRIVATE',
  `current_version_id` bigint DEFAULT NULL,
  `status` char(1) NOT NULL DEFAULT '1',
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_agent_code` (`agent_code`),
  KEY `idx_runtime_agent_owner` (`owner_type`,`owner_user_id`,`status`,`del_flag`),
  KEY `idx_runtime_agent_family` (`agent_family`,`status`,`del_flag`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent稳定身份';

CREATE TABLE IF NOT EXISTS `aid_runtime_agent_draft` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `agent_id` bigint NOT NULL,
  `owner_user_id` bigint NOT NULL,
  `active_key` varchar(160) DEFAULT NULL,
  `base_version_id` bigint DEFAULT NULL,
  `draft_json` longtext NOT NULL,
  `draft_digest` varchar(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'EDITING',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_agent_draft_active` (`active_key`),
  KEY `idx_runtime_agent_draft` (`agent_id`,`owner_user_id`,`status`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent活动草稿';

CREATE TABLE IF NOT EXISTS `aid_runtime_agent_version` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `agent_id` bigint NOT NULL,
  `version_code` varchar(64) NOT NULL,
  `publish_status` varchar(20) NOT NULL DEFAULT 'PRIVATE',
  `instruction` longtext NOT NULL,
  `model_config_json` text NOT NULL,
  `input_schema_json` longtext NOT NULL,
  `output_schema_json` longtext NOT NULL,
  `definition_json` longtext DEFAULT NULL,
  `package_digest` varchar(64) NOT NULL,
  `status` char(1) NOT NULL DEFAULT '0',
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_agent_version` (`agent_id`,`version_code`),
  UNIQUE KEY `uk_runtime_agent_digest` (`package_digest`),
  KEY `idx_runtime_agent_version` (`agent_id`,`status`,`del_flag`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent不可变版本';

CREATE TABLE IF NOT EXISTS `aid_runtime_agent_skill_ref` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `agent_version_id` bigint NOT NULL,
  `skill_id` bigint NOT NULL,
  `skill_version_id` bigint NOT NULL,
  `skill_code` varchar(64) NOT NULL,
  `package_digest` char(64) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_agent_skill_ref` (`agent_version_id`,`skill_id`),
  KEY `idx_agent_skill_reverse` (`skill_id`,`agent_version_id`),
  KEY `idx_agent_skill_version` (`skill_version_id`,`agent_version_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent版本固定Skill依赖';

CREATE TABLE IF NOT EXISTS `aid_runtime_agent_tool_ref` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `agent_version_id` bigint NOT NULL,
  `tool_code` varchar(100) NOT NULL,
  `contract_version` varchar(32) NOT NULL,
  `schema_digest` char(64) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_agent_tool_ref` (`agent_version_id`,`tool_code`),
  KEY `idx_agent_tool_reverse` (`tool_code`,`agent_version_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Agent版本固定Tool契约';

-- 画布已有 Skill 引用表只补不可变包摘要；无法解析的历史引用让迁移失败，禁止猜值。
-- Module bindings contain identities only; import and publish built-ins before binding them.
CREATE TABLE IF NOT EXISTS `aid_runtime_module_agent_binding` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `module_code` varchar(32) NOT NULL,
  `runtime_agent_id` bigint NOT NULL,
  `active_version_id` bigint NOT NULL,
  `binding_revision` bigint NOT NULL DEFAULT 0,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_module_agent` (`module_code`),
  KEY `idx_runtime_module_agent_version` (`runtime_agent_id`,`active_version_id`),
  KEY `idx_runtime_module_agent_status` (`status`,`del_flag`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Assistant module to active Agent version binding';

-- Existing Agent Skill references must resolve the immutable published package digest.
SET @assistant_column_exists := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_agent_skill_ref' AND COLUMN_NAME='package_digest');
SET @assistant_ddl := IF(@assistant_column_exists=0,'ALTER TABLE `aid_runtime_agent_skill_ref` ADD COLUMN `package_digest` char(64) NULL AFTER `skill_code`','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
UPDATE `aid_runtime_agent_skill_ref` r
JOIN `aid_skill_version` v ON v.`id`=r.`skill_version_id`
SET r.`package_digest`=v.`package_digest`
WHERE r.`package_digest` IS NULL OR r.`package_digest`='';
SET @assistant_column_nullable := (SELECT IS_NULLABLE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_agent_skill_ref' AND COLUMN_NAME='package_digest');
SET @assistant_ddl := IF(@assistant_column_nullable='YES','ALTER TABLE `aid_runtime_agent_skill_ref` MODIFY COLUMN `package_digest` char(64) NOT NULL','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;
SET @assistant_index_exists := (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@assistant_schema AND TABLE_NAME='aid_runtime_agent_skill_ref' AND INDEX_NAME='idx_agent_skill_version');
SET @assistant_ddl := IF(@assistant_index_exists=0,'ALTER TABLE `aid_runtime_agent_skill_ref` ADD INDEX `idx_agent_skill_version` (`skill_version_id`,`agent_version_id`)','SELECT 1'); PREPARE assistant_stmt FROM @assistant_ddl; EXECUTE assistant_stmt; DEALLOCATE PREPARE assistant_stmt;

-- 动态规划、显式批准和产物版本是后续助手循环的权威持久状态。
CREATE TABLE IF NOT EXISTS `aid_runtime_plan` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_id` bigint NOT NULL,
  `revision` bigint NOT NULL,
  `parent_revision` bigint DEFAULT NULL,
  `agent_version_id` bigint NOT NULL,
  `protocol_version` varchar(40) NOT NULL,
  `planner_attempt_no` int NOT NULL DEFAULT 1,
  `definition_json` longtext NOT NULL,
  `input_context_digest` char(64) NOT NULL,
  `definition_digest` char(64) NOT NULL,
  `quote_digest` char(64) DEFAULT NULL,
  `media_task_id` bigint DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'PROPOSED',
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_plan_revision` (`run_id`,`revision`),
  KEY `idx_runtime_plan_status` (`run_id`,`status`,`revision`),
  KEY `idx_runtime_plan_task` (`media_task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手不可变规划修订';

CREATE TABLE IF NOT EXISTS `aid_runtime_approval` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `client_request_id` varchar(64) NOT NULL,
  `authorization_id` bigint DEFAULT NULL,
  `authorization_revision` bigint DEFAULT NULL,
  `scope_kind` varchar(30) NOT NULL,
  `request_digest` char(64) NOT NULL,
  `answer_digest` char(64) DEFAULT NULL,
  `context_digest` char(64) NOT NULL,
  `planning_attempt_no` int DEFAULT NULL,
  `plan_revision` bigint DEFAULT NULL,
  `plan_digest` char(64) DEFAULT NULL,
  `scope_json` longtext NOT NULL,
  `scope_digest` char(64) NOT NULL,
  `node_revision_set_json` longtext DEFAULT NULL,
  `allowed_tool_set_json` text DEFAULT NULL,
  `allowed_model_set_json` text DEFAULT NULL,
  `allowed_capability_set_json` text DEFAULT NULL,
  `max_attempts` int DEFAULT NULL,
  `mode` varchar(20) DEFAULT NULL,
  `quote_id` varchar(64) DEFAULT NULL,
  `quote_digest` char(64) DEFAULT NULL,
  `quote_snapshot_ref` varchar(500) DEFAULT NULL,
  `max_charge` decimal(14,4) NOT NULL,
  `expires_at` datetime NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'QUOTED',
  `state_revision` bigint NOT NULL DEFAULT 0,
  `accepted_at` datetime DEFAULT NULL,
  `invalidated_at` datetime DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_approval_request` (`user_id`,`run_id`,`client_request_id`),
  KEY `idx_runtime_approval_status` (`run_id`,`status`,`id`),
  KEY `idx_runtime_approval_authorization` (`authorization_id`,`authorization_revision`),
  KEY `idx_runtime_approval_expiry` (`status`,`expires_at`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='助手显式规划与执行批准';

-- Immutable artifact/source chunks and auditable coverage, review, and adoption projections.
CREATE TABLE IF NOT EXISTS `aid_runtime_artifact_chunk` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `artifact_id` bigint NOT NULL,
  `chunk_index` int NOT NULL,
  `char_start` int NOT NULL,
  `char_end` int NOT NULL,
  `char_count` int NOT NULL,
  `word_count` int NOT NULL,
  `content_text` mediumtext NOT NULL,
  `content_hash` char(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_artifact_chunk` (`artifact_id`,`chunk_index`),
  KEY `idx_runtime_artifact_chunk_hash` (`content_hash`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Immutable runtime artifact text chunk';

CREATE TABLE IF NOT EXISTS `aid_runtime_source_revision` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `source_kind` varchar(40) NOT NULL,
  `source_object_id` varchar(128) NOT NULL,
  `source_revision` varchar(128) NOT NULL,
  `content_hash` char(64) NOT NULL,
  `char_count` int NOT NULL,
  `word_count` int NOT NULL,
  `chunk_count` int NOT NULL,
  `access_scope_digest` char(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_source_revision` (`user_id`,`source_kind`,`source_object_id`,`source_revision`,`content_hash`),
  KEY `idx_runtime_source_user` (`user_id`,`status`,`del_flag`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Authorized immutable source revision';

CREATE TABLE IF NOT EXISTS `aid_runtime_source_chunk` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `source_revision_id` bigint NOT NULL,
  `chunk_index` int NOT NULL,
  `char_start` int NOT NULL,
  `char_end` int NOT NULL,
  `char_count` int NOT NULL,
  `word_count` int NOT NULL,
  `locator_json` text NOT NULL,
  `content_text` mediumtext NOT NULL,
  `content_hash` char(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_source_chunk` (`source_revision_id`,`chunk_index`),
  KEY `idx_runtime_source_chunk_hash` (`content_hash`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Immutable authorized source text chunk';

CREATE TABLE IF NOT EXISTS `aid_runtime_source_coverage` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `run_id` bigint NOT NULL,
  `step_id` bigint NOT NULL,
  `source_revision_id` bigint NOT NULL,
  `chunk_index` int NOT NULL,
  `purpose` varchar(40) NOT NULL,
  `coverage_status` varchar(20) NOT NULL,
  `evidence_artifact_id` bigint DEFAULT NULL,
  `revision` bigint NOT NULL DEFAULT 0,
  `notes` varchar(1000) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_source_coverage` (`run_id`,`source_revision_id`,`chunk_index`,`purpose`),
  KEY `idx_runtime_source_coverage_step` (`run_id`,`step_id`,`status`,`id`),
  KEY `idx_runtime_source_evidence` (`evidence_artifact_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Runtime source coverage ledger';

CREATE TABLE IF NOT EXISTS `aid_runtime_artifact_review` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `artifact_id` bigint NOT NULL,
  `review_artifact_id` bigint NOT NULL,
  `reviewer_run_id` bigint NOT NULL,
  `reviewer_step_id` bigint NOT NULL,
  `verdict` varchar(20) NOT NULL,
  `severity_counts_json` text NOT NULL,
  `content_hash` char(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'ACTIVE',
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_artifact_review` (`artifact_id`,`review_artifact_id`),
  KEY `idx_runtime_artifact_reviewer` (`reviewer_run_id`,`reviewer_step_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Immutable artifact review receipt';

CREATE TABLE IF NOT EXISTS `aid_runtime_artifact_adoption` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `session_id` bigint NOT NULL,
  `artifact_id` bigint NOT NULL,
  `target_kind` varchar(40) NOT NULL,
  `target_object_id` varchar(128) NOT NULL,
  `expected_target_revision` varchar(128) NOT NULL,
  `result_target_revision` varchar(128) DEFAULT NULL,
  `client_request_id` varchar(64) NOT NULL,
  `request_digest` char(64) NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'PENDING',
  `receipt_json` text DEFAULT NULL,
  `error_code` varchar(64) DEFAULT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_by` varchar(64) DEFAULT '',
  `create_time` datetime DEFAULT NULL,
  `update_by` varchar(64) DEFAULT '',
  `update_time` datetime DEFAULT NULL,
  `remark` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_runtime_artifact_adoption` (`user_id`,`target_kind`,`target_object_id`,`client_request_id`),
