  `pool_code` varchar(100) NOT NULL,
  `draft_config_json` longtext NOT NULL,
  `revision` bigint NOT NULL,
  `active_config_json` longtext DEFAULT NULL,
  `active_revision` bigint DEFAULT NULL,
  `state` varchar(24) NOT NULL DEFAULT 'DRAFT',
  `health_status` varchar(24) DEFAULT NULL,
  `health_generation` bigint NOT NULL DEFAULT 0,
  `health_json` longtext DEFAULT NULL,
  `health_checked_at` datetime DEFAULT NULL,
  `draft_worker_id` varchar(100) DEFAULT NULL,
  `draft_credential_ciphertext` text DEFAULT NULL,
  `verification_json` longtext DEFAULT NULL,
  `verified_at` datetime DEFAULT NULL,
  `create_by` varchar(64) NOT NULL,
  `update_by` varchar(64) NOT NULL,
  `create_time` datetime NOT NULL,
  `update_time` datetime NOT NULL,
  PRIMARY KEY (`node_key`),
  KEY `idx_compute_pool_state` (`pool_code`,`state`),
  KEY `idx_compute_updated` (`update_time`,`node_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='计算节点配置及已确认版本';

SET @compute_ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_compute_node' AND COLUMN_NAME='health_generation')=0,'ALTER TABLE aid_compute_node ADD COLUMN health_generation bigint NOT NULL DEFAULT 0','SELECT 1');
