EXECUTE compute_stmt;
DEALLOCATE PREPARE compute_stmt;
SET @compute_ddl=IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='aid_compute_node' AND COLUMN_NAME='health_status')=0,'ALTER TABLE aid_compute_node ADD COLUMN health_status varchar(24) DEFAULT NULL','SELECT 1');
