traCharge":false}},"taskQuerySuffix":"/v1/song/query/%s"}',0,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='mureka-9.5' AND p.provider_code='mureka' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_protocol_binding x WHERE x.model_id=m.id AND x.capability_code='post_soundtrack_generate' AND x.binding_code='official');
