SELECT p.id,'eleven_v4_turbo','eleven_v4_turbo','ElevenLabs V4 Turbo','audio','audio','/v1/text-to-dialogue/stream-input','elevenlabs-audio','1','0','SKU','{"mode":"SKU","meterType":"PER_CHAR","chargeType":"AUDIO","preHold":true,"priceCurrency":"USD","exchangeRateToCny":null,"matchStrategy":"FIRST_HIT","params":[],"skus":[{"skuCode":"ws_text_to_dialogue_stream_input","skuName":"实时对话","remark":"按字符计价，上游用量只退不补","enabled":true,"priority":1,"match":{},"meterType":"PER_CHAR","pricePerChar":0.00004}],"settleRule":{"settleMode":"REFUND_ONLY","usageSource":"PROVIDER_USAGE","allowRefund":true,"allowExtraCharge":false}}','1','{"officialAudioOperation":"elevenlabs.ws.text_to_dialogue_stream_input","ttsTextRequired":false,"ttsVoiceRequired":false,"audioOperation":"official_audio","officialRequestSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"queryParameters":{"type":"object","properties":{"model_id":{"type":"string","enum":["eleven_v4","eleven_v4_turbo"]},"output_format":{"description":"Any type"},"language_code":{"type":"string"},"sync_alignment":{"type":"boolean","default":false},"apply_text_normalization":{"description":"Any type"},"seed":{"type":"integer","minimum":1,"maximum":4294967295},"enable_logging":{"type":"boolean","default":true}},"additionalProperties":false},"messages":{"type":"array","minItems":2,"maxItems":200,"items":{"$ref":"#/$defs/TextToDialogueWebsocketClientMessage"}}},"required":["messages"],"additionalProperties":false,"$defs":{"NormalizedAlignment":{"type":"object","properties":{"charStartTimesMs":{"type":"array","items":{"type":"integer"},"description":"A list of starting times (in milliseconds) for each character in the normalized text as it\\ncorresponds to the audio. For instance, the character ''H'' starts at time 0 ms in the audio.\\nNote these times are relative to the returned chunk from the model, and not the\\nfull audio response.\\n"},"charDurationsMs":{"type":"array","items":{"type":"integer"},"description":"A list of durations (in milliseconds) for each character in the normalized text as it\\ncorresponds to the audio. For instance, the character ''H'' lasts for 3 ms in the audio.\\nNote these times are relative to the returned chunk from the model, and not the\\nfull audio response.\\n"},"chars":{"type":"array","items":{"type":"string"},"description":"A list of characters in the normalized text sequence. For instance, the first character is ''H''.\\nNote that this list may contain spaces, punctuation, and other special characters.\\nThe length of this list should be the same as the lengths of `charStartTimesMs` and `charDurationsMs`.\\n"}},"description":"Alignment information for the generated audio given the input normalized text sequence.\\n","title":"NormalizedAlignment","additionalProperties":false},"Alignment":{"type":"object","properties":{"charStartTimesMs":{"type":"array","items":{"type":"integer"},"description":"A list of starting times (in milliseconds) for each character in the text as it\\ncorresponds to the audio. For instance, the character ''H'' starts at time 0 ms in the audio.\\nNote these times are relative to the returned chunk from the model, and not the\\nfull audio response.\\n"},"charDurationsMs":{"type":"array","items":{"type":"integer"},"description":"A list of durations (in milliseconds) for each character in the text as it\\ncorresponds to the audio. For instance, the character ''H'' lasts for 3 ms in the audio.\\nNote these times are relative to the returned chunk from the model, and not the\\nfull audio response.\\n"},"chars":{"type":"array","items":{"type":"string"},"description":"A list of characters in the text sequence. For instance, the first character is ''H''.\\nNote that this list may contain spaces, punctuation, and other special characters.\\nThe length of this list should be the same as the lengths of `charStartTimesMs` and `charDurationsMs`.\\n"}},"description":"Alignment information for the generated audio given the input text sequence.\\n","title":"Alignment","additionalProperties":false},"AudioOutput":{"type":"object","properties":{"audio":{"type":"string","description":"A generated partial audio chunk, encoded using the selected output_format, by default this\\nis MP3 encoded as a base64 string.\\n"},"normalizedAlignment":{"$ref":"#/$defs/NormalizedAlignment"},"alignment":{"$ref":"#/$defs/Alignment"}},"required":["audio"],"title":"AudioOutput","additionalProperties":false},"FinalOutput":{"type":"object","properties":{"isFinal":{"type":"boolean","enum":[true],"description":"Indicates if the generation is complete. If set to `True`, `audio` will be null.\\n"}},"title":"FinalOutput","additionalProperties":false},"V1TextToSpeechVoiceIdStreamInputSubscribe":{"oneOf":[{"$ref":"#/$defs/AudioOutput"},{"$ref":"#/$defs/FinalOutput"}],"title":"V1TextToSpeechVoiceIdStreamInputSubscribe"},"RealtimeVoiceSettings":{"type":"object","properties":{"stability":{"type":"number","format":"double","default":0.5,"description":"Defines the stability for voice settings."},"similarity_boost":{"type":"number","format":"double","default":0.75,"description":"Defines the similarity boost for voice settings."},"style":{"type":"number","format":"double","default":0,"description":"Defines the style for voice settings. This parameter is available on V2+ models."},"use_speaker_boost":{"type":"boolean","default":true,"description":"Defines the use speaker boost for voice settings. This parameter is available on V2+ models."},"speed":{"type":"number","format":"double","default":1,"description":"Controls the speed of the generated speech. Values range from 0.7 to 1.2, with 1.0 being the default speed."}},"title":"RealtimeVoiceSettings","additionalProperties":false},"GenerationConfig":{"type":"object","properties":{"chunk_length_schedule":{"type":"array","items":{"type":"number","format":"double"},"description":"This is an advanced setting that most users shouldn''t need to use. It relates to our\\ngeneration schedule.\\n\\nOur WebSocket service incorporates a buffer system designed to optimize the Time To First Byte (TTFB) while maintaining high-quality streaming.\\n\\nAll text sent to the WebSocket endpoint is added to this buffer and only when that buffer reaches a certain size is an audio generation attempted. This is because our model provides higher quality audio when the model has longer inputs, and can deduce more context about how the text should be delivered.\\n\\nThe buffer ensures smooth audio data delivery and is automatically emptied with a final audio generation either when the stream is closed, or upon sending a `flush` command. We have advanced settings for changing the chunk schedule, which can improve latency at the cost of quality by generating audio more frequently with smaller text inputs.\\n\\nThe `chunk_length_schedule` determines the minimum amount of text that needs to be sent and present in our\\nbuffer before audio starts being generated. This is to maximise the amount of context available to\\nthe model to improve audio quality, whilst balancing latency of the returned audio chunks.\\n\\nThe default value for `chunk_length_schedule` is: [120, 160, 250, 290].\\n\\nThis means that the first chunk of audio will not be generated until you send text that\\ntotals at least 120 characters long. The next chunk of audio will only be generated once a\\nfurther 160 characters have been sent. The third audio chunk will be generated after the\\nnext 250 characters. Then the fourth, and beyond, will be generated in sets of at least 290 characters.\\n\\nCustomize this array to suit your needs. If you want to generate audio more frequently\\nto optimise latency, you can reduce the values in the array. Note that setting the values\\ntoo low may result in lower quality audio. Please test and adjust as needed.\\n\\nEach item should be in the range 50-500.\\n"}},"title":"GenerationConfig","additionalProperties":false},"PronunciationDictionaryLocator":{"type":"object","properties":{"pronunciation_dictionary_id":{"type":"string","description":"The unique identifier of the pronunciation dictionary"},"version_id":{"type":"string","description":"The version identifier of the pronunciation dictionary"}},"required":["pronunciation_dictionary_id","version_id"],"description":"Identifies a specific pronunciation dictionary to use","title":"PronunciationDictionaryLocator","additionalProperties":false},"InitializeConnection":{"type":"object","properties":{"text":{"type":"string","enum":[" "],"description":"The initial text that must be sent is a blank space."},"voice_settings":{"$ref":"#/$defs/RealtimeVoiceSettings"},"generation_config":{"$ref":"#/$defs/GenerationConfig"},"pronunciation_dictionary_locators":{"type":"array","items":{"$ref":"#/$defs/PronunciationDictionaryLocator"},"description":"Optional list of pronunciation dictionary locators. If provided, these dictionaries will be used to\\nmodify pronunciation of matching text. Must only be provided in the first message.\\n\\nNote: Pronunciation dictionary matches will only be respected within a provided chunk.\\n"},"xi-api-key":{"type":"string","description":"Your ElevenLabs API key. This can only be included in the first message and is not needed if present in the header.\\n"},"authorization":{"type":"string","description":"Your authorization bearer token. This can only be included in the first message and is not needed if present in the header.\\n"}},"required":["text"],"title":"InitializeConnection","additionalProperties":false},"SendText":{"type":"object","properties":{"text":{"type":"string","description":"The text to be sent to the API for audio generation. Should always end with a single space string."},"try_trigger_generation":{"type":"boolean","default":false,"description":"This is an advanced setting that most users shouldn''t need to use. It relates to our generation schedule.\\n\\nUse this to attempt to immediately trigger the generation of audio, overriding the `chunk_length_schedule`.\\nUnlike flush, `try_trigger_generation` will only generate audio if our\\nbuffer contains more than a minimum\\nthreshold of characters, this is to ensure a higher quality response from our model.\\n\\nNote that overriding the chunk schedule to generate small amounts of\\ntext may result in lower quality audio, therefore, only use this parameter if you\\nreally need text to be processed immediately. We generally recommend keeping the default value of\\n`false` and adjusting the `chunk_length_schedule` in the `generation_config` instead.\\n"},"voice_settings":{"$ref":"#/$defs/RealtimeVoiceSettings","description":"The voice settings field can be provided in the first `InitializeConnection` message and then must either be not provided or not changed."},"generator_config":{"$ref":"#/$defs/GenerationConfig","description":"The generator config field can be provided in the first `InitializeConnection` message and then must either be not provided or not changed."},"flush":{"type":"boolean","default":false,"description":"Flush forces the generation of audio. Set this value to true when you have finished sending text, but want to keep the websocket connection open.\\n\\nThis is useful when you want to ensure that the last chunk of audio is generated even when the length of text sent is smaller than the value set in chunk_length_schedule (e.g. 120 or 50).\\n"}},"required":["text"],"title":"SendText","additionalProperties":false},"CloseConnection":{"type":"object","properties":{"text":{"type":"string","enum":[""],"description":"End the stream with an empty string"}},"required":["text"],"title":"CloseConnection","additionalProperties":false},"V1TextToSpeechVoiceIdStreamInputPublish":{"oneOf":[{"$ref":"#/$defs/InitializeConnection"},{"$ref":"#/$defs/SendText"},{"$ref":"#/$defs/CloseConnection"}],"title":"V1TextToSpeechVoiceIdStreamInputPublish"},"AudioOutputMulti":{"type":"object","properties":{"audio":{"type":"string","description":"Base64 encoded audio chunk."},"normalizedAlignment":{"oneOf":[{"$ref":"#/$defs/NormalizedAlignment"},{"type":"null"}]},"alignment":{"oneOf":[{"$ref":"#/$defs/Alignment"},{"type":"null"}]},"contextId":{"type":"string","description":"The contextId for which this audio is."}},"required":["audio"],"description":"Server payload containing an audio chunk for a specific context.","title":"AudioOutputMulti","additionalProperties":false},"FinalOutputMulti":{"type":"object","properties":{"isFinal":{"type":"boolean","enum":[true],"description":"Indicates this is the final message for the context."},"contextId":{"type":"string","description":"The context_id for which this is the final message."}},"required":["isFinal"],"description":"Server payload indicating the final output for a specific context.","title":"FinalOutputMulti","additionalProperties":false},"V1TextToSpeechVoiceIdMultiStreamInputSubscribe":{"oneOf":[{"$ref":"#/$defs/AudioOutputMulti"},{"$ref":"#/$defs/FinalOutputMulti"}],"title":"V1TextToSpeechVoiceIdMultiStreamInputSubscribe"},"InitializeConnectionMulti":{"type":"object","properties":{"text":{"type":"string","enum":[" "],"description":"Must be a single space character to initiate the context."},"voice_settings":{"$ref":"#/$defs/RealtimeVoiceSettings"},"generation_config":{"$ref":"#/$defs/GenerationConfig"},"pronunciation_dictionary_locators":{"type":"array","items":{"$ref":"#/$defs/PronunciationDictionaryLocator"},"description":"Optional pronunciation dictionaries for this context."},"xi_api_key":{"type":"string","description":"Your ElevenLabs API key (if not in header). For this context''s first message only."},"authorization":{"type":"string","description":"Your authorization bearer token (if not in header). For this context''s first message only."},"context_id":{"type":"string","description":"A unique identifier for the first context created in the websocket. If not provided, a default context will be used."}},"required":["text"],"description":"Payload to initialize a new context in a multi-stream WebSocket connection.","title":"InitializeConnectionMulti","additionalProperties":false},"InitialiseContext":{"type":"object","properties":{"text":{"type":"string","description":"The initial text to synthesize. Should end with a single space."},"voice_settings":{"$ref":"#/$defs/RealtimeVoiceSettings"},"generation_config":{"$ref":"#/$defs/GenerationConfig"},"pronunciation_dictionary_locators":{"type":"array","items":{"$ref":"#/$defs/PronunciationDictionaryLocator"},"description":"Optional list of pronunciation dictionary locators to be used for this context."},"xi_api_key":{"type":"string","description":"Your ElevenLabs API key. Required if not provided in the WebSocket connection''s header or query parameters. This applies to the (re)initialization of this specific context."},"authorization":{"type":"string","description":"Your authorization bearer token. Required if not provided in the WebSocket connection''s header or query parameters. This applies to the (re)initialization of this specific context."},"context_id":{"type":"string","description":"An identifier for the text-to-speech context. If omitted, a default context ID may be assigned by the server. If provided, this message will create a new context with this ID or re-initialize an existing one with the new settings and text."}},"required":["text"],"description":"Payload to initialize or re-initialize a TTS context with specific settings and initial text for multi-stream connections.","title":"InitialiseContext","additionalProperties":false},"SendTextMulti":{"type":"object","properties":{"text":{"type":"string","description":"Text to synthesize. Should end with a single space."},"context_id":{"type":"string","description":"The target context_id for this text."},"flush":{"type":"boolean","default":false,"description":"If true, flushes the audio buffer for the specified context. If false, the text will be appended to the buffer to be generated."}},"required":["text"],"description":"Payload to send text for synthesis to an existing context.","title":"SendTextMulti","additionalProperties":false},"FlushContextClient":{"type":"object","properties":{"context_id":{"type":"string","description":"The context_id to flush."},"text":{"type":"string","description":"The text to append to the buffer to be flushed."},"flush":{"type":"boolean","default":false,"description":"If true, flushes the audio buffer for the specified context. If false, the context will remain open and the text will be appended to the buffer to be generated."}},"required":["context_id","flush"],"description":"Payload to flush the audio buffer for a specific context.","title":"FlushContextClient","additionalProperties":false},"CloseContextClient":{"type":"object","properties":{"context_id":{"type":"string","description":"The context_id to close."},"close_context":{"type":"boolean","default":false,"description":"Must set the close_context to true, to close the specified context. If false, the context will remain open and the text will be ignored. If set to true, the context will close. If it has already been set to flush it will continue flushing. The same context id can be used again but will not be linked to the previous context with the same name."}},"required":["context_id","close_context"],"description":"Payload to close a specific TTS context.","title":"CloseContextClient","additionalProperties":false},"CloseSocketClient":{"type":"object","properties":{"close_socket":{"type":"boolean","default":false,"description":"If true, closes all contexts and closes the entire WebSocket connection. Any context that was previously set to flush will wait to flush before closing."}},"description":"Payload to signal closing the entire WebSocket connection.","title":"CloseSocketClient","additionalProperties":false},"KeepContextAlive":{"type":"object","properties":{"text":{"type":"string","enum":[""],"description":"An empty string. This text is ignored by the server but its presence resets the inactivity timeout for the specified context."},"context_id":{"type":"string","description":"The identifier of the context to keep alive."}},"required":["text","context_id"],"description":"Payload to keep a specific context alive by resetting its inactivity timeout. Empty text is ignored but resets the clock.","title":"KeepContextAlive","additionalProperties":false},"V1TextToSpeechVoiceIdMultiStreamInputPublish":{"oneOf":[{"$ref":"#/$defs/InitializeConnectionMulti"},{"$ref":"#/$defs/InitialiseContext"},{"$ref":"#/$defs/SendTextMulti"},{"$ref":"#/$defs/FlushContextClient"},{"$ref":"#/$defs/CloseContextClient"},{"$ref":"#/$defs/CloseSocketClient"},{"$ref":"#/$defs/KeepContextAlive"}],"title":"V1TextToSpeechVoiceIdMultiStreamInputPublish"},"_v1_speech-to-text_realtime_model_id":{"type":"string","enum":["scribe_v2_realtime"],"default":"scribe_v2_realtime","description":"The ID of the model to use for speech-to-text transcription.","title":"/v1/speech-to-text/realtime_model_id"},"_v1_speech-to-text_realtime_commit_strategy":{"type":"string","enum":["manual","vad","turn_prediction"],"description":"Commit strategy for speech segmentation. ''manual'' requires explicit commits, ''vad'' automatically segments speech using silence detection, ''turn_prediction'' additionally commits as soon as the model predicts the speaker has finished their turn (only for models that predict turns, where it is the default).","title":"/v1/speech-to-text/realtime_commit_strategy"},"_v1_speech-to-text_realtime_entity_detection":{"oneOf":[{"type":"string"},{"type":"array","items":{"type":"string"}}],"description":"Detect entities on committed transcripts. Can be ''all'', a single entity type or category, or a list of types/categories (''pii'', ''phi'', ''pci'', ''other'', ''offensive_language''). When enabled, detected entities are delivered in a separate ''committed_transcript_entities'' event with their text, type, and character positions.","title":"/v1/speech-to-text/realtime_entity_detection"},"AudioForma