ntifier for this session."},"client_session_id":{"type":["string","null"],"description":"Client-defined session identifier, if provided during connection."}},"required":["message_type","session_id"],"description":"Confirms the session has been initialized.","title":"sessionStarted","additionalProperties":false},"status":{"type":"object","properties":{"message_type":{"type":"string","enum":["status"],"description":"The message type identifier."},"status":{"type":"string","description":"Current session status (`started` or `stopped`)."}},"required":["message_type","status"],"description":"Session lifecycle update.","title":"status","additionalProperties":false},"partialTranscript":{"type":"object","properties":{"message_type":{"type":"string","enum":["partial_transcript"],"description":"The message type identifier."},"text":{"type":"string","description":"Partial transcription text."}},"required":["message_type","text"],"description":"Interim transcription of the source audio.","title":"partialTranscript","additionalProperties":false},"finalTranscript":{"type":"object","properties":{"message_type":{"type":"string","enum":["final_transcript"],"description":"The message type identifier."},"text":{"type":"string","description":"Final transcription text."}},"required":["message_type","text"],"description":"Final transcription of a completed segment.","title":"finalTranscript","additionalProperties":false},"translation":{"type":"object","properties":{"message_type":{"type":"string","enum":["translation"],"description":"The message type identifier."},"text":{"type":"string","description":"Translated text."}},"required":["message_type","text"],"description":"Translated text in the target language.","title":"translation","additionalProperties":false},"audio":{"type":"object","properties":{"message_type":{"type":"string","enum":["audio"],"description":"The message type identifier."},"data":{"type":"string","description":"Base64-encoded audio data."},"sample_rate":{"type":"integer","description":"Sample rate of the audio in Hz."}},"required":["message_type","data","sample_rate"],"description":"Base64-encoded audio of the translated speech.","title":"audio","additionalProperties":false},"error":{"type":"object","properties":{"message_type":{"type":"string","enum":["error"],"description":"The message type identifier."},"error":{"type":"string","description":"Error message."}},"required":["message_type","error"],"description":"Error encountered during translation.","title":"error","additionalProperties":false},"TranslateAuthError":{"type":"object","properties":{"message_type":{"type":"string","enum":["auth_error"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateAuthError","additionalProperties":false},"TranslateRateLimitedError":{"type":"object","properties":{"message_type":{"type":"string","enum":["rate_limited"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateRateLimitedError","additionalProperties":false},"TranslateQueueOverflowError":{"type":"object","properties":{"message_type":{"type":"string","enum":["queue_overflow"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateQueueOverflowError","additionalProperties":false},"TranslateInputError":{"type":"object","properties":{"message_type":{"type":"string","enum":["input_error"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateInputError","additionalProperties":false},"TranslateTranscriberError":{"type":"object","properties":{"message_type":{"type":"string","enum":["transcriber_error"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateTranscriberError","additionalProperties":false},"TranslateTranslationError":{"type":"object","properties":{"message_type":{"type":"string","enum":["translation_error"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateTranslationError","additionalProperties":false},"TranslateAudioOutputError":{"type":"object","properties":{"message_type":{"type":"string","enum":["audio_output_error"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateAudioOutputError","additionalProperties":false},"TranslateQuotaExceededError":{"type":"object","properties":{"message_type":{"type":"string","enum":["quota_exceeded"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateQuotaExceededError","additionalProperties":false},"TranslatePaymentIssueError":{"type":"object","properties":{"message_type":{"type":"string","enum":["payment_issue"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslatePaymentIssueError","additionalProperties":false},"TranslateUnacceptedTermsError":{"type":"object","properties":{"message_type":{"type":"string","enum":["unaccepted_terms"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateUnacceptedTermsError","additionalProperties":false},"V1TranslationRealtimeSubscribe":{"oneOf":[{"$ref":"#/$defs/sessionStarted"},{"$ref":"#/$defs/status"},{"$ref":"#/$defs/partialTranscript"},{"$ref":"#/$defs/finalTranscript"},{"$ref":"#/$defs/translation"},{"$ref":"#/$defs/audio"},{"$ref":"#/$defs/error"},{"$ref":"#/$defs/TranslateAuthError"},{"$ref":"#/$defs/TranslateRateLimitedError"},{"$ref":"#/$defs/TranslateQueueOverflowError"},{"$ref":"#/$defs/TranslateInputError"},{"$ref":"#/$defs/TranslateTranscriberError"},{"$ref":"#/$defs/TranslateTranslationError"},{"$ref":"#/$defs/TranslateAudioOutputError"},{"$ref":"#/$defs/TranslateQuotaExceededError"},{"$ref":"#/$defs/TranslatePaymentIssueError"},{"$ref":"#/$defs/TranslateUnacceptedTermsError"}],"title":"V1TranslationRealtimeSubscribe"},"inputAudioChunk":{"type":"object","properties":{"message_type":{"type":"string","enum":["input_audio_chunk"],"description":"The message type identifier."},"audio_base_64":{"type":"string","description":"Base64-encoded audio data. Recommended chunk size is around 100 ms of audio."}},"required":["message_type","audio_base_64"],"description":"A chunk of audio to be translated.","title":"inputAudioChunk","additionalProperties":false},"endOfStream":{"type":"object","properties":{"message_type":{"type":"string","enum":["end_of_stream"],"description":"The message type identifier."}},"required":["message_type"],"description":"Signal that the client has finished sending audio.","title":"endOfStream","additionalProperties":false},"V1TranslationRealtimePublish":{"oneOf":[{"$ref":"#/$defs/inputAudioChunk"},{"$ref":"#/$defs/endOfStream"}],"title":"V1TranslationRealtimePublish"}}}}','1','0','0',1,1,NOW(),'system','核验账号权限、全部SKU价格及外币汇率后启用' FROM aid_ai_provider p WHERE p.provider_code='elevenlabs' AND NOT EXISTS(SELECT 1 FROM aid_ai_model m WHERE m.model_code='eleven_v4_turbo');
