SELECT m.id,'ws_text_to_dialogue_stream_input','audio','{"code":"ws_text_to_dialogue_stream_input","label":"文本配音（Turbo）","generateMode":"audio","enabled":true,"defaultCapability":true,"evidenceStatus":"VERIFIED","sourceUrls":["https://elevenlabs.io/docs/api-reference"],"parameters":[{"name":"options","label":"官方参数","type":"object","properties":[{"name":"queryParameters","label":"queryParameters","type":"object","required":false,"properties":[{"name":"model_id","label":"model_id","type":"string","required":false,"choices":["eleven_v4","eleven_v4_turbo"],"widget":"textarea"},{"name":"output_format","label":"output_format","type":"string","description":"Any type","required":false,"widget":"textarea"},{"name":"language_code","label":"language_code","type":"string","required":false,"widget":"textarea"},{"name":"sync_alignment","label":"sync_alignment","type":"boolean","required":false},{"name":"apply_text_normalization","label":"apply_text_normalization","type":"string","description":"Any type","required":false,"widget":"textarea"},{"name":"seed","label":"seed","type":"integer","required":false,"minimum":1,"maximum":4294967295},{"name":"enable_logging","label":"enable_logging","type":"boolean","required":false}]},{"name":"messages","label":"messages","type":"array","required":true,"minimum":2,"maximum":200,"items":{"name":"item","label":"TextToDialogueWebsocketClientMessage","type":"object","description":"All fields are optional unless noted for the **first** message.\\n\\n**First message requirements**\\n- `voices`: non-empty array of voice IDs (maximum 10 for `eleven_v3`; exactly 1 for `eleven_v3_conversational`).\\n- Credentials if not supplied via `xi-api-key` / `Authorization` headers or `single_use_token` query parameter.\\n\\n**Subsequent messages**\\n- Do not resend `voices`, `pronunciation_dictionary_locators`, or credential fields.\\n","required":false,"properties":[{"name":"inputs","label":"inputs","type":"array","description":"Dialogue lines to append for synthesis.","required":false,"items":{"name":"item","label":"TextToDialogueWebsocketVoiceInput","type":"object","required":false,"properties":[{"name":"text","label":"text","type":"string","description":"Text appended for this voice. Buffered with prior text until the server triggers generation.","required":true,"widget":"textarea"},{"name":"voice_id","label":"voice_id","type":"string","description":"Must be one of the IDs from the initial `voices` array.","required":true,"widget":"textarea"},{"name":"new_turn","label":"new_turn","type":"boolean","description":"When `true`, the server finalizes the current pending segment (as if the speaker finished their turn) before applying this input.","required":false}]}},{"name":"flush","label":"flush","type":"boolean","description":"Force generation of buffered text without closing the connection.","required":false},{"name":"close_socket","label":"close_socket","type":"boolean","description":"Flush buffers, emit remaining audio, send `is_final`, and close the WebSocket.","required":false},{"name":"keep_alive","label":"keep_alive","type":"boolean","description":"Resets the 20s inactivity timer; performs no synthesis.","required":false},{"name":"voices","label":"voices","type":"array","description":"Voice IDs to load for the session (first message only, required on first message).","required":false,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"voice_settings","label":"TextToDialogueWebsocketVoiceSettings","type":"object","description":"Voice settings for dialogue generation. Only `stability` is supported for `eleven_v3` dialogue models.","required":false,"properties":[{"name":"stability","label":"stability","type":"number","description":"Determines how stable the voice is and the randomness between each generation. Lower values introduce broader emotional range for the voice. Higher values can result in a monotonous voice with limited emotion.","required":false,"minimum":0,"maximum":1}]},{"name":"pronunciation_dictionary_locators","label":"pronunciation_dictionary_locators","type":"array","description":"Optional pronunciation dictionaries (first message only).","required":false,"items":{"name":"item","label":"PronunciationDictionaryLocator","type":"object","description":"Identifies a specific pronunciation dictionary to use","required":false,"properties":[{"name":"pronunciation_dictionary_id","label":"pronunciation_dictionary_id","type":"string","description":"The unique identifier of the pronunciation dictionary","required":true,"widget":"textarea"},{"name":"version_id","label":"version_id","type":"string","description":"The version identifier of the pronunciation dictionary","required":true,"widget":"textarea"}]}}]}}]}],"rules":[],"presentation":{"supportsTextInput":false,"maxOutputCount":1,"defaultOutputCount":1}}',0,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='eleven_v4_turbo' AND p.provider_code='elevenlabs' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_capability x WHERE x.model_id=m.id AND x.capability_code='ws_text_to_dialogue_stream_input');
