"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateQuotaExceededError","additionalProperties":false},"TranslatePaymentIssueError":{"type":"object","properties":{"message_type":{"type":"string","enum":["payment_issue"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslatePaymentIssueError","additionalProperties":false},"TranslateUnacceptedTermsError":{"type":"object","properties":{"message_type":{"type":"string","enum":["unaccepted_terms"]},"error":{"type":"string"}},"required":["message_type","error"],"title":"TranslateUnacceptedTermsError","additionalProperties":false},"V1TranslationRealtimeSubscribe":{"oneOf":[{"$ref":"#/$defs/sessionStarted"},{"$ref":"#/$defs/status"},{"$ref":"#/$defs/partialTranscript"},{"$ref":"#/$defs/finalTranscript"},{"$ref":"#/$defs/translation"},{"$ref":"#/$defs/audio"},{"$ref":"#/$defs/error"},{"$ref":"#/$defs/TranslateAuthError"},{"$ref":"#/$defs/TranslateRateLimitedError"},{"$ref":"#/$defs/TranslateQueueOverflowError"},{"$ref":"#/$defs/TranslateInputError"},{"$ref":"#/$defs/TranslateTranscriberError"},{"$ref":"#/$defs/TranslateTranslationError"},{"$ref":"#/$defs/TranslateAudioOutputError"},{"$ref":"#/$defs/TranslateQuotaExceededError"},{"$ref":"#/$defs/TranslatePaymentIssueError"},{"$ref":"#/$defs/TranslateUnacceptedTermsError"}],"title":"V1TranslationRealtimeSubscribe"},"inputAudioChunk":{"type":"object","properties":{"message_type":{"type":"string","enum":["input_audio_chunk"],"description":"The message type identifier."},"audio_base_64":{"type":"string","description":"Base64-encoded audio data. Recommended chunk size is around 100 ms of audio."}},"required":["message_type","audio_base_64"],"description":"A chunk of audio to be translated.","title":"inputAudioChunk","additionalProperties":false},"endOfStream":{"type":"object","properties":{"message_type":{"type":"string","enum":["end_of_stream"],"description":"The message type identifier."}},"required":["message_type"],"description":"Signal that the client has finished sending audio.","title":"endOfStream","additionalProperties":false},"V1TranslationRealtimePublish":{"oneOf":[{"$ref":"#/$defs/inputAudioChunk"},{"$ref":"#/$defs/endOfStream"}],"title":"V1TranslationRealtimePublish"}}}},"fixedParameters":{},"mappings":[],"billingMode":"SKU","billingRule":{"mode":"SKU","meterType":"PER_CHAR","chargeType":"AUDIO","preHold":true,"priceCurrency":"USD","exchangeRateToCny":null,"matchStrategy":"FIRST_HIT","params":[],"skus":[{"skuCode":"ws_text_to_dialogue_stream_input","skuName":"实时对话","remark":"按字符计价，上游用量只退不补","enabled":true,"priority":1,"match":{},"meterType":"PER_CHAR","pricePerChar":0.00004}],"settleRule":{"settleMode":"REFUND_ONLY","usageSource":"PROVIDER_USAGE","allowRefund":true,"allowExtraCharge":false}}}',0,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='eleven_v4_turbo' AND p.provider_code='elevenlabs' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_protocol_binding x WHERE x.model_id=m.id AND x.capability_code='ws_text_to_dialogue_stream_input' AND x.binding_code='official');
