SELECT m.id,'post_music','text_to_music','{"code":"post_music","label":"音乐作曲","generateMode":"text_to_music","enabled":true,"defaultCapability":true,"evidenceStatus":"VERIFIED","sourceUrls":["https://elevenlabs.io/docs/api-reference"],"parameters":[{"name":"options","label":"官方参数","type":"object","properties":[{"name":"prompt","label":"prompt","type":"string","description":"A simple text prompt to generate a song from. Cannot be used in conjunction with `composition_plan`.","required":false,"maximum":4100,"widget":"textarea"},{"name":"composition_plan","label":"MusicPrompt","type":"object","description":"A detailed composition plan to guide music generation. Cannot be used in conjunction with `prompt`.","required":false,"properties":[{"name":"positive_global_styles","label":"positive_global_styles","type":"array","description":"The styles and musical directions that should be present in the entire song. Use English language for best result.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"negative_global_styles","label":"negative_global_styles","type":"array","description":"The styles and musical directions that should not be present in the entire song. Use English language for best result.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"sections","label":"sections","type":"array","description":"The sections of the song.","required":true,"items":{"name":"item","label":"SongSection","type":"object","required":false,"properties":[{"name":"section_name","label":"section_name","type":"string","description":"The name of the section. Must be between 1 and 100 characters.","required":true,"minimum":1,"maximum":100,"widget":"textarea"},{"name":"positive_local_styles","label":"positive_local_styles","type":"array","description":"The styles and musical directions that should be present in this section. Use English language for best result.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"negative_local_styles","label":"negative_local_styles","type":"array","description":"The styles and musical directions that should not be present in this section. Use English language for best result.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"duration_ms","label":"duration_ms","type":"integer","description":"The duration of the section in milliseconds. Must be between 3000ms and 120000ms.","required":true,"minimum":3000,"maximum":120000},{"name":"lines","label":"lines","type":"array","description":"The lyrics of the section. Max 30 lines per section and max 200 characters per line.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"maximum":200,"widget":"textarea"}},{"name":"source_from","label":"SectionSource","type":"object","required":false,"properties":[{"name":"song_id","label":"song_id","type":"string","description":"The ID of the song to source the section from. You can find the song ID in the response headers when you generate a song.","required":true,"minimum":1,"maximum":100,"widget":"textarea"},{"name":"range","label":"TimeRange","type":"object","required":true,"properties":[{"name":"start_ms","label":"start_ms","type":"integer","required":true},{"name":"end_ms","label":"end_ms","type":"integer","required":true}]},{"name":"negative_ranges","label":"negative_ranges","type":"array","description":"The ranges to exclude from the ''range''.","required":false,"items":{"name":"item","label":"TimeRange","type":"object","required":false,"properties":[{"name":"start_ms","label":"start_ms","type":"integer","required":true},{"name":"end_ms","label":"end_ms","type":"integer","required":true}]}}]}]}}],"alternatives":[{"name":"composition_plan","label":"MusicPrompt","type":"object","description":"Composition plan for the `music_v1` model. Using this field with any other model will result in an error.","required":false,"properties":[{"name":"positive_global_styles","label":"positive_global_styles","type":"array","description":"The styles and musical directions that should be present in the entire song. Use English language for best result.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"negative_global_styles","label":"negative_global_styles","type":"array","description":"The styles and musical directions that should not be present in the entire song. Use English language for best result.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"sections","label":"sections","type":"array","description":"The sections of the song.","required":true,"items":{"name":"item","label":"SongSection","type":"object","required":false,"properties":[{"name":"section_name","label":"section_name","type":"string","description":"The name of the section. Must be between 1 and 100 characters.","required":true,"minimum":1,"maximum":100,"widget":"textarea"},{"name":"positive_local_styles","label":"positive_local_styles","type":"array","description":"The styles and musical directions that should be present in this section. Use English language for best result.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"negative_local_styles","label":"negative_local_styles","type":"array","description":"The styles and musical directions that should not be present in this section. Use English language for best result.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"duration_ms","label":"duration_ms","type":"integer","description":"The duration of the section in milliseconds. Must be between 3000ms and 120000ms.","required":true,"minimum":3000,"maximum":120000},{"name":"lines","label":"lines","type":"array","description":"The lyrics of the section. Max 30 lines per section and max 200 characters per line.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"maximum":200,"widget":"textarea"}},{"name":"source_from","label":"SectionSource","type":"object","required":false,"properties":[{"name":"song_id","label":"song_id","type":"string","description":"The ID of the song to source the section from. You can find the song ID in the response headers when you generate a song.","required":true,"minimum":1,"maximum":100,"widget":"textarea"},{"name":"range","label":"TimeRange","type":"object","required":true,"properties":[{"name":"start_ms","label":"start_ms","type":"integer","required":true},{"name":"end_ms","label":"end_ms","type":"integer","required":true}]},{"name":"negative_ranges","label":"negative_ranges","type":"array","description":"The ranges to exclude from the ''range''.","required":false,"items":{"name":"item","label":"TimeRange","type":"object","required":false,"properties":[{"name":"start_ms","label":"start_ms","type":"integer","required":true},{"name":"end_ms","label":"end_ms","type":"integer","required":true}]}}]}]}}]},{"name":"composition_plan","label":"CompositionPlan","type":"object","description":"Composition plan for the `music_v2` and `music_v2_5` models. Using this field with any other model will result in an error.","required":false,"properties":[{"name":"chunks","label":"chunks","type":"array","description":"The chunks that make up the generation.","required":true,"items":{"name":"item","label":"GenerationChunk-Input","type":"object","required":false,"properties":[{"name":"text","label":"text","type":"string","description":"The text config to be generated for this chunk. Can contain an optional section name in square brackets at the beginning, e.g. [Verse 1], lyrics lines, and inline directions in curly braces, e.g. {scratching}. Section names must be between 1 and 100 characters. At most 30 lines are allowed, each at most 200 characters.","required":true,"maximum":6132,"widget":"textarea"},{"name":"duration_ms","label":"duration_ms","type":"integer","description":"The duration of the chunk in milliseconds. Must be between 3000ms and 120000ms.","required":true,"minimum":3000,"maximum":120000},{"name":"positive_styles","label":"positive_styles","type":"array","description":"The styles and musical directions that should be present in this chunk. Use English language for best results. The styles for the first chunk are the most important as they set the overall tone and genre. Styles for subsequent chunks can be used to add nuance, progression, emphasis, or change the direction of the song. Aim to have at least 6-7 styles in early chunks until the direction is established. Generic styles like ''great production quality'' are good default styles to append to the list.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"negative_styles","label":"negative_styles","type":"array","description":"The styles and musical directions that should not be present in this chunk. Use English language for best results. Leaving empty is a good default, only use this field if you want to explicitly avoid a particular style or direction.","required":false,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"context_adherence","label":"GenerationChunkInputContextAdherence","type":"string","description":"How much the model adheres to the context of its surrounding chunks. Low adherence means the model can deviate from the context and be more creative. High adherence means the model will be more consistent with the context.","required":false,"choices":["low","medium","high"],"widget":"textarea"},{"name":"conditioning_ref","label":"AudioRefChunk","type":"object","required":false,"properties":[{"name":"song_id","label":"song_id","type":"string","description":"The ID of the song to source the chunk from. You can find the song ID in the response headers when you generate a song.","required":true,"minimum":1,"maximum":100,"widget":"textarea"},{"name":"range","label":"TimeRange","type":"object","required":true,"properties":[{"name":"start_ms","label":"start_ms","type":"integer","required":true},{"name":"end_ms","label":"end_ms","type":"integer","required":true}]}]},{"name":"condition_strength","label":"ConditionStrength","type":"string","required":false,"choices":["low","medium","high","xhigh"],"widget":"textarea"}],"alternatives":[{"name":"item","label":"GenerationChunk-Input","type":"object","required":false,"properties":[{"name":"text","label":"text","type":"string","description":"The text config to be generated for this chunk. Can contain an optional section name in square brackets at the beginning, e.g. [Verse 1], lyrics lines, and inline directions in curly braces, e.g. {scratching}. Section names must be between 1 and 100 characters. At most 30 lines are allowed, each at most 200 characters.","required":true,"maximum":6132,"widget":"textarea"},{"name":"duration_ms","label":"duration_ms","type":"integer","description":"The duration of the chunk in milliseconds. Must be between 3000ms and 120000ms.","required":true,"minimum":3000,"maximum":120000},{"name":"positive_styles","label":"positive_styles","type":"array","description":"The styles and musical directions that should be present in this chunk. Use English language for best results. The styles for the first chunk are the most important as they set the overall tone and genre. Styles for subsequent chunks can be used to add nuance, progression, emphasis, or change the direction of the song. Aim to have at least 6-7 styles in early chunks until the direction is established. Generic styles like ''great production quality'' are good default styles to append to the list.","required":true,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"negative_styles","label":"negative_styles","type":"array","description":"The styles and musical directions that should not be present in this chunk. Use English language for best results. Leaving empty is a good default, only use this field if you want to explicitly avoid a particular style or direction.","required":false,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"context_adherence","label":"GenerationChunkInputContextAdherence","type":"string","description":"How much the model adheres to the context of its surrounding chunks. Low adherence means the model can deviate from the context and be more creative. High adherence means the model will be more consistent with the context.","required":false,"choices":["low","medium","high"],"widget":"textarea"},{"name":"conditioning_ref","label":"AudioRefChunk","type":"object","required":false,"properties":[{"name":"song_id","label":"song_id","type":"string","description":"The ID of the song to source the chunk from. You can find the song ID in the response headers when you generate a song.","required":true,"minimum":1,"maximum":100,"widget":"textarea"},{"name":"range","label":"TimeRange","type":"object","required":true,"properties":[{"name":"start_ms","label":"start_ms","type":"integer","required":true},{"name":"end_ms","label":"end_ms","type":"integer","required":true}]}]},{"name":"condition_strength","label":"ConditionStrength","type":"string","required":false,"choices":["low","medium","high","xhigh"],"widget":"textarea"}]},{"name":"item","label":"AudioRefChunk","type":"object","required":false,"properties":[{"name":"song_id","label":"song_id","type":"string","description":"The ID of the song to source the chunk from. You can find the song ID in the response headers when you generate a song.","required":true,"minimum":1,"maximum":100,"widget":"textarea"},{"name":"range","label":"TimeRange","type":"object","required":true,"properties":[{"name":"start_ms","label":"start_ms","type":"integer","required":true},{"name":"end_ms","label":"end_ms","type":"integer","required":true}]}]}]}}]}]},{"name":"music_length_ms","label":"music_length_ms","type":"integer","description":"The length of the song to generate in milliseconds. Used only in conjunction with `prompt`. Must be between 3000ms and 600000ms. Optional - if not provided, the model will choose a length based on the prompt.","required":false,"minimum":3000,"maximum":600000},{"name":"seed","label":"seed","type":"integer","description":"Random seed to initialize the music generation process. Providing the same seed with the same parameters can help achieve more consistent results, but exact reproducibility is not guaranteed and outputs may change across system updates. Cannot be used in conjunction with prompt.","required":false,"minimum":0,"maximum":2147483647},{"name":"force_instrumental","label":"force_instrumental","type":"boolean","description":"If true, guarantees that the generated song will be instrumental. If false, the song may or may not be instrumental depending on the `prompt`. Can only be used with `prompt`.","required":false},{"name":"finetune_id","label":"finetune_id","type":"string","description":"The ID of the finetune to use for the generation","required":false,"maximum":100,"widget":"textarea"},{"name":"respect_sections_durations","label":"respect_sections_durations","type":"boolean","description":"Controls how strictly section durations in the `composition_plan` are enforced. Only used with `composition_plan` and only applies to `music_v1`; for `music_v2` and `music_v2_5` section durations are always enforced and this is ignored. When false for `music_v1`, the model may adjust individual section durations for better quality and latency, while preserving the total song duration from the plan.","required":false},{"name":"store_for_inpainting","label":"store_for_inpainting","type":"boolean","description":"Whether to store the generated song for inpainting.","required":false},{"name":"sign_with_c2pa","label":"sign_with_c2pa","type":"boolean","description":"Whether to sign the generated song with C2PA. Applicable only for mp3 files.","required":false},{"name":"queryParameters","label":"queryParameters","type":"object","required":false,"properties":[{"name":"output_format","label":"V1MusicPostParametersOutputFormat","type":"string","required":false,"choices":["auto","mp3_48000_128","mp3_48000_192","mp3_48000_240","mp3_48000_320","mp3_22050_32","mp3_24000_48","mp3_44100_32","mp3_44100_64","mp3_44100_96","mp3_44100_128","mp3_44100_192","pcm_8000","pcm_16000","pcm_22050","pcm_24000","pcm_32000","pcm_44100","pcm_48000","ulaw_8000","alaw_8000","opus_48000_32","opus_48000_64","opus_48000_96","opus_48000_128","opus_48000_192"],"widget":"textarea"},{"name":"enable_logging","label":"enable_logging","type":"boolean","required":false}]}]}],"rules":[],"presentation":{"supportsTextInput":false,"maxOutputCount":1,"defaultOutputCount":1}}',0,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='music_v2_5' AND p.provider_code='elevenlabs' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_capability x WHERE x.model_id=m.id AND x.capability_code='post_music');
