SELECT m.id,'post_music','official','elevenlabs-audio','{"code":"official","protocol":"elevenlabs-audio","upstreamModel":"music_v2_5","apiSuffix":"/v1/music","defaultBinding":true,"enabled":true,"capability":{"officialAudioOperation":"elevenlabs.post.music","ttsTextRequired":false,"ttsVoiceRequired":false,"audioOperation":"official_audio","officialRequestSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"prompt":{"type":["string","null"],"maxLength":4100,"description":"A simple text prompt to generate a song from. Cannot be used in conjunction with `composition_plan`."},"composition_plan":{"oneOf":[{"$ref":"#/$defs/BodyComposeMusicV1MusicPostCompositionPlan"},{"type":"null"}],"description":"A detailed composition plan to guide music generation. Cannot be used in conjunction with `prompt`."},"music_length_ms":{"type":["integer","null"],"minimum":3000,"maximum":600000,"description":"The length of the song to generate in milliseconds. Used only in conjunction with `prompt`. Must be between 3000ms and 600000ms. Optional - if not provided, the model will choose a length based on the prompt."},"model_id":{"$ref":"#/$defs/MusicModelID","default":"music_v1","description":"The model to use for the generation."},"seed":{"type":["integer","null"],"minimum":0,"maximum":2147483647,"description":"Random seed to initialize the music generation process. Providing the same seed with the same parameters can help achieve more consistent results, but exact reproducibility is not guaranteed and outputs may change across system updates. Cannot be used in conjunction with prompt."},"force_instrumental":{"type":"boolean","default":false,"description":"If true, guarantees that the generated song will be instrumental. If false, the song may or may not be instrumental depending on the `prompt`. Can only be used with `prompt`."},"finetune_id":{"type":["string","null"],"maxLength":100,"description":"The ID of the finetune to use for the generation"},"respect_sections_durations":{"type":"boolean","default":true,"description":"Controls how strictly section durations in the `composition_plan` are enforced. Only used with `composition_plan` and only applies to `music_v1`; for `music_v2` and `music_v2_5` section durations are always enforced and this is ignored. When false for `music_v1`, the model may adjust individual section durations for better quality and latency, while preserving the total song duration from the plan."},"store_for_inpainting":{"type":"boolean","default":false,"description":"Whether to store the generated song for inpainting."},"sign_with_c2pa":{"type":"boolean","default":false,"description":"Whether to sign the generated song with C2PA. Applicable only for mp3 files."},"queryParameters":{"type":"object","properties":{"output_format":{"$ref":"#/$defs/V1MusicPostParametersOutputFormat","default":"auto"},"enable_logging":{"type":"boolean","default":true}},"additionalProperties":false}},"title":"Body_Compose_music_v1_music_post","additionalProperties":false,"$defs":{"BodyComposeMusicV1MusicPostCompositionPlan":{"oneOf":[{"$ref":"#/$defs/MusicPrompt"},{"$ref":"#/$defs/CompositionPlan"}],"description":"A detailed composition plan to guide music generation. Cannot be used in conjunction with `prompt`.","title":"BodyComposeMusicV1MusicPostCompositionPlan"},"MusicModelID":{"type":"string","enum":["music_v1","music_v2","music_v2_5"],"default":"music_v1","title":"MusicModelID"},"V1MusicPostParametersOutputFormat":{"type":"string","enum":["auto","mp3_48000_128","mp3_48000_192","mp3_48000_240","mp3_48000_320","mp3_22050_32","mp3_24000_48","mp3_44100_32","mp3_44100_64","mp3_44100_96","mp3_44100_128","mp3_44100_192","pcm_8000","pcm_16000","pcm_22050","pcm_24000","pcm_32000","pcm_44100","pcm_48000","ulaw_8000","alaw_8000","opus_48000_32","opus_48000_64","opus_48000_96","opus_48000_128","opus_48000_192"],"default":"auto","title":"V1MusicPostParametersOutputFormat"},"MusicPrompt":{"type":"object","properties":{"positive_global_styles":{"type":"array","items":{"type":"string"},"description":"The styles and musical directions that should be present in the entire song. Use English language for best result."},"negative_global_styles":{"type":"array","items":{"type":"string"},"description":"The styles and musical directions that should not be present in the entire song. Use English language for best result."},"sections":{"type":"array","items":{"$ref":"#/$defs/SongSection"},"description":"The sections of the song."}},"required":["positive_global_styles","negative_global_styles","sections"],"description":"Composition plan for the `music_v1` model. Using this field with any other model will result in an error.","title":"MusicPrompt","additionalProperties":false},"CompositionPlan":{"type":"object","properties":{"chunks":{"type":"array","items":{"$ref":"#/$defs/CompositionPlanChunksItems"},"description":"The chunks that make up the generation."}},"required":["chunks"],"description":"Composition plan for the `music_v2` and `music_v2_5` models. Using this field with any other model will result in an error.","title":"CompositionPlan","additionalProperties":false},"SongSection":{"type":"object","properties":{"section_name":{"type":"string","minLength":1,"maxLength":100,"description":"The name of the section. Must be between 1 and 100 characters."},"positive_local_styles":{"type":"array","items":{"type":"string"},"description":"The styles and musical directions that should be present in this section. Use English language for best result."},"negative_local_styles":{"type":"array","items":{"type":"string"},"description":"The styles and musical directions that should not be present in this section. Use English language for best result."},"duration_ms":{"type":"integer","minimum":3000,"maximum":120000,"description":"The duration of the section in milliseconds. Must be between 3000ms and 120000ms."},"lines":{"type":"array","items":{"type":"string","maxLength":200},"description":"The lyrics of the section. Max 30 lines per section and max 200 characters per line."},"source_from":{"oneOf":[{"$ref":"#/$defs/SectionSource"},{"type":"null"}],"description":"Optional source to extract the section from. Used for inpainting."}},"required":["section_name","positive_local_styles","negative_local_styles","duration_ms","lines"],"title":"SongSection","additionalProperties":false},"CompositionPlanChunksItems":{"oneOf":[{"$ref":"#/$defs/GenerationChunk-Input"},{"$ref":"#/$defs/AudioRefChunk"}],"title":"CompositionPlanChunksItems"},"SectionSource":{"type":"object","properties":{"song_id":{"type":"string","minLength":1,"maxLength":100,"description":"The ID of the song to source the section from. You can find the song ID in the response headers when you generate a song."},"range":{"$ref":"#/$defs/TimeRange","description":"The range to extract from the source song."},"negative_ranges":{"type":"array","items":{"$ref":"#/$defs/TimeRange"},"description":"The ranges to exclude from the ''range''."}},"required":["song_id","range"],"title":"SectionSource","additionalProperties":false},"GenerationChunk-Input":{"type":"object","properties":{"text":{"type":"string","maxLength":6132,"description":"The text config to be generated for this chunk. Can contain an optional section name in square brackets at the beginning, e.g. [Verse 1], lyrics lines, and inline directions in curly braces, e.g. {scratching}. Section names must be between 1 and 100 characters. At most 30 lines are allowed, each at most 200 characters."},"duration_ms":{"type":"integer","minimum":3000,"maximum":120000,"description":"The duration of the chunk in milliseconds. Must be between 3000ms and 120000ms."},"positive_styles":{"type":"array","items":{"type":"string"},"description":"The styles and musical directions that should be present in this chunk. Use English language for best results. The styles for the first chunk are the most important as they set the overall tone and genre. Styles for subsequent chunks can be used to add nuance, progression, emphasis, or change the direction of the song. Aim to have at least 6-7 styles in early chunks until the direction is established. Generic styles like ''great production quality'' are good default styles to append to the list."},"negative_styles":{"type":"array","items":{"type":"string"},"description":"The styles and musical directions that should not be present in this chunk. Use English language for best results. Leaving empty is a good default, only use this field if you want to explicitly avoid a particular style or direction."},"context_adherence":{"$ref":"#/$defs/GenerationChunkInputContextAdherence","default":"high","description":"How much the model adheres to the context of its surrounding chunks. Low adherence means the model can deviate from the context and be more creative. High adherence means the model will be more consistent with the context."},"conditioning_ref":{"oneOf":[{"$ref":"#/$defs/AudioRefChunk"},{"type":"null"}],"description":"The audio reference to condition the generation on. The first chunk is the most important as it will influence the generation of all subsequent chunks. Thus, if you want to apply conditioning to the entire song, start conditioning from the first chunk."},"condition_strength":{"oneOf":[{"$ref":"#/$defs/ConditionStrength"},{"type":"null"}],"description":"How strongly the model adheres to the conditioning reference. Low strength means the model will be more creative and deviate from the reference. High strength means the model will be more consistent with the reference."}},"required":["text","duration_ms","positive_styles"],"title":"GenerationChunk-Input","additionalProperties":false},"AudioRefChunk":{"type":"object","properties":{"song_id":{"type":"string","minLength":1,"maxLength":100,"description":"The ID of the song to source the chunk from. You can find the song ID in the response headers when you generate a song."},"range":{"$ref":"#/$defs/TimeRange","description":"The time range to extract from the song."}},"required":["song_id","range"],"title":"AudioRefChunk","additionalProperties":false},"TimeRange":{"type":"object","properties":{"start_ms":{"type":"integer"},"end_ms":{"type":"integer"}},"required":["start_ms","end_ms"],"title":"TimeRange","additionalProperties":false},"GenerationChunkInputContextAdherence":{"type":"string","enum":["low","medium","high"],"default":"high","description":"How much the model adheres to the context of its surrounding chunks. Low adherence means the model can deviate from the context and be more creative. High adherence means the model will be more consistent with the context.","title":"GenerationChunkInputContextAdherence"},"ConditionStrength":{"type":"string","enum":["low","medium","high","xhigh"],"title":"ConditionStrength"}}}},"fixedParameters":{},"mappings":[],"billingMode":"SKU","billingRule":{"mode":"SKU","meterType":"PER_SECOND","chargeType":"AUDIO","preHold":true,"priceCurrency":"USD","exchangeRateToCny":null,"matchStrategy":"FIRST_HIT","params":[],"skus":[{"skuCode":"post_music","skuName":"音乐作曲","remark":"按秒计价，多版本按总时长计价","enabled":true,"priority":1,"match":{},"meterType":"PER_SECOND","pricePerSecond":0.0025}],"settleRule":{"settleMode":"REFUND_ONLY","usageSource":"PROVIDER_USAGE","allowRefund":true,"allowExtraCharge":false}}}',0,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='music_v2_5' AND p.provider_code='elevenlabs' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_protocol_binding x WHERE x.model_id=m.id AND x.capability_code='post_music' AND x.binding_code='official');
