SELECT m.id,'post_music_video_to_music','video_to_music','{"code":"post_music_video_to_music","label":"视频配乐","generateMode":"video_to_music","enabled":true,"defaultCapability":false,"evidenceStatus":"VERIFIED","sourceUrls":["https://elevenlabs.io/docs/api-reference"],"parameters":[{"name":"options","label":"官方参数","type":"object","properties":[{"name":"videos","label":"videos","type":"array","description":"\\n            One or more video files sent via FormData array (multipart/form-data). They will be combined into one codec in order.\\n            A maximum of 10 videos is allowed, where the total size of the combined video is limited to 200MB.\\n            In total, the video can be up to 600 seconds long. Note that combining multiple videos may increase the request duration significantly. If possible, combine the videos beforehand.\\n            ","required":true,"minimum":1,"maximum":10,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"input"}},{"name":"description","label":"description","type":"string","description":"Optional text description of the music you want. A maximum of 4100 characters is allowed.","required":false,"minimum":1,"maximum":4100,"widget":"textarea"},{"name":"tags","label":"tags","type":"array","description":"Optional list of style tags (e.g. [''upbeat'', ''cinematic'']). A maximum of 10 tags is allowed.","required":false,"maximum":10,"items":{"name":"item","label":"item","type":"string","required":false,"widget":"textarea"}},{"name":"add_sfx","label":"add_sfx","type":"boolean","description":"When true, incorporate SFX cues from the video.","required":false},{"name":"separate_tracks","label":"separate_tracks","type":"boolean","description":"When true, return a ZIP with separate music and SFX audio tracks instead of a single mixed file. Use this for more flexibility to layer the tracks.","required":false},{"name":"use_audio_as_reference","label":"use_audio_as_reference","type":"boolean","description":"When true, analyze the video''s audio track and use its genres, BPM, instrumentation, mood, and arc as reference characteristics for music generation.","required":false},{"name":"sign_with_c2pa","label":"sign_with_c2pa","type":"boolean","description":"Whether to sign the generated song with C2PA. Applicable only for mp3 files.","required":false},{"name":"queryParameters","label":"queryParameters","type":"object","required":false,"properties":[{"name":"output_format","label":"AllowedOutputFormats","type":"string","required":false,"choices":["mp3_22050_32","mp3_24000_48","mp3_44100_32","mp3_44100_64","mp3_44100_96","mp3_44100_128","mp3_44100_192","pcm_8000","pcm_16000","pcm_22050","pcm_24000","pcm_32000","pcm_44100","pcm_48000","ulaw_8000","alaw_8000","opus_48000_32","opus_48000_64","opus_48000_96","opus_48000_128","opus_48000_192"],"widget":"textarea"},{"name":"enable_logging","label":"enable_logging","type":"boolean","required":false}]}]}],"rules":[],"presentation":{"supportsTextInput":false,"maxOutputCount":1,"defaultOutputCount":1}}',1,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='music_v2_5' AND p.provider_code='elevenlabs' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_capability x WHERE x.model_id=m.id AND x.capability_code='post_music_video_to_music');
