SELECT m.id,'post_video_to_music','video_to_music','{"code":"post_video_to_music","label":"视频生成音乐","generateMode":"video_to_music","enabled":true,"defaultCapability":false,"evidenceStatus":"PARTIAL","sourceUrls":["https://platform.sonilo.com/openapi.json"],"parameters":[{"name":"options","label":"官方参数","type":"object","properties":[{"name":"video","label":"video","type":"string","description":"Max file size: default 300MB. Max duration: 6 minutes.","required":false,"widget":"input"},{"name":"video_url","label":"video_url","type":"string","description":"Max file size: default 300MB. Max duration: 6 minutes.","required":false,"widget":"textarea"},{"name":"prompt","label":"prompt","type":"string","required":false,"maximum":2000,"widget":"textarea"},{"name":"segments","label":"segments","type":"string","required":false,"widget":"textarea"},{"name":"mode","label":"mode","type":"string","required":false,"choices":["stream","async"],"widget":"textarea"},{"name":"output_format","label":"output_format","type":"string","description":"`m4a` (default, AAC), `wav` (16-bit PCM) or `mp3` (320 kbps CBR). Applies to `audio`, to the `ducked` track when ducking ran, to the `mux` track when `preserve_speech` is used, and normally to every entry in `stems` (each stem''s `content_type` reports what was actually delivered); the isolated `vocals` stem `preserve_speech` returns is unaffected. `wav` and `mp3` are transcoded server-side after generation and require mode=async — the streaming response is always m4a. The delivered MIME is echoed in `audio[].content_type`.","required":false,"choices":["m4a","wav","mp3"],"widget":"textarea"},{"name":"preserve_speech","label":"preserve_speech","type":"boolean","required":false},{"name":"ducking","label":"ducking","type":"boolean","description":"Off by default. Set to true to also return a `ducked` audio track — the generated music dipped under the video''s speech so dialogue stays intelligible — alongside the clean `audio`. Free of charge. Requires mode=async.","required":false},{"name":"prompt_influence","label":"prompt_influence","type":"number","description":"How strongly the generated music follows the prompt: lower values let the video lead, higher values follow the prompt more literally. Omit to keep the default behavior. Free of charge.","required":false,"minimum":0,"maximum":1},{"name":"variants_num","label":"variants_num","type":"integer","description":"How many distinct music variants to generate in one request. Each variant is a separate creative direction, returned as its own entry in the async result''s `audio` array. Cost scales linearly — `variants_num=3` costs three times a single-variant request. Values above 1 require mode=async; the default of 1 is valid in stream mode. Values above 1 are never covered by the free trial and are always billed.","required":false,"minimum":1,"maximum":10},{"name":"stems","label":"stems","type":"boolean","description":"Off by default. Set to true to also return a `stems` array — the generated music split into four separated instrument tracks (`drums`, `bass`, `vocals`, `other`), each normally following the requested `output_format`, with `content_type` reporting what was actually delivered — alongside the clean `audio`. It splits the generated music, never the video''s own audio. Free of charge. Requires mode=async. Separation runs after generation and typically adds 2-6 min to the wait and gives up after 30 min; that ceiling is reached by a retry or a busy queue rather than by track length, so do not size a client timeout off the duration. It never fails the task: if separation fails, `audio` is unaffected and the response carries `stems_error` — on its own, or alongside the streams that did separate.","required":false}]}],"rules":[],"presentation":{"supportsTextInput":false,"maxOutputCount":10,"defaultOutputCount":1}}',1,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='sonilo-music-api' AND p.provider_code='sonilo' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_capability x WHERE x.model_id=m.id AND x.capability_code='post_video_to_music');
INSERT INTO aid_ai_model_protocol_binding(model_id,capability_code,binding_code,protocol,definition_json,sort_order,create_time,create_by)
SELECT m.id,'post_video_to_music','official','sonilo-audio','{"code":"official","protocol":"sonilo-audio","upstreamModel":"sonilo-music-api","apiSuffix":"/v1/video-to-music","defaultBinding":true,"enabled":true,"capability":{"officialAudioOperation":"sonilo.post.video_to_music","ttsTextRequired":false,"ttsVoiceRequired":false,"audioOperation":"official_audio","officialRequestSchema":{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","properties":{"video":{"type":"string","format":"binary","description":"Max file size: default 300MB. Max duration: 6 minutes."},"video_url":{"type":"string","description":"Max file size: default 300MB. Max duration: 6 minutes.","format":"uri"},"prompt":{"type":"string","maxLength":2000},"segments":{"type":"string"},"mode":{"type":"string","enum":["stream","async"],"default":"stream"},"output_format":{"type":"string","enum":["m4a","wav","mp3"],"default":"m4a","description":"`m4a` (default, AAC), `wav` (16-bit PCM) or `mp3` (320 kbps CBR). Applies to `audio`, to the `ducked` track when ducking ran, to the `mux` track when `preserve_speech` is used, and normally to every entry in `stems` (each stem''s `content_type` reports what was actually delivered); the isolated `vocals` stem `preserve_speech` returns is unaffected. `wav` and `mp3` are transcoded server-side after generation and require mode=async — the streaming response is always m4a. The delivered MIME is echoed in `audio[].content_type`."},"preserve_speech":{"type":"boolean"},"ducking":{"type":"boolean","default":false,"description":"Off by default. Set to true to also return a `ducked` audio track — the generated music dipped under the video''s speech so dialogue stays intelligible — alongside the clean `audio`. Free of charge. Requires mode=async."},"prompt_influence":{"type":"number","minimum":0,"maximum":1,"default":0.5,"description":"How strongly the generated music follows the prompt: lower values let the video lead, higher values follow the prompt more literally. Omit to keep the default behavior. Free of charge."},"variants_num":{"type":"integer","minimum":1,"maximum":10,"default":1,"description":"How many distinct music variants to generate in one request. Each variant is a separate creative direction, returned as its own entry in the async result''s `audio` array. Cost scales linearly — `variants_num=3` costs three times a single-variant request. Values above 1 require mode=async; the default of 1 is valid in stream mode. Values above 1 are never covered by the free trial and are always billed."},"stems":{"type":"boolean","default":false,"description":"Off by default. Set to true to also return a `stems` array — the generated music split into four separated instrument tracks (`drums`, `bass`, `vocals`, `other`), each normally following the requested `output_format`, with `content_type` reporting what was actually delivered — alongside the clean `audio`. It splits the generated music, never the video''s own audio. Free of charge. Requires mode=async. Separation runs after generation and typically adds 2-6 min to the wait and gives up after 30 min; that ceiling is reached by a retry or a busy queue rather than by track length, so do not size a client timeout off the duration. It never fails the task: if separation fails, `audio` is unaffected and the response carries `stems_error` — on its own, or alongside the streams that did separate."}},"additionalProperties":false,"$defs":{}}},"fixedParameters":{},"mappings":[],"billingMode":"SKU","billingRule":{"mode":"SKU","meterType":"PER_SECOND","chargeType":"AUDIO","preHold":true,"priceCurrency":"USD","exchangeRateToCny":null,"matchStrategy":"FIRST_HIT","params":[],"skus":[{"skuCode":"post_video_to_music","skuName":"视频生成音乐","remark":"按秒计价，多版本按总时长计价","enabled":true,"priority":1,"match":{},"meterType":"PER_SECOND","pricePerSecond":0.009}],"settleRule":{"settleMode":"REFUND_ONLY","usageSource":"PROVIDER_USAGE","allowRefund":true,"allowExtraCharge":false}},"taskQuerySuffix":"/v1/tasks/%s"}',0,NOW(),'system' FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='sonilo-music-api' AND p.provider_code='sonilo' AND NOT EXISTS(SELECT 1 FROM aid_ai_model_protocol_binding x WHERE x.model_id=m.id AND x.capability_code='post_video_to_music' AND x.binding_code='official');
-- Remove platform administration operations from native audio model capabilities.
DELETE b FROM aid_ai_model_protocol_binding b JOIN aid_ai_model m ON m.id=b.model_id JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='mureka-9.5' AND p.provider_code='mureka' AND b.capability_code IN('post_files_upload','post_song_vocal_clone','post_song_recognize','post_song_describe','post_song_transcribe','post_lyrics_video_generate') AND JSON_UNQUOTE(JSON_EXTRACT(b.definition_json,'$.capability.officialAudioOperation')) LIKE 'mureka.%';
DELETE c FROM aid_ai_model_capability c JOIN aid_ai_model m ON m.id=c.model_id JOIN aid_ai_provider p ON p.id=m.provider_id WHERE m.model_code='mureka-9.5' AND p.provider_code='mureka' AND c.capability_code IN('post_files_upload','post_song_vocal_clone','post_song_recognize','post_song_describe','post_song_transcribe','post_lyrics_video_generate') AND NOT EXISTS(SELECT 1 FROM aid_ai_model_protocol_binding b WHERE b.model_id=c.model_id AND b.capability_code=c.capability_code);
