-- Audio business catalog: retain administrator configuration and append native audio model bindings.
SET NAMES utf8mb4 COLLATE utf8mb4_general_ci;
DROP TEMPORARY TABLE IF EXISTS tmp_aid_audio_business_models;
CREATE TEMPORARY TABLE tmp_aid_audio_business_models (model_id BIGINT PRIMARY KEY);
INSERT IGNORE INTO tmp_aid_audio_business_models
SELECT DISTINCT m.id FROM aid_ai_model m
JOIN aid_ai_model_protocol_binding b ON b.model_id=m.id
WHERE m.model_type='audio' AND m.del_flag='0'
  AND b.protocol IN ('mureka-audio','seed-audio','minimax-music','elevenlabs-audio','sonilo-audio')
  AND JSON_VALID(b.definition_json)=1
  AND JSON_EXTRACT(b.definition_json,'$.capability.officialAudioOperation') IS NOT NULL;
SET @aid_audio_pool_created := NOT EXISTS(SELECT 1 FROM aid_ai_model_func_config WHERE func_code='canvas.audio.generate');
INSERT INTO aid_ai_model_func_config
 (func_name,func_code,model_type,generate_mode,model_ids,status,remark,create_by,create_time,update_by,update_time,del_flag)
SELECT '音频创作','canvas.audio.generate','audio',NULL,JSON_ARRAY(),'0',
 '音频节点使用的模型与能力；价格、权限及有效状态由模型配置控制','system',NOW(),'system',NOW(),'0'
FROM DUAL WHERE NOT EXISTS(SELECT 1 FROM aid_ai_model_func_config WHERE func_code='canvas.audio.generate');
DROP PROCEDURE IF EXISTS aid_append_audio_business_models;
DELIMITER $$
CREATE PROCEDURE aid_append_audio_business_models()
BEGIN
 DECLARE done INT DEFAULT 0;
 DECLARE model_id_value BIGINT;
 DECLARE pool_id BIGINT;
 DECLARE pool_models JSON;
 DECLARE cur CURSOR FOR SELECT model_id FROM tmp_aid_audio_business_models ORDER BY model_id;
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET done=1;
 SELECT id,model_ids INTO pool_id,pool_models FROM aid_ai_model_func_config WHERE func_code='canvas.audio.generate' AND del_flag='0' LIMIT 1;
 IF pool_id IS NOT NULL AND @aid_audio_pool_created=1 THEN
  OPEN cur;
  read_loop: LOOP
   FETCH cur INTO model_id_value;
   IF done=1 THEN LEAVE read_loop; END IF;
   IF JSON_CONTAINS(pool_models,CAST(model_id_value AS JSON),'$')=0 THEN
    SET pool_models=JSON_ARRAY_APPEND(pool_models,'$',model_id_value);
   END IF;
  END LOOP;
  CLOSE cur;
  UPDATE aid_ai_model_func_config SET model_ids=pool_models,update_by='system',update_time=NOW() WHERE id=pool_id AND NOT(model_ids <=> pool_models);
 END IF;
END$$
DELIMITER ;
CALL aid_append_audio_business_models();
DROP PROCEDURE aid_append_audio_business_models;
INSERT INTO aid_ai_business_model_binding
 (func_code,model_id,capability_code,default_capability,defaults_json,sort_order,create_by,create_time,update_by,update_time,remark)
SELECT 'canvas.audio.generate',c.model_id,c.capability_code,
 IF(JSON_EXTRACT(c.definition_json,'$.defaultCapability')=true OR c.capability_code='post_music_generation',1,0),NULL,c.sort_order,'system',NOW(),'system',NOW(),'音频创作能力绑定'
FROM aid_ai_model_capability c JOIN tmp_aid_audio_business_models m ON m.model_id=c.model_id
WHERE JSON_EXTRACT(c.definition_json,'$.enabled')=true
 AND EXISTS (SELECT 1 FROM aid_ai_model_protocol_binding route WHERE route.model_id=c.model_id AND route.capability_code=c.capability_code AND JSON_VALID(route.definition_json)=1 AND JSON_EXTRACT(route.definition_json,'$.capability.officialAudioOperation') IS NOT NULL)
 AND EXISTS (SELECT 1 FROM aid_ai_model_func_config f WHERE f.func_code='canvas.audio.generate' AND f.del_flag='0' AND JSON_CONTAINS(f.model_ids,CAST(c.model_id AS JSON),'$')=1)
 AND NOT EXISTS (SELECT 1 FROM aid_ai_business_model_binding existing WHERE existing.func_code='canvas.audio.generate' AND existing.model_id=c.model_id AND existing.capability_code=c.capability_code);
DROP TEMPORARY TABLE tmp_aid_audio_business_models;


-- 助手入口属于会话，同一服务同时提供普通入口与工作区入口。
SET @aid_entry_ddl = IF(EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='aid_chat_session' AND column_name='entry_transport'), 'SELECT 1', 'ALTER TABLE aid_chat_session ADD COLUMN entry_transport varchar(16) DEFAULT NULL COMMENT ''助手入口 MAIN/CANVAS，NULL 为历史兼容'' AFTER session_type');
PREPARE aid_entry_stmt FROM @aid_entry_ddl;
EXECUTE aid_entry_stmt;
DEALLOCATE PREPARE aid_entry_stmt;
-- 兼容既有客户端：工作区会话及空间预演会话归为 CANVAS，其余归为 MAIN。
-- 显式记录过的入口不重新推断，不修改消息、上下文、运行或计费数据。
UPDATE aid_chat_session SET entry_transport=CASE WHEN workspace_id > 0 OR module_code='SPATIAL_PREVIS' THEN 'CANVAS' ELSE 'MAIN' END WHERE session_type='ASSISTANT' AND entry_transport IS NULL;
SET @aid_entry_ddl = IF(EXISTS(SELECT 1 FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='aid_chat_session' AND index_name='idx_chat_session_entry'), 'SELECT 1', 'CREATE INDEX idx_chat_session_entry ON aid_chat_session(user_id,session_type,entry_transport,del_flag,id)');
PREPARE aid_entry_stmt FROM @aid_entry_ddl;
EXECUTE aid_entry_stmt;
DEALLOCATE PREPARE aid_entry_stmt;

-- 画布发布审核增量；MySQL 5.7+；重复执行不修改既有业务内容。
CREATE TABLE IF NOT EXISTS aid_canvas_publication_state (
 project_id BIGINT NOT NULL PRIMARY KEY,
 version BIGINT NOT NULL DEFAULT 0,
 published_id BIGINT NULL,
 pending_id BIGINT NULL,
 visible TINYINT NOT NULL DEFAULT 0,
 copy_enabled TINYINT NOT NULL DEFAULT 0,
 blocked TINYINT NOT NULL DEFAULT 0,
 scene_version BIGINT NOT NULL DEFAULT 0,
 scene_document_json LONGTEXT NULL,
 source_publication_id BIGINT NULL,
 root_publication_id BIGINT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS aid_canvas_publication (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 project_id BIGINT NOT NULL,
 owner_user_id BIGINT NOT NULL,
 workspace_revision BIGINT NOT NULL,
 scene_version BIGINT NOT NULL,
 operation_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 request_hash CHAR(64) NOT NULL,
 project_name VARCHAR(100) NOT NULL,
 project_desc VARCHAR(500) NOT NULL,
 video_url VARCHAR(2048) NOT NULL,
 cover_url VARCHAR(2048) NOT NULL,
 snapshot_json LONGTEXT NOT NULL,
 content_hash CHAR(64) NOT NULL,
 allow_copy TINYINT NOT NULL DEFAULT 0,
 review_status VARCHAR(16) NOT NULL DEFAULT 'PENDING',
 review_reason VARCHAR(1000) NULL,
 source_publication_id BIGINT NULL,
 root_publication_id BIGINT NULL,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_canvas_publication_operation(project_id,operation_id),
 KEY idx_canvas_publication_review(review_status,id),
 KEY idx_canvas_publication_source(source_publication_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS aid_canvas_publication_audit (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 publication_id BIGINT NULL,
 project_id BIGINT NOT NULL,
 actor VARCHAR(100) NOT NULL,
 action VARCHAR(32) NOT NULL,
 reason VARCHAR(1000) NULL,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 KEY idx_canvas_publication_audit(project_id,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS aid_canvas_publication_copy (
 id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
 user_id BIGINT NOT NULL,
 operation_id VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
 publication_id BIGINT NOT NULL,
 request_hash CHAR(64) NOT NULL,
