 request_hash CHAR(64) NOT NULL,project_name VARCHAR(100) NULL,status VARCHAR(16) NOT NULL DEFAULT 'QUEUED',worker_token CHAR(32) NULL,
 total_resources INT NOT NULL DEFAULT 0,completed_resources INT NOT NULL DEFAULT 0,total_bytes BIGINT NOT NULL DEFAULT 0,completed_bytes BIGINT NOT NULL DEFAULT 0,
 target_project_id BIGINT NULL,cancel_requested TINYINT NOT NULL DEFAULT 0,attempts INT NOT NULL DEFAULT 0,error_code VARCHAR(100) NULL,lease_until DATETIME NULL,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
