 location VARCHAR(700) NOT NULL,storage_identity CHAR(64) NOT NULL,extension VARCHAR(8) NOT NULL,status VARCHAR(16) NOT NULL DEFAULT 'STAGED',
 publication_id BIGINT NULL,project_id BIGINT NULL,attempts INT NOT NULL DEFAULT 0,expires_at DATETIME NOT NULL,next_attempt_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,update_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 PRIMARY KEY(id),KEY idx_canvas_file_scope(scope_id,id),KEY idx_canvas_file_reclaim(status,next_attempt_at,expires_at)
