-- 历史通用协议与专用协议同时标为默认时，保留专用协议为默认。
-- 不删除或停用旧绑定，不改动价格、密钥、网关或自定义协议。
UPDATE aid_ai_model_protocol_binding old_route
JOIN aid_ai_model m ON m.id=old_route.model_id AND m.del_flag='0'
JOIN aid_ai_provider p ON p.id=m.provider_id
JOIN aid_ai_model_protocol_binding dedicated ON dedicated.model_id=old_route.model_id AND dedicated.capability_code=old_route.capability_code
SET old_route.definition_json=JSON_SET(old_route.definition_json,'$.defaultBinding',JSON_EXTRACT('false','$'))
WHERE JSON_EXTRACT(old_route.definition_json,'$.defaultBinding')=TRUE
  AND JSON_EXTRACT(dedicated.definition_json,'$.defaultBinding')=TRUE
  AND JSON_EXTRACT(dedicated.definition_json,'$.enabled')=TRUE
  AND ((m.model_code='doubao-seedream-5-0-pro-260628' AND old_route.capability_code='image_layer_decomposition'
        AND old_route.binding_code='route_8' AND dedicated.binding_code='route_layer_split')
    OR (p.provider_code='volcengine' AND m.model_code='doubao-seedance-2.5'
        AND m.real_model_code='doubao-seedance-2-5-260628'
        AND old_route.protocol='seedance-video' AND dedicated.protocol='seedance-video'
        AND JSON_UNQUOTE(JSON_EXTRACT(old_route.definition_json,'$.protocol'))='seedance-video'
        AND JSON_UNQUOTE(JSON_EXTRACT(dedicated.definition_json,'$.protocol'))='seedance-video'
        AND JSON_UNQUOTE(JSON_EXTRACT(old_route.definition_json,'$.upstreamModel'))=m.real_model_code
        AND JSON_UNQUOTE(JSON_EXTRACT(dedicated.definition_json,'$.upstreamModel'))=m.real_model_code
        AND ((old_route.capability_code='text_to_video'
              AND old_route.binding_code='seedance_official_128' AND dedicated.binding_code='seedance_official_363')
          OR (old_route.capability_code='image_to_video'
              AND old_route.binding_code='seedance_official_129' AND dedicated.binding_code='seedance_official_364')
          OR (old_route.capability_code='start_end_to_video'
              AND old_route.binding_code='seedance_official_130' AND dedicated.binding_code='seedance_official_365')
          OR (old_route.capability_code='reference_to_video'
              AND old_route.binding_code='seedance_official_131' AND dedicated.binding_code='seedance_official_366')
          OR (old_route.capability_code='video_edit'
              AND old_route.binding_code='seedance_official_132' AND dedicated.binding_code='seedance_official_367')
          OR (old_route.capability_code='video_extend'
              AND old_route.binding_code='seedance_official_133' AND dedicated.binding_code='seedance_official_368'))));

-- Topaz 图片目录仅保留 Standard 2；MySQL 5.7，可重复执行。
SET NAMES utf8mb4 COLLATE utf8mb4_general_ci;
-- 供应商与模型默认停用；密钥和人民币售价须由站长在后台设置，启用前进行真实上游验证。
INSERT INTO aid_ai_provider
 (provider_name, provider_code, logo_url, base_url, api_key, auth_header, auth_prefix,
  api_key_apply_url, official_doc_url, official_price_url, task_query_suffix,
  status, del_flag, create_time, create_by, remark, supports_callback, schedule_strategy_json)
SELECT 'Topaz Labs', 'topaz', '/brand-icons/topaz.ico', 'https://api.topazlabs.com', '', 'X-API-Key', '',
 'https://www.topazlabs.com/api', 'https://developer.topazlabs.com/',
 'https://developer.topazlabs.com/getting-started/model-pricing.md',
 '/image/v1/status/%s', '1', '0', NOW(), 'system',
 '官方 Image API；按输出像素档位配置人民币 SKU 后启用，不在 SQL 中保存密钥', 0,
 '{"dispatchMode":"POLL_ONLY","supportsCallback":false,"firstPollDelaySeconds":5,"baseIntervalSeconds":5,"maxIntervalSeconds":30,"maxLifeSeconds":3600,"providerConcurrency":10,"modelConcurrency":5}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM aid_ai_provider WHERE provider_code = 'topaz');

-- Standard 2 每次输入一张图、输出一张图；输入输出均不超过 256 MP。
SET @topaz_precision_params = JSON_OBJECT(
 'deblurStrength', JSON_OBJECT('type','number','min',0,'max',1,'upstream','deblur_strength'),
 'decompressionStrength', JSON_OBJECT('type','number','min',0,'max',1,'upstream','decompression_strength'),
 'denoiseStrength', JSON_OBJECT('type','number','min',0,'max',1,'upstream','denoise_strength'),
 'opacity', JSON_OBJECT('type','number','min',0,'max',1),
 'outputFormat', JSON_OBJECT('type','string','enum',JSON_ARRAY('jpeg','jpg','png','tiff','tif'),'upstream','output_format'),
 'cropToFill', JSON_OBJECT('type','boolean','upstream','crop_to_fill'));
SET @topaz_precision_capability = JSON_OBJECT(
 'minReferenceImages',1,'maxReferenceImages',1,'referenceImageMaxPixels',256000000,
 'referenceImageFormats',JSON_ARRAY('jpeg','jpg','png','tiff','tif'),
 'maxOutputPixels',256000000,'allowCustomWH',true,'requiresConfiguredBilling',true,
 'sceneRules',JSON_OBJECT('imageUpscale',JSON_OBJECT('inputRequirement','image_required')),
 'providerParameters',CAST(@topaz_precision_params AS JSON));

INSERT INTO aid_ai_model
 (provider_id, model_code, real_model_code, model_name, model_type, generate_mode,
  api_suffix, protocol, cost_credits, billing_mode, billing_rule_json, status, del_flag,
  create_time, create_by, remark, image_refine, supports_text_input, supports_image_input,
  supports_multi_image_input, max_output_count, default_output_count, supports_size_preset, supports_aspect_ratio,
  capability_json, capability_inited, official_price_url)
SELECT p.id, catalog.code, catalog.upstream, catalog.label, 'image', 'image_upscale',
 catalog.endpoint, 'topaz-image', 0, 'SKU', NULL, '1', '0', NOW(), 'system',
 'Topaz 官方图片处理模型；未配置密钥、人民币 SKU 和实测前保持停用', 3, catalog.text_input,
 1, 0, 1, 1, 0, 0, catalog.capability, 1,
 'https://developer.topazlabs.com/getting-started/model-pricing.md'
FROM aid_ai_provider p JOIN (
 SELECT 'topaz-standard-2' code, 'Standard V2' upstream, 'Topaz Standard 2' label,
  '/image/v1/enhance/async' endpoint, 0 text_input, @topaz_precision_capability capability

) catalog ON p.provider_code = 'topaz'
WHERE NOT EXISTS (SELECT 1 FROM aid_ai_model m WHERE m.model_code = catalog.code AND m.del_flag = '0');

-- Topaz 图片按输出像素向上取整计费。参考 Developer 每 Topaz credit $0.10、
-- 估算汇率 ¥6.70/$，初始成本 ¥0.67/credit；实际售价仍乘系统统一倍率，
-- 后台可调整该单价。Standard 2 每 24 MP 输出消耗 1 credit。
-- 只补齐未定价且仍停用的模型，不覆盖运营自行配置的价格或启停。
UPDATE aid_ai_model m
JOIN aid_ai_provider p ON p.id = m.provider_id
SET m.billing_rule_json = JSON_OBJECT(
 'mode','SKU','meterType','PER_IMAGE','chargeType','IMAGE','preHold',true,
 'matchStrategy','FIRST_HIT','skus',JSON_ARRAY(JSON_OBJECT(
  'skuCode',CONCAT(UPPER(REPLACE(m.model_code,'-','_')),'_OUTPUT_MP'),
  'skuName',CONCAT(m.model_name,' 输出像素计费'),
  'enabled',true,'priority',1,'match',JSON_OBJECT(),
  'price',0.67,
  'outputPixelsPerUnit',24000000,
  'remark','初始估算：Developer $0.10/credit × ¥6.70/$；按输出像素向上取整，后台可改价'
  )))
WHERE p.provider_code = 'topaz'
  AND m.model_code = 'topaz-standard-2'
  AND m.status = '1' AND m.del_flag = '0'
  AND (m.billing_rule_json IS NULL OR TRIM(m.billing_rule_json) = '');


-- 在停止新任务接入、确认在途任务结束的维护窗口执行；不重写任务、素材、Skill 包或账本。
-- 任一有效直接绑定或在途执行仍引用待删除型号时，整个清理事务回滚并给出原因。
DELIMITER $$
DROP PROCEDURE IF EXISTS aid_cleanup_topaz_image_catalog$$
CREATE PROCEDURE aid_cleanup_topaz_image_catalog()
BEGIN
  DECLARE finished INT DEFAULT 0;
  DECLARE old_id BIGINT;
  DECLARE old_code VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
  DECLARE old_upstream VARCHAR(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
  DECLARE reason VARCHAR(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
  DECLARE retired CURSOR FOR
    SELECT m.id,m.model_code,m.real_model_code FROM aid_ai_model m
    JOIN aid_ai_provider p ON p.id=m.provider_id
    WHERE p.provider_code='topaz' AND m.model_type='image'
      AND m.model_code IN ('topaz-low-resolution-2','topaz-art-cgi','topaz-high-fidelity-3',
        'topaz-text-shapes','topaz-wonder-3-5','topaz-bloom-2') ORDER BY m.id;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET finished=1;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;
  OPEN retired;
  retire_loop: LOOP
    FETCH retired INTO old_id,old_code,old_upstream;
    IF finished=1 THEN LEAVE retire_loop; END IF;
    SET reason=NULL;

    -- 含停用但未删除配置，避免下次启用时恢复悬空引用；不擅自把不同增强语义替换为 Standard。
    IF EXISTS (SELECT 1 FROM aid_agent WHERE del_flag='0' AND model_code=old_code COLLATE utf8mb4_general_ci)
      OR EXISTS (SELECT 1 FROM aid_gen_agent_pool WHERE del_flag='0' AND model_code=old_code COLLATE utf8mb4_general_ci)
      OR EXISTS (SELECT 1 FROM aid_project_gen_config WHERE del_flag='0' AND model_code=old_code COLLATE utf8mb4_general_ci)
      OR EXISTS (SELECT 1 FROM aid_ai_voice_library WHERE del_flag='0' AND model_id=old_id)
      OR EXISTS (SELECT 1 FROM aid_role_voice_binding WHERE del_flag='0' AND model_id=old_id)
      OR EXISTS (SELECT 1 FROM aid_audio_asset WHERE del_flag='0' AND voice_model_id=old_id)
      OR EXISTS (SELECT 1 FROM aid_provider_error_rule WHERE model_code=old_code COLLATE utf8mb4_general_ci) THEN
      SET reason='Current business binding must be migrated explicitly';
    END IF;
    -- 可执行版本及活动草稿按模型字段检查，不搜索/改写提示词或不可变快照正文。
    IF EXISTS (SELECT 1 FROM aid_skill WHERE del_flag='0' AND model_code COLLATE utf8mb4_general_ci=old_code COLLATE utf8mb4_general_ci)
      OR EXISTS (SELECT 1 FROM aid_skill_version WHERE del_flag='0' AND status='0'
        AND (model_code COLLATE utf8mb4_general_ci=old_code COLLATE utf8mb4_general_ci
          OR JSON_SEARCH(IF(JSON_VALID(model_config_json),model_config_json,'{}'),'one',old_code,NULL,
            '$.defaultModelCode','$.selectableModelCodes[*]') IS NOT NULL))
      OR EXISTS (SELECT 1 FROM aid_skill_draft WHERE status='EDITING'
        AND JSON_SEARCH(IF(JSON_VALID(draft_json),draft_json,'{}'),'one',old_code,NULL,
          '$.modelCode','$.defaultModelCode','$.selectableModelCodes[*]') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM aid_runtime_agent_version WHERE del_flag='0' AND status='0'
        AND JSON_SEARCH(IF(JSON_VALID(model_config_json),model_config_json,'{}'),'one',old_code,NULL,
          '$.defaultModelCode','$.selectableModelCodes[*]') IS NOT NULL)
      OR EXISTS (SELECT 1 FROM aid_runtime_agent_draft WHERE status='EDITING'
        AND JSON_SEARCH(IF(JSON_VALID(draft_json),draft_json,'{}'),'one',old_code,NULL,
          '$.modelCode','$.defaultModelCode','$.selectableModelCodes[*]',
          '$.modelConfig.defaultModelCode','$.modelConfig.selectableModelCodes[*]') IS NOT NULL) THEN
      SET reason='Skill or Agent model binding requires a reviewed new package';
    END IF;
    -- 指向旧型号的外部别名可能仍是业务入口，不能连同该入口静默删除。
    IF EXISTS (SELECT 1 FROM aid_ai_model_alias
      WHERE model_id=old_id AND legacy_model_id<>old_id AND legacy_model_code<>old_code COLLATE utf8mb4_general_ci) THEN
      SET reason='Inbound model alias must be migrated explicitly';
    END IF;
    -- 成功但未完成素材转存/计费的任务仍可能回调或补偿，不能按 status 单字段判定已结束。
    IF EXISTS (SELECT 1 FROM aid_media_task
        WHERE (model_name=old_code COLLATE utf8mb4_general_ci OR (protocol='topaz-image' AND model_name=old_upstream COLLATE utf8mb4_general_ci))
          AND (status NOT IN ('SUCCEEDED','FAILED','CANCELED','CANCELLED')
            OR (status='SUCCEEDED' AND (oss_url IS NULL OR oss_url=''))
            OR (billing_status IS NOT NULL AND billing_status NOT IN ('SUCCESS','FAILED','REFUNDED'))))
      OR EXISTS (SELECT 1 FROM aid_gen_record WHERE model_id=old_id AND (status IS NULL OR status=0))
      OR EXISTS (SELECT 1 FROM aid_audio_record WHERE voice_model_id=old_id
        AND status NOT IN ('SUCCEEDED','FAILED','CANCELED','CANCELLED'))
      OR EXISTS (SELECT 1 FROM aid_extract_task WHERE model_code=old_code COLLATE utf8mb4_general_ci
        AND status NOT IN ('SUCCEEDED','FAILED','CANCELED','CANCELLED'))
      OR EXISTS (SELECT 1 FROM aid_skill_run WHERE model_code COLLATE utf8mb4_general_ci=old_code COLLATE utf8mb4_general_ci
        AND status NOT IN ('SUCCEEDED','FAILED','CANCELED','CANCELLED'))
      OR EXISTS (SELECT 1 FROM aid_runtime_run WHERE model_code COLLATE utf8mb4_general_ci=old_code COLLATE utf8mb4_general_ci
        AND status NOT IN ('SUCCEEDED','FAILED','STOPPED','CANCELED','CANCELLED'))
      OR EXISTS (SELECT 1 FROM aid_media_execution_permit WHERE model_code COLLATE utf8mb4_general_ci=old_code COLLATE utf8mb4_general_ci AND state IN ('RESERVED','ACTIVE')) THEN
      SET reason='Active execution or unsettled media task must finish before cleanup';
    END IF;
    IF reason IS NOT NULL THEN
      SET reason=CONCAT(old_code,': ',reason);
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT=reason;
    END IF;

    BEGIN
      DECLARE pools_done INT DEFAULT 0;
      DECLARE pool_id BIGINT;
      DECLARE pool_deleted CHAR(1);
      DECLARE pool_type VARCHAR(32);
      DECLARE pool_mode VARCHAR(32);
      DECLARE standard_id BIGINT;
      DECLARE members LONGTEXT;
      DECLARE previous_members LONGTEXT;
      DECLARE position_no INT;
      DECLARE pools CURSOR FOR SELECT id,del_flag,model_type,generate_mode,model_ids FROM aid_ai_model_func_config FOR UPDATE;
      DECLARE CONTINUE HANDLER FOR NOT FOUND SET pools_done=1;
      OPEN pools;
      pool_loop: LOOP
        FETCH pools INTO pool_id,pool_deleted,pool_type,pool_mode,members;
        IF pools_done=1 THEN LEAVE pool_loop; END IF;
        IF JSON_TYPE(members)<>'ARRAY' THEN
          SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid model pool JSON; repair its model_ids before cleanup';
        END IF;
        SET previous_members=members;
        SET position_no=JSON_LENGTH(members)-1;
        WHILE position_no>=0 DO
          IF JSON_UNQUOTE(JSON_EXTRACT(members,CONCAT('$[',position_no,']')))=CAST(old_id AS CHAR) THEN
            SET members=JSON_REMOVE(members,CONCAT('$[',position_no,']'));
          END IF;
          SET position_no=position_no-1;
        END WHILE;
        IF NOT (members <=> previous_members) THEN
          -- 仅空的图片高清池允许语义一致地回落 Standard；其他业务不能扩大成新的模型授权。
          IF pool_deleted='0' AND JSON_LENGTH(members)=0 THEN
            SET standard_id=(SELECT MIN(m.id) FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id
              WHERE p.provider_code='topaz' AND m.model_code='topaz-standard-2'
                AND m.model_type='image' AND m.del_flag='0');
            IF pool_type='image' AND pool_mode='image_upscale' AND standard_id IS NOT NULL THEN
              SET members=JSON_ARRAY(standard_id);
              INSERT INTO aid_ai_business_model_binding
                (func_code,model_id,capability_code,default_capability,sort_order,create_time,create_by)
              SELECT func_code,standard_id,'image_upscale',1,0,NOW(),'system'
              FROM aid_ai_model_func_config f WHERE f.id=pool_id
                AND NOT EXISTS (SELECT 1 FROM aid_ai_business_model_binding b
                  WHERE b.func_code=f.func_code AND b.model_id=standard_id AND b.capability_code='image_upscale');
            ELSE
              SET reason=CONCAT('Model pool ',pool_id,' would be empty; bind a compatible replacement first');
              SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT=reason;
            END IF;
          END IF;
          UPDATE aid_ai_model_func_config SET model_ids=members,update_by='system',update_time=NOW() WHERE id=pool_id;
        END IF;
      END LOOP;
      CLOSE pools;
    END;
    DELETE FROM aid_ai_business_model_binding WHERE model_id=old_id;
    DELETE FROM aid_ai_model_alias WHERE model_id=old_id OR legacy_model_id=old_id;
    DELETE FROM aid_ai_model_protocol_binding WHERE model_id=old_id;
    DELETE FROM aid_ai_model_capability WHERE model_id=old_id;
    DELETE FROM aid_ai_model WHERE id=old_id;
  END LOOP;
  CLOSE retired;

  -- 当前 Standard 2 官方契约：仅调整该型号的能力字段，不覆盖网关、价格、启停或其他配置。
  SET @topaz_standard_params=JSON_OBJECT(
    'deblurStrength',JSON_OBJECT('type','number','min',0,'max',1,'upstream','deblur_strength'),
    'decompressionStrength',JSON_OBJECT('type','number','min',0,'max',1,'upstream','decompression_strength'),
    'denoiseStrength',JSON_OBJECT('type','number','min',0,'max',1,'upstream','denoise_strength'),
    'opacity',JSON_OBJECT('type','number','min',0,'max',1),
    'outputFormat',JSON_OBJECT('type','string','enum',JSON_ARRAY('jpeg','jpg','png','tiff','tif'),'upstream','output_format'),
    'cropToFill',JSON_OBJECT('type','boolean','upstream','crop_to_fill'));
  SET @topaz_standard_schema='[{"name":"referenceImageUrl","label":"原图","type":"string","materialRole":"reference_image"},{"name":"size","label":"目标像素宽高","type":"string","required":true},{"name":"expectedImageCount","label":"生成张数","type":"integer","minimum":1,"maximum":1,"defaultValue":1},{"name":"options","label":"生成参数","type":"object","properties":[{"name":"providerParameters","label":"增强参数","type":"object","properties":[{"name":"deblurStrength","label":"去模糊强度","type":"number","minimum":0,"maximum":1},{"name":"decompressionStrength","label":"去压缩伪影强度","type":"number","minimum":0,"maximum":1},{"name":"denoiseStrength","label":"降噪强度","type":"number","minimum":0,"maximum":1},{"name":"opacity","label":"效果融合强度","type":"number","minimum":0,"maximum":1},{"name":"outputFormat","label":"输出格式","type":"string","choices":["jpeg","jpg","png","tiff","tif"]},{"name":"cropToFill","label":"裁切填充","type":"boolean"}]}]}]';
  UPDATE aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id
  SET m.capability_json=JSON_SET(IF(JSON_VALID(m.capability_json),m.capability_json,'{}'),
      '$.providerParameters',JSON_EXTRACT(@topaz_standard_params,'$'),
      '$.referenceImageMaxPixels',LEAST(COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(m.capability_json,'$.referenceImageMaxPixels')) AS UNSIGNED),256000000),256000000),
      '$.maxOutputPixels',LEAST(COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(m.capability_json,'$.maxOutputPixels')) AS UNSIGNED),256000000),256000000)),
      m.config_version=COALESCE(m.config_version,0)+1,m.update_by='system',m.update_time=NOW()
  WHERE p.provider_code='topaz' AND m.model_code='topaz-standard-2' AND m.model_type='image'
    AND m.del_flag='0'
    AND (NOT (JSON_EXTRACT(m.capability_json,'$.providerParameters') <=> JSON_EXTRACT(@topaz_standard_params,'$'))
      OR COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(m.capability_json,'$.referenceImageMaxPixels')) AS UNSIGNED),256000001)>256000000
      OR COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(m.capability_json,'$.maxOutputPixels')) AS UNSIGNED),256000001)>256000000);

  INSERT INTO aid_ai_model_capability
    (model_id,capability_code,generate_mode,definition_json,sort_order,create_time,create_by)
  SELECT m.id,'image_upscale','image_upscale',JSON_OBJECT('code','image_upscale','label','图片高清',
    'generateMode','image_upscale','enabled',true,'defaultCapability',true,
    'evidenceStatus','LEGACY_PENDING_REVIEW','parameters',JSON_EXTRACT(@topaz_standard_schema,'$'),
    'sourceUrls',JSON_ARRAY('https://developer.topazlabs.com/image-models/upscaling-and-enhancement/precision/standard-2.md')),
    0,NOW(),'system'
  FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id
  WHERE p.provider_code='topaz' AND m.model_code='topaz-standard-2' AND m.del_flag='0' AND m.model_type='image'
    AND NOT EXISTS (SELECT 1 FROM aid_ai_model_capability c WHERE c.model_id=m.id AND c.capability_code='image_upscale');
  UPDATE aid_ai_model_capability c JOIN aid_ai_model m ON m.id=c.model_id
    JOIN aid_ai_provider p ON p.id=m.provider_id
  SET c.definition_json=JSON_SET(c.definition_json,'$.parameters',JSON_EXTRACT(@topaz_standard_schema,'$')),
    c.update_by='system',c.update_time=NOW()
  WHERE p.provider_code='topaz' AND m.model_code='topaz-standard-2' AND m.del_flag='0' AND m.model_type='image'
    AND c.capability_code='image_upscale' AND JSON_VALID(c.definition_json)
    AND NOT (JSON_EXTRACT(c.definition_json,'$.parameters') <=> JSON_EXTRACT(@topaz_standard_schema,'$'));

  INSERT INTO aid_ai_model_protocol_binding
    (model_id,capability_code,binding_code,protocol,definition_json,sort_order,create_time,create_by)
  SELECT m.id,'image_upscale','topaz_standard_image','topaz-image',JSON_OBJECT(
    'code','topaz_standard_image','protocol','topaz-image','upstreamModel','Standard V2',
    'apiSuffix','/image/v1/enhance/async','enabled',true,'defaultBinding',true,
    'capability',JSON_EXTRACT(m.capability_json,'$'),'billingMode',m.billing_mode,
    'billingRule',JSON_EXTRACT(IF(JSON_VALID(m.billing_rule_json),m.billing_rule_json,'{}'),'$')),0,NOW(),'system'
  FROM aid_ai_model m JOIN aid_ai_provider p ON p.id=m.provider_id
  WHERE p.provider_code='topaz' AND m.model_code='topaz-standard-2' AND m.del_flag='0' AND m.model_type='image'
    AND NOT EXISTS (SELECT 1 FROM aid_ai_model_protocol_binding b WHERE b.model_id=m.id AND b.capability_code='image_upscale');

  UPDATE aid_ai_model_protocol_binding b JOIN aid_ai_model m ON m.id=b.model_id
    JOIN aid_ai_provider p ON p.id=m.provider_id
  SET b.definition_json=JSON_SET(b.definition_json,
      '$.capability.providerParameters',JSON_EXTRACT(@topaz_standard_params,'$'),
      '$.capability.referenceImageMaxPixels',LEAST(COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(b.definition_json,'$.capability.referenceImageMaxPixels')) AS UNSIGNED),256000000),256000000),
      '$.capability.maxOutputPixels',LEAST(COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(b.definition_json,'$.capability.maxOutputPixels')) AS UNSIGNED),256000000),256000000)),
      b.update_by='system',b.update_time=NOW()
  WHERE p.provider_code='topaz' AND m.model_code='topaz-standard-2' AND m.model_type='image'
    AND m.del_flag='0' AND b.capability_code='image_upscale' AND b.protocol='topaz-image'
    AND JSON_VALID(b.definition_json)
    AND (NOT (JSON_EXTRACT(b.definition_json,'$.capability.providerParameters') <=> JSON_EXTRACT(@topaz_standard_params,'$'))
      OR COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(b.definition_json,'$.capability.referenceImageMaxPixels')) AS UNSIGNED),256000001)>256000000
      OR COALESCE(CAST(JSON_UNQUOTE(JSON_EXTRACT(b.definition_json,'$.capability.maxOutputPixels')) AS UNSIGNED),256000001)>256000000);
  SET @topaz_standard_params=NULL;
  SET @topaz_standard_schema=NULL;
  COMMIT;
END$$
CALL aid_cleanup_topaz_image_catalog()$$
DROP PROCEDURE aid_cleanup_topaz_image_catalog$$
DELIMITER ;

-- 同一 Seedance 2.0 能力的历史与当前官方协议同时为默认时，保留当前协议。
-- 精确匹配已知迁移绑定，保留价格、自定义协议及环境上游模型编码。
UPDATE aid_ai_model_protocol_binding old_route
JOIN aid_ai_model m ON m.id=old_route.model_id AND m.del_flag='0'
JOIN aid_ai_provider p ON p.id=m.provider_id AND p.provider_code='volcengine'
JOIN aid_ai_model_protocol_binding current_route
  ON current_route.model_id=old_route.model_id
  AND current_route.capability_code=old_route.capability_code
SET old_route.definition_json=JSON_SET(old_route.definition_json,'$.defaultBinding',JSON_EXTRACT('false','$'))
WHERE m.model_code='doubao-seedance-2.0'
  AND old_route.binding_code='seedance_official_14'
  AND current_route.binding_code='seedance_official_328'
  AND old_route.protocol='seedance-video' AND current_route.protocol='seedance-video'
  AND JSON_UNQUOTE(JSON_EXTRACT(old_route.definition_json,'$.protocol'))='seedance-video'
  AND JSON_UNQUOTE(JSON_EXTRACT(current_route.definition_json,'$.protocol'))='seedance-video'
  AND JSON_UNQUOTE(JSON_EXTRACT(old_route.definition_json,'$.upstreamModel'))=m.real_model_code
  AND JSON_UNQUOTE(JSON_EXTRACT(current_route.definition_json,'$.upstreamModel'))=m.real_model_code
  AND JSON_EXTRACT(old_route.definition_json,'$.defaultBinding')=TRUE
  AND JSON_EXTRACT(old_route.definition_json,'$.enabled')=TRUE
  AND JSON_EXTRACT(current_route.definition_json,'$.defaultBinding')=TRUE
  AND JSON_EXTRACT(current_route.definition_json,'$.enabled')=TRUE
  AND old_route.capability_code IN ('text_to_video','image_to_video','start_end_to_video',
    'reference_to_video','video_edit','video_extend');

