UPDATE aid_ai_model_func_config f SET model_ids=(SELECT CAST(CONCAT('[',GROUP_CONCAT(DISTINCT b.model_id ORDER BY b.model_id),']') AS JSON) FROM aid_ai_business_model_binding b WHERE b.func_code=f.func_code) WHERE @omni_new_canvas_pool AND f.func_code='canvas.video.generate';
SET SESSION group_concat_max_len=@omni_group_concat_before;
UPDATE aid_ai_model_func_config f SET model_ids=JSON_ARRAY_APPEND(model_ids,'$',@omni_model) WHERE @omni_new_model AND @omni_model IS NOT NULL AND f.del_flag='0' AND EXISTS(SELECT 1 FROM aid_ai_business_model_binding b WHERE b.func_code=f.func_code AND b.model_id=@omni_model) AND NOT JSON_CONTAINS(model_ids,CAST(@omni_model AS CHAR),'$');
COMMIT;

START TRANSACTION;
-- 内置风格与参考角色的品牌中性表述；仅替换仍含旧词的官方素材，保留其他编辑和资源路径。
UPDATE `aid_comic_asset` SET `prompt_text`=REPLACE(`prompt_text`,'参考押井守《攻壳机动队》美术设定','突出冷峻的未来都市美术设定') WHERE `id`=1 AND `asset_type`='style' AND LOCATE('参考押井守《攻壳机动队》美术设定',`prompt_text`)>0;
UPDATE `aid_comic_asset` SET `prompt_text`=REPLACE(`prompt_text`,'参考《山水情》水墨动画','突出传统水墨动画质感') WHERE `id`=2 AND `asset_type`='style' AND LOCATE('参考《山水情》水墨动画',`prompt_text`)>0;
UPDATE `aid_comic_asset` SET `prompt_text`=REPLACE(`prompt_text`,'参考伦勃朗与维米尔油画','强调古典写实油画的明暗层次') WHERE `id`=3 AND `asset_type`='style' AND LOCATE('参考伦勃朗与维米尔油画',`prompt_text`)>0;
UPDATE `aid_comic_asset` SET `prompt_text`=REPLACE(`prompt_text`,'参考蒂姆·伯顿视觉美术','突出奇诡装饰与尖角造型') WHERE `id`=6 AND `asset_type`='style' AND LOCATE('参考蒂姆·伯顿视觉美术',`prompt_text`)>0;
