-- Model price settlement in CNY. Fixed conversion 1 USD = 7 CNY.
-- Convert both fallback prices and protocol-specific price overrides.
SET NAMES utf8mb4;
DELIMITER $$
DROP PROCEDURE IF EXISTS aid_model_and_route_price_cny7$$
CREATE PROCEDURE aid_model_and_route_price_cny7()
BEGIN
  DECLARE done INT DEFAULT 0;
  DECLARE row_id BIGINT;
  DECLARE model_id BIGINT;
  DECLARE is_route INT;
  DECLARE model_code_value VARCHAR(255);
  DECLARE original_cost DECIMAL(44,20);
  DECLARE original_rule TEXT CHARACTER SET utf8mb4;
  DECLARE original_definition MEDIUMTEXT CHARACTER SET utf8mb4;
  DECLARE route_definition JSON;
  DECLARE old_cost_json JSON;
  DECLARE rule_json JSON;
  DECLARE old_price JSON;
  DECLARE paths JSON;
  DECLARE price_path VARCHAR(160);
  DECLARE sku_code VARCHAR(160);
  DECLARE price_note TEXT CHARACTER SET utf8mb4;
  DECLARE fixed_rate DECIMAL(8,4) DEFAULT 7;
  DECLARE index_sku, index_path, idx_tier INT;
  DECLARE updated_rows INT DEFAULT 0;
  DECLARE legacy_rows INT DEFAULT 0;
  DECLARE route_rows INT DEFAULT 0;
  DECLARE is_usd BOOLEAN;
  DECLARE new_cost DECIMAL(50,24);
  DECLARE drift_error VARCHAR(128);
  DECLARE model_cursor CURSOR FOR
    SELECT m.id, m.id, 0, m.model_code, m.cost_credits, m.billing_rule_json, NULL
    FROM aid_ai_model m
    WHERE m.del_flag = '0' AND JSON_VALID(m.billing_rule_json) = 1
    UNION ALL
    SELECT b.id, m.id, 1, m.model_code, NULL,
           JSON_EXTRACT(IF(JSON_VALID(b.definition_json), b.definition_json, '{}'), '$.billingRule'),
           b.definition_json
    FROM aid_ai_model_protocol_binding b
    JOIN aid_ai_model m ON m.id = b.model_id
    WHERE m.del_flag = '0' AND JSON_VALID(b.definition_json) = 1
      AND JSON_TYPE(JSON_EXTRACT(IF(JSON_VALID(b.definition_json), b.definition_json, '{}'), '$.billingRule')) = 'OBJECT';
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  CREATE TEMPORARY TABLE IF NOT EXISTS aid_cny_changed_model (id BIGINT PRIMARY KEY) ENGINE=InnoDB;
  START TRANSACTION;
  OPEN model_cursor;
  price_rows: LOOP
    FETCH model_cursor INTO row_id, model_id, is_route, model_code_value, original_cost, original_rule, original_definition;
    IF done THEN LEAVE price_rows; END IF;
    SET rule_json = original_rule;
    SET route_definition = original_definition;
    SET new_cost = original_cost;
    SET is_usd = COALESCE(UPPER(TRIM(JSON_UNQUOTE(JSON_EXTRACT(rule_json, '$.priceCurrency')))) = 'USD', FALSE);

    IF is_usd THEN
      SET paths = JSON_ARRAY('$.inputPricing.image.unitPrice', '$.inputPricing.video.unitPrice');
      SET index_sku = 0;
      WHILE index_sku < COALESCE(JSON_LENGTH(JSON_EXTRACT(rule_json, '$.skus')), 0) DO
        SET price_path = CONCAT('$.skus[', index_sku, '].');
        SET paths = JSON_ARRAY_APPEND(paths,
          '$', CONCAT(price_path, 'price'),
          '$', CONCAT(price_path, 'pricePerSecond'),
          '$', CONCAT(price_path, 'pricePerChar'),
          '$', CONCAT(price_path, 'fixedSurcharge'),
          '$', CONCAT(price_path, 'inputPricePerMillion'),
          '$', CONCAT(price_path, 'imageRequestTextInputPricePerMillion'),
          '$', CONCAT(price_path, 'outputPricePerMillion'),
          '$', CONCAT(price_path, 'cachedInputPricePerMillion'),
          '$', CONCAT(price_path, 'cacheWritePricePerMillion'),
          '$', CONCAT(price_path, 'reasoningPricePerMillion'),
          '$', CONCAT(price_path, 'inputPricing.image.unitPrice'),
          '$', CONCAT(price_path, 'inputPricing.video.unitPrice'),
          '$', CONCAT(price_path, 'compositeVideoTokens.inputPricePerMillion'),
          '$', CONCAT(price_path, 'compositeVideoTokens.textOutputPricePerMillion'),
          '$', CONCAT(price_path, 'compositeVideoTokens.reasoningPricePerMillion'),
          '$', CONCAT(price_path, 'compositeVideoTokens.videoOutputPricePerMillion'));
        SET index_sku = index_sku + 1;
      END WHILE;
      SET idx_tier = 0;
      WHILE idx_tier < COALESCE(JSON_LENGTH(JSON_EXTRACT(rule_json, '$.settleRule.imageOutputPixelTiers')), 0) DO
        SET paths = JSON_ARRAY_APPEND(paths, '$', CONCAT('$.settleRule.imageOutputPixelTiers[', idx_tier, '].price'));
        SET idx_tier = idx_tier + 1;
      END WHILE;
      SET index_path = 0;
      WHILE index_path < JSON_LENGTH(paths) DO
        SET price_path = JSON_UNQUOTE(JSON_EXTRACT(paths, CONCAT('$[', index_path, ']')));
        SET old_price = JSON_EXTRACT(rule_json, price_path);
        IF old_price IS NOT NULL AND JSON_TYPE(old_price) <> 'NULL' THEN
          IF JSON_UNQUOTE(old_price) NOT REGEXP '^[+]?[0-9]+([.][0-9]+)?([eE][+-]?[0-9]+)?$' THEN
            SET drift_error = CONCAT('Invalid USD price in model ', LEFT(model_code_value, 50), ' at ', LEFT(price_path, 44));
            SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = drift_error;
          END IF;
          SET rule_json = JSON_SET(rule_json, price_path,
              CAST(JSON_UNQUOTE(old_price) AS DECIMAL(44,20)) * fixed_rate);
        END IF;
        SET index_path = index_path + 1;
      END WHILE;
      SET rule_json = JSON_REMOVE(JSON_SET(rule_json, '$.priceCurrency', 'CNY'), '$.exchangeRateToCny');
      SET new_cost = original_cost * fixed_rate;
    ELSEIF model_code_value IN ('wavespeed-depth-anything-video', 'topaz-proteus-video-express',
      'topaz-standard-2', 'topaz-low-resolution-2', 'topaz-art-cgi', 'topaz-high-fidelity-3',
      'topaz-text-shapes', 'topaz-wonder-3-5', 'topaz-bloom-2') AND COALESCE(UPPER(TRIM(JSON_UNQUOTE(JSON_EXTRACT(rule_json, '$.priceCurrency')))), 'CNY') IN ('CNY','NULL','') THEN
      -- Identify the unmodified old seed amount and its original USD pricing note.
      SET index_sku = 0;
      WHILE index_sku < COALESCE(JSON_LENGTH(JSON_EXTRACT(rule_json, '$.skus')), 0) DO
        SET price_path = CONCAT('$.skus[', index_sku, '].');
        SET sku_code = JSON_UNQUOTE(JSON_EXTRACT(rule_json, CONCAT(price_path,'skuCode')));
        SET price_note = JSON_UNQUOTE(JSON_EXTRACT(rule_json, CONCAT(price_path,'remark')));
        IF model_code_value = 'wavespeed-depth-anything-video' AND sku_code = 'WAVESPEED_DEPTH_VIDEO'
           AND LOCATE('6.7489', price_note) > 0
           AND JSON_UNQUOTE(JSON_EXTRACT(rule_json, CONCAT(price_path,'pricePerSecond'))) = '0.0337445' THEN
          SET rule_json = JSON_SET(rule_json, CONCAT(price_path,'pricePerSecond'), 0.035,
            CONCAT(price_path,'remark'), '官方 USD 0.005/计费秒，按 7 CNY/USD 换算，最少计 3 秒');
        ELSEIF model_code_value = 'topaz-proteus-video-express' AND sku_code = 'TOPAZ_VIDEO_CREDIT'
           AND LOCATE('6.7489', price_note) > 0
           AND JSON_UNQUOTE(JSON_EXTRACT(rule_json, CONCAT(price_path,'price'))) = '0.67489' THEN
          SET rule_json = JSON_SET(rule_json, CONCAT(price_path,'price'), 0.70,
            CONCAT(price_path,'remark'), 'Developer 档 USD 0.10/credit，按 7 CNY/USD 换算');
        ELSEIF LEFT(model_code_value, 6) = 'topaz-' AND RIGHT(sku_code, 10) = '_OUTPUT_MP'
           AND LOCATE('6.70', price_note) > 0 AND LOCATE('$0.10', price_note) > 0
           AND JSON_UNQUOTE(JSON_EXTRACT(rule_json, CONCAT(price_path,'price'))) = '0.67' THEN
          SET rule_json = JSON_SET(rule_json, CONCAT(price_path,'price'), 0.70,
            CONCAT(price_path,'remark'), 'Developer 档 USD 0.10/credit，按 7 CNY/USD 换算，按输出像素向上取整');
        END IF;
        SET index_sku = index_sku + 1;
      END WHILE;
      IF CAST(rule_json AS BINARY) <> CAST(CAST(original_rule AS JSON) AS BINARY) THEN
        SET rule_json = JSON_REMOVE(JSON_SET(rule_json, '$.priceCurrency', 'CNY'), '$.exchangeRateToCny');
      END IF;
    END IF;

    IF is_usd OR CAST(rule_json AS BINARY) <> CAST(CAST(original_rule AS JSON) AS BINARY) THEN
      IF is_route = 1 THEN
        IF is_usd THEN
          SET old_cost_json = JSON_EXTRACT(route_definition, '$.costCredits');
          IF old_cost_json IS NOT NULL AND JSON_TYPE(old_cost_json) <> 'NULL' THEN
            IF JSON_UNQUOTE(old_cost_json) NOT REGEXP '^[+]?[0-9]+([.][0-9]+)?([eE][+-]?[0-9]+)?$' THEN
              SET drift_error = CONCAT('Invalid USD route fixed price: ', LEFT(model_code_value, 75));
              SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = drift_error;
            END IF;
            SET route_definition = JSON_SET(route_definition, '$.costCredits',
                CAST(JSON_UNQUOTE(old_cost_json) AS DECIMAL(44,20)) * fixed_rate);
          END IF;
        END IF;
        UPDATE aid_ai_model_protocol_binding
        SET definition_json = JSON_SET(route_definition, '$.billingRule', rule_json)
        WHERE id = row_id AND BINARY definition_json <=> BINARY original_definition;
      ELSE
        UPDATE aid_ai_model
        SET billing_rule_json = rule_json, cost_credits = new_cost
        WHERE id = row_id AND BINARY billing_rule_json <=> BINARY original_rule
          AND cost_credits <=> original_cost AND del_flag = '0';
      END IF;
      IF ROW_COUNT() <> 1 THEN
        SET drift_error = CONCAT('Billing rule changed during FX migration: ', LEFT(model_code_value, 70));
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = drift_error;
      END IF;
      INSERT IGNORE INTO aid_cny_changed_model VALUES (model_id);
      IF is_route = 1 THEN
        SET route_rows = route_rows + 1;
      ELSE
        SET updated_rows = updated_rows + IF(is_usd, 1, 0);
        SET legacy_rows = legacy_rows + IF(is_usd, 0, 1);
      END IF;
    END IF;
  END LOOP;
  CLOSE model_cursor;
  UPDATE aid_ai_model m JOIN aid_cny_changed_model c ON c.id = m.id
  SET m.billing_version = COALESCE(m.billing_version, 0) + 1;
  COMMIT;
  DROP TEMPORARY TABLE aid_cny_changed_model;
  SELECT updated_rows AS usd_rules_converted, legacy_rows AS older_fx_rules_rebased, route_rows AS routes_converted;
END$$
CALL aid_model_and_route_price_cny7()$$
DROP PROCEDURE aid_model_and_route_price_cny7$$
DELIMITER ;


-- Additional public canvas and previz structures.
CREATE TABLE IF NOT EXISTS `aid_canvas_agent_session` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `workspace_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `title` varchar(100) NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_agent_session_owner` (`workspace_id`,`user_id`,`updated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布个人对话';

CREATE TABLE IF NOT EXISTS `aid_canvas_agent_turn` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `session_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `request_key` varchar(64) NOT NULL,
  `prompt` text NOT NULL,
  `chat_input` text NOT NULL,
  `model_code` varchar(100) NOT NULL,
  `refs_json` text NOT NULL,
  `status` varchar(32) NOT NULL,
  `chat_quote` decimal(18,6) NOT NULL,
  `chat_authorized` decimal(18,6) NOT NULL,
  `chat_task_id` bigint DEFAULT NULL,
  `chat_task_status` varchar(32) DEFAULT NULL,
  `reply_text` mediumtext,
  `plan_prompt` text,
  `plan_model` varchar(100) DEFAULT NULL,
  `plan_quote` decimal(18,6) DEFAULT NULL,
  `plan_version` int NOT NULL DEFAULT '1',
  `mode` varchar(10) DEFAULT NULL,
  `budget_cap` decimal(18,6) DEFAULT NULL,
  `spent_credits` decimal(18,6) DEFAULT NULL,
  `action_task_id` bigint DEFAULT NULL,
  `action_task_status` varchar(32) DEFAULT NULL,
  `result_node_id` varchar(64) DEFAULT NULL,
  `result_text` mediumtext,
  `error_message` varchar(500) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_agent_turn_request` (`session_id`,`request_key`),
  KEY `idx_agent_turn_status` (`status`,`id`),
  KEY `idx_agent_turn_session` (`session_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布对话计划与执行授权';

CREATE TABLE IF NOT EXISTS `aid_canvas_audit_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '审计记录ID',
  `operator` varchar(64) NOT NULL COMMENT '操作人账号',
  `operator_name` varchar(100) DEFAULT NULL COMMENT '操作人显示名',
  `target_type` varchar(32) NOT NULL COMMENT '目标类型',
  `target_id` varchar(128) NOT NULL COMMENT '目标稳定ID',
  `target_user_id` bigint DEFAULT NULL COMMENT '目标用户ID',
  `action` varchar(64) NOT NULL COMMENT '审计动作',
  `detail_json` longtext COMMENT '审计详情JSON',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_canvas_audit_operator` (`operator`,`create_time`,`id`),
  KEY `idx_canvas_audit_target_user` (`target_user_id`,`create_time`,`id`),
  KEY `idx_canvas_audit_action` (`action`,`create_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布后台审计日志';

CREATE TABLE IF NOT EXISTS `aid_canvas_config` (
  `id` bigint NOT NULL COMMENT '配置ID',
  `collaboration_enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '实时协作总开关',
  `max_projects_per_owner` int NOT NULL DEFAULT '20' COMMENT '所有者项目数兜底上限',
  `max_nodes_per_workspace` int NOT NULL DEFAULT '1000' COMMENT '工作区节点数兜底上限',
  `max_members_per_project` int NOT NULL DEFAULT '10' COMMENT '项目成员数兜底上限',
  `max_online_editors` int NOT NULL DEFAULT '10' COMMENT '工作区在线编辑人数兜底上限',
  `max_connections_per_user` int NOT NULL DEFAULT '3' COMMENT '单用户在线连接上限',
  `operation_batch_max` int NOT NULL DEFAULT '100' COMMENT '单次变更操作上限',
  `operation_payload_max_bytes` int NOT NULL DEFAULT '262144' COMMENT '单次变更载荷字节上限',
  `lock_lease_seconds` int NOT NULL DEFAULT '30' COMMENT '节点锁租期秒数',
  `lock_renew_seconds` int NOT NULL DEFAULT '10' COMMENT '节点锁续期间隔秒数',
  `text_merge_millis` int NOT NULL DEFAULT '300' COMMENT '文本变更合并窗口毫秒数',
  `invite_default_days` int NOT NULL DEFAULT '7' COMMENT '邀请默认有效天数',
  `invite_default_uses` int NOT NULL DEFAULT '10' COMMENT '邀请默认使用次数',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布运行配置';

-- 为画布运行配置补齐固定记录，沿用列默认值并保留既有设置。
INSERT INTO `aid_canvas_config` (`id`, `create_time`, `update_time`)
VALUES (1, NOW(), NOW())
ON DUPLICATE KEY UPDATE `id` = `aid_canvas_config`.`id`;

CREATE TABLE IF NOT EXISTS `aid_canvas_model_category` (
  `id` varchar(32) NOT NULL,
  `name` varchar(50) NOT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'ACTIVE',
  `sort_order` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_category_status` (`status`,`sort_order`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `aid_canvas_model_library` (
  `id` varchar(32) NOT NULL,
  `model_id` varchar(32) NOT NULL,
  `version_no` int NOT NULL,
  `name` varchar(100) NOT NULL,
  `category_id` varchar(32) NOT NULL,
  `tags` varchar(500) NOT NULL DEFAULT '',
  `status` varchar(16) NOT NULL DEFAULT 'DRAFT',
  `storage_path` varchar(2048) NOT NULL,
  `thumbnail_path` varchar(2048) NOT NULL,
  `file_size` bigint NOT NULL,
  `content_hash` char(64) NOT NULL,
  `metadata_json` text NOT NULL,
  `revision` int NOT NULL DEFAULT '1',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_model_version` (`model_id`,`version_no`),
  KEY `idx_model_catalog` (`status`,`category_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `aid_canvas_model_usage` (
  `version_id` varchar(32) NOT NULL,
  `workspace_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `operation_id` varchar(64) NOT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`version_id`,`workspace_id`,`user_id`,`operation_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `aid_canvas_node_draft` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '节点个人草稿ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `workspace_id` bigint NOT NULL COMMENT '工作区ID',
  `object_id` varchar(64) NOT NULL COMMENT '节点稳定ID',
  `user_id` bigint NOT NULL COMMENT '草稿所属用户ID',
  `draft_version` bigint NOT NULL DEFAULT '1' COMMENT '草稿乐观锁版本',
  `base_object_version` bigint NOT NULL DEFAULT '0' COMMENT '草稿基于的共享对象版本',
  `draft_json` longtext NOT NULL COMMENT '个人草稿JSON',
  `draft_hash` char(64) NOT NULL COMMENT '草稿SHA-256摘要',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_canvas_node_draft_user` (`workspace_id`,`object_id`,`user_id`),
  KEY `idx_canvas_node_draft_load` (`workspace_id`,`user_id`,`update_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='画布节点个人断线草稿';

CREATE TABLE IF NOT EXISTS `aid_canvas_node_result_selection` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '节点结果选择ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `workspace_id` bigint NOT NULL COMMENT '工作区ID',
  `object_id` varchar(64) NOT NULL COMMENT '节点稳定ID',
  `task_id` bigint NOT NULL COMMENT '统一媒体任务ID',
  `result_id` bigint NOT NULL COMMENT '媒体结果ID',
  `input_object_version` bigint NOT NULL COMMENT '生成输入对应的节点版本',
  `selection_version` bigint NOT NULL DEFAULT '1' COMMENT '结果选择版本',
  `last_actor_user_id` bigint NOT NULL COMMENT '最后选择用户ID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_canvas_node_result_selection` (`workspace_id`,`object_id`),
  KEY `idx_canvas_node_result_task` (`task_id`,`result_id`),
  KEY `idx_canvas_node_result_project` (`project_id`,`update_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='画布节点当前结果选择';

CREATE TABLE IF NOT EXISTS `aid_canvas_object` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '对象记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `workspace_id` bigint NOT NULL COMMENT '工作区ID',
  `object_id` varchar(64) NOT NULL COMMENT '画布对象稳定ID',
  `object_type` varchar(16) NOT NULL COMMENT '对象类型',
  `object_version` bigint NOT NULL DEFAULT '1' COMMENT '对象乐观锁版本',
  `lock_fence` bigint NOT NULL DEFAULT '0' COMMENT '最近成功写入的租约栅栏令牌',
  `content_json` longtext COMMENT '对象内容JSON，删除墓碑为空',
  `content_hash` char(64) DEFAULT NULL COMMENT '对象内容SHA-256摘要，删除墓碑为空',
  `deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除状态',
  `last_actor_user_id` bigint NOT NULL COMMENT '最近写入用户ID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_canvas_object_workspace_object` (`workspace_id`,`object_id`),
  KEY `idx_canvas_object_workspace_active` (`workspace_id`,`deleted`,`id`),
  KEY `idx_canvas_object_project` (`project_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布对象当前态';

CREATE TABLE IF NOT EXISTS `aid_canvas_object_fence` (
  `workspace_id` bigint NOT NULL COMMENT '工作区ID',
  `object_id` varchar(64) NOT NULL COMMENT '画布对象稳定ID',
  `lock_fence` bigint NOT NULL DEFAULT '0' COMMENT '最近签发的租约栅栏令牌',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`workspace_id`,`object_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布对象租约栅栏';

CREATE TABLE IF NOT EXISTS `aid_canvas_operation` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '操作记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `workspace_id` bigint NOT NULL COMMENT '工作区ID',
  `operation_id` varchar(64) NOT NULL COMMENT '客户端幂等操作ID',
  `actor_user_id` bigint NOT NULL COMMENT '操作用户ID',
  `workspace_revision` bigint NOT NULL COMMENT '操作后的工作区修订号',
  `event_seq` bigint NOT NULL COMMENT '工作区事件序号',
  `operation_type` varchar(32) NOT NULL COMMENT '操作类型',
  `payload_json` longtext NOT NULL COMMENT '操作结果或增量JSON',
  `payload_hash` char(64) NOT NULL COMMENT '操作载荷SHA-256摘要',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_canvas_operation_idempotency` (`workspace_id`,`operation_id`),
  UNIQUE KEY `uk_canvas_operation_event` (`workspace_id`,`event_seq`),
  KEY `idx_canvas_operation_project` (`project_id`,`id`),
  KEY `idx_canvas_operation_actor` (`actor_user_id`,`create_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布增量操作日志';

CREATE TABLE IF NOT EXISTS `aid_canvas_operation_object` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '操作对象快照ID',
  `operation_row_id` bigint NOT NULL COMMENT '画布操作记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `workspace_id` bigint NOT NULL COMMENT '工作区ID',
  `operation_id` varchar(64) NOT NULL COMMENT '客户端幂等操作ID',
  `object_id` varchar(64) NOT NULL COMMENT '画布对象稳定ID',
  `object_type` varchar(16) NOT NULL COMMENT '对象类型',
  `before_version` bigint NOT NULL COMMENT '操作前对象版本，0表示不存在',
  `after_version` bigint NOT NULL COMMENT '操作后对象版本',
  `before_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作前删除状态',
  `after_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '操作后删除状态',
  `before_content_json` longtext COMMENT '操作前内容，用于安全撤销',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_canvas_operation_object` (`operation_row_id`,`object_id`),
  KEY `idx_canvas_operation_object_target` (`workspace_id`,`object_id`,`id`),
  KEY `idx_canvas_operation_object_operation` (`workspace_id`,`operation_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='画布操作对象前态快照';

CREATE TABLE IF NOT EXISTS `aid_canvas_owner_quota` (
  `user_id` bigint NOT NULL COMMENT '项目所有者用户ID',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布所有者容量并发锁';

CREATE TABLE IF NOT EXISTS `aid_canvas_project_request` (
  `user_id` bigint NOT NULL COMMENT '创建用户ID',
  `operation_id` varchar(64) NOT NULL COMMENT '客户端幂等操作ID',
  `request_hash` char(64) NOT NULL COMMENT '创建请求SHA-256摘要',
  `project_id` bigint NOT NULL DEFAULT '0' COMMENT '创建完成后的项目ID，0表示处理中',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (`user_id`,`operation_id`),
  KEY `idx_canvas_project_request_project` (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布项目创建幂等记录';

CREATE TABLE IF NOT EXISTS `aid_canvas_resource` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '资源记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `workspace_id` bigint NOT NULL COMMENT '工作区ID',
  `owner_user_id` bigint NOT NULL COMMENT '资源所属用户ID',
  `source_type` varchar(32) NOT NULL COMMENT '资源来源类型',
  `source_id` bigint DEFAULT NULL COMMENT '来源记录ID，直接上传时为空',
  `media_type` varchar(16) NOT NULL COMMENT '媒体类型',
  `storage_url` varchar(1024) NOT NULL COMMENT '受控存储地址',
  `file_size` bigint DEFAULT NULL COMMENT '文件字节数',
  `mime_type` varchar(100) DEFAULT NULL,
  `metadata_json` longtext,
  `status` varchar(16) NOT NULL DEFAULT 'ACTIVE' COMMENT '资源状态',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_canvas_resource_source` (`workspace_id`,`source_type`,`source_id`),
  KEY `idx_canvas_resource_workspace` (`workspace_id`,`status`,`id`),
  KEY `idx_canvas_resource_owner` (`owner_user_id`,`status`,`id`),
  KEY `idx_canvas_resource_project` (`project_id`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布受控媒体资源';

CREATE TABLE IF NOT EXISTS `aid_canvas_scene_write_history` (
  `project_id` bigint NOT NULL,
  `scene_version` bigint NOT NULL,
  `before_document_json` longtext COLLATE utf8mb4_general_ci NOT NULL,
  PRIMARY KEY (`project_id`,`scene_version`),
  CONSTRAINT `fk_canvas_scene_history_state` FOREIGN KEY (`project_id`) REFERENCES `aid_canvas_publication_state` (`project_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

CREATE TABLE IF NOT EXISTS `aid_canvas_task_binding` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '绑定记录ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `workspace_id` bigint NOT NULL COMMENT '工作区ID',
  `object_id` varchar(64) NOT NULL COMMENT '生成节点稳定ID',
  `input_object_version` bigint NOT NULL COMMENT '生成输入对象版本',
  `task_id` bigint DEFAULT NULL COMMENT '统一媒体任务ID',
  `actor_user_id` bigint NOT NULL COMMENT '生成发起用户及付费主体ID',
  `media_type` varchar(16) NOT NULL COMMENT '媒体类型',
  `result_format` varchar(16) DEFAULT NULL,
  `operation_id` varchar(64) NOT NULL COMMENT '生成幂等操作ID',
  `request_hash` char(64) NOT NULL COMMENT '生成请求SHA-256摘要',
  `status` varchar(16) NOT NULL COMMENT '绑定状态',
  `call_id` varchar(128) NOT NULL COMMENT '统一媒体服务稳定调用ID',
  `result_url` varchar(1024) DEFAULT NULL COMMENT '生成结果地址',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_canvas_task_operation` (`workspace_id`,`operation_id`),
  UNIQUE KEY `uk_canvas_task_call` (`call_id`),
  UNIQUE KEY `uk_canvas_task_id` (`task_id`),
  KEY `idx_canvas_task_object` (`workspace_id`,`object_id`,`status`,`id`),
  KEY `idx_canvas_task_project` (`project_id`,`status`,`id`),
  KEY `idx_canvas_task_actor` (`actor_user_id`,`status`,`id`),
  KEY `idx_canvas_task_reconcile` (`status`,`update_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布节点与统一媒体任务绑定';

CREATE TABLE IF NOT EXISTS `aid_canvas_user_view` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '视图记录ID',
  `workspace_id` bigint NOT NULL COMMENT '工作区ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `view_version` bigint NOT NULL DEFAULT '0' COMMENT '个人视图乐观锁版本',
  `view_json` longtext NOT NULL COMMENT '个人视口和偏好JSON',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_canvas_user_view` (`workspace_id`,`user_id`),
  KEY `idx_canvas_user_view_user` (`user_id`,`update_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布个人视图';

CREATE TABLE IF NOT EXISTS `aid_canvas_workspace` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '工作区ID',
  `project_id` bigint NOT NULL COMMENT '项目ID',
  `workspace_type` varchar(32) NOT NULL DEFAULT 'FREE_CANVAS' COMMENT '工作区类型',
  `schema_version` int NOT NULL DEFAULT '1' COMMENT '画布文档结构版本',
  `revision` bigint NOT NULL DEFAULT '0' COMMENT '工作区修订号',
  `event_seq` bigint NOT NULL DEFAULT '0' COMMENT '增量事件序号',
  `node_count` int NOT NULL DEFAULT '0' COMMENT '有效节点数',
  `edge_count` int NOT NULL DEFAULT '0' COMMENT '有效连线数',
  `group_count` int NOT NULL DEFAULT '0' COMMENT '有效分组数',
  `storage_bytes` bigint NOT NULL DEFAULT '0' COMMENT '对象JSON占用字节数',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_canvas_workspace_project` (`project_id`),
  KEY `idx_canvas_workspace_active` (`del_flag`,`update_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='自由画布工作区';

CREATE TABLE IF NOT EXISTS `aid_previz_document_revision` (
  `project_id` varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `revision` bigint NOT NULL,
  `source_version` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `document_version` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor_id` bigint NOT NULL,
  `operation` varchar(16) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `created_at` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (`project_id`,`revision`),
  KEY `idx_previz_document_version` (`project_id`,`document_version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `aid_previz_project` (
  `id` varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `owner_user_id` bigint NOT NULL,
  `title` varchar(120) NOT NULL,
  `create_request_id` varchar(100) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `create_request_digest` char(64) CHARACTER SET ascii COLLATE ascii_general_ci DEFAULT NULL,
  `preferred_engine` varchar(16) DEFAULT NULL,
  `model_code` varchar(100) DEFAULT NULL,
  `revision` bigint NOT NULL DEFAULT '0',
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_time` datetime NOT NULL,
  `create_by` bigint NOT NULL,
  `update_time` datetime NOT NULL,
  `update_by` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_previz_create` (`owner_user_id`,`create_request_id`),
  KEY `idx_previz_owner` (`owner_user_id`,`del_flag`,`update_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `aid_previz_project_lifecycle_operation` (
  `project_id` varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `request_id` varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `actor_id` bigint NOT NULL,
  `operation` varchar(16) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `request_digest` char(64) CHARACTER SET ascii COLLATE ascii_general_ci NOT NULL,
  `applied_revision` bigint NOT NULL,
  `deleted` tinyint NOT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`project_id`,`request_id`),
  KEY `idx_previz_lifecycle_actor` (`actor_id`,`create_time`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `aid_previz_project_member` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `project_id` varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `user_id` bigint NOT NULL,
  `role_code` varchar(16) NOT NULL,
  `del_flag` char(1) NOT NULL DEFAULT '0',
  `create_time` datetime NOT NULL,
  `create_by` bigint NOT NULL,
  `update_time` datetime NOT NULL,
  `update_by` bigint NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_previz_project_user` (`project_id`,`user_id`),
  KEY `idx_previz_member` (`user_id`,`del_flag`,`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `aid_previz_workspace_head` (
  `project_id` varchar(100) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_version` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `document_version` char(64) CHARACTER SET ascii COLLATE ascii_bin DEFAULT NULL,
  `revision` bigint NOT NULL DEFAULT '0',
  PRIMARY KEY (`project_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `aid_runtime_test_grant` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL,
  `admin_user_id` bigint NOT NULL,
  `member_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `member_id` bigint NOT NULL,
  `draft_digest` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `expires_at` datetime NOT NULL,
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ISSUED',
  `client_request_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `run_id` bigint DEFAULT NULL,
  `create_time` datetime NOT NULL,
  `update_time` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_runtime_grant_user` (`user_id`,`status`,`expires_at`,`id`),
  KEY `idx_runtime_grant_admin` (`admin_user_id`,`member_type`,`member_id`,`status`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户单次授权管理员对其草稿试运行并由本人计费';

