INSERT INTO aid_ai_model_func_config (
    func_code, func_name, model_type, generate_mode, model_ids, status, del_flag, create_by, create_time
)
SELECT s.func_code, s.func_name, s.model_type, NULLIF(s.generate_mode, ''), JSON_ARRAY(),
       '0', '0', 'system', CURRENT_TIMESTAMP
FROM aid_canvas_seed_scene s
WHERE NOT EXISTS (SELECT 1 FROM aid_ai_model_func_config f WHERE f.func_code COLLATE utf8mb4_general_ci = s.func_code);

