DROP PROCEDURE IF EXISTS aid_seed_canvas_business_models;
DELIMITER $$
CREATE PROCEDURE aid_seed_canvas_business_models()
BEGIN
    DECLARE completed BOOLEAN DEFAULT FALSE;
    DECLARE target_func VARCHAR(100);
    DECLARE target_model BIGINT;
    DECLARE target_cap VARCHAR(96);
    DECLARE preferred TINYINT;
    DECLARE ordering INT;
    DECLARE is_default TINYINT;
    DECLARE candidates CURSOR FOR
        SELECT seed.func_code, m.id, seed.capability_code, seed.default_capability, seed.sort_order
        FROM aid_canvas_seed_binding seed
        JOIN aid_canvas_seed_scene scene ON scene.func_code = seed.func_code
        JOIN aid_ai_model_func_config f ON f.func_code COLLATE utf8mb4_general_ci = seed.func_code AND f.del_flag = '0'
            AND f.model_type COLLATE utf8mb4_general_ci = scene.model_type
            AND COALESCE(f.generate_mode, '') COLLATE utf8mb4_general_ci = scene.generate_mode
        JOIN aid_ai_provider p ON p.provider_code COLLATE utf8mb4_general_ci = seed.provider_code
        JOIN aid_ai_model m ON m.provider_id = p.id AND m.model_code COLLATE utf8mb4_general_ci = seed.model_code
            AND m.del_flag = '0' AND m.model_type COLLATE utf8mb4_general_ci = scene.model_type
        JOIN aid_ai_model_capability c ON c.model_id = m.id AND c.capability_code COLLATE utf8mb4_general_ci = seed.capability_code
        WHERE seed.func_code <> 'previz_3dbox'
           OR (m.supports_text_input = 1 AND m.supports_system_prompt = 1)
        ORDER BY seed.func_code, m.id, seed.default_capability DESC, seed.sort_order, seed.capability_code;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET completed = TRUE;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;
    OPEN candidates;
    add_binding: LOOP
        FETCH candidates INTO target_func, target_model, target_cap, preferred, ordering;
        IF completed THEN
            LEAVE add_binding;
        END IF;
        IF NOT EXISTS (
            SELECT 1 FROM aid_ai_business_model_binding
            WHERE func_code COLLATE utf8mb4_general_ci = target_func AND model_id = target_model AND capability_code COLLATE utf8mb4_general_ci = target_cap
        ) THEN
            SET is_default = preferred = 1 AND NOT EXISTS (
                SELECT 1 FROM aid_ai_business_model_binding
                WHERE func_code COLLATE utf8mb4_general_ci = target_func AND model_id = target_model AND default_capability = 1
            );
            INSERT INTO aid_ai_business_model_binding (
                func_code, model_id, capability_code, default_capability, sort_order, create_by, create_time
            ) VALUES (
                target_func, target_model, target_cap,
                is_default,
                ordering, 'system', CURRENT_TIMESTAMP
            );
        END IF;
        UPDATE aid_ai_model_func_config
        SET model_ids = JSON_ARRAY_APPEND(model_ids, '$', target_model)
        WHERE func_code COLLATE utf8mb4_general_ci = target_func
          AND JSON_CONTAINS(model_ids, CAST(target_model AS JSON)) = 0
          AND JSON_CONTAINS(model_ids, JSON_QUOTE(CAST(target_model AS CHAR))) = 0;
    END LOOP;
    CLOSE candidates;
    COMMIT;
END$$
DELIMITER ;

CALL aid_seed_canvas_business_models();
DROP PROCEDURE aid_seed_canvas_business_models;
