-- 原创剧本流程
SET @aid_starter_skill_prompt := CONVERT( USING utf8mb4);
SET @aid_starter_skill_md := CONVERT( USING utf8mb4);
SET @aid_starter_skill_input := CONVERT(0x7b2274797065223a226f626a656374222c22782d6169642d696e7075742d6d6f6465223a22465245455f464f524d222c226578616d706c6573223a5b22e7a4bae4be8b225d7d USING utf8mb4);
