SET @aid_starter_skill_exists := (SELECT id FROM aid_skill WHERE skill_code='story_creation_flow' LIMIT 1);
SET @aid_starter_previous_skill_version := (SELECT v.id FROM aid_skill s JOIN aid_skill_version v
  ON v.id=s.current_version_id AND v.skill_id=s.id WHERE s.id=@aid_starter_skill_exists
  AND s.owner_type='PLATFORM' AND s.create_by='community-starter' AND s.visibility='PUBLIC'
  AND s.invocation_scope='INTERNAL' AND s.executor_type='PROMPT' AND s.status='0' AND s.del_flag='0'
  AND v.create_by='community-starter' AND v.version_code='1.0.0-community'
