INSERT INTO aid_skill (skill_code,name,description,owner_type,visibility,invocation_scope,executor_type,
  model_code,input_schema_json,output_schema_json,system_prompt,definition_json,config_hash,status,del_flag,create_by,create_time)
SELECT 'spatial_previs',CONVERT(0xe7a9bae997b4e9959ce5a4b4e9a284e6bc94 USING utf8mb4),@aid_starter_skill_prompt,'PLATFORM','PUBLIC','INTERNAL','PROMPT',
  @aid_starter_skill_model_code,@aid_starter_skill_input,@aid_starter_skill_output,@aid_starter_skill_prompt,
  @aid_starter_skill_definition,SHA2(CONCAT('spatial_previs',@aid_starter_skill_prompt),256),'0','0','community-starter',NOW()
WHERE @aid_starter_skill_exists IS NULL;
SET @aid_starter_skill := IF(@aid_starter_skill_exists IS NULL,LAST_INSERT_ID(),
