SET @aid_starter_skill_digest := SHA2(CONCAT(
  '{"format":"aid-db-package-v3","skillCode":"spatial_previs","versionCode":"1.0.1-community",',
  '"visibility":"PUBLIC","invocationScope":"INTERNAL","executorType":"PROMPT","modelCode":',JSON_QUOTE(@aid_starter_skill_model_code),
