  SELECT 'aid.previz.file-list' AS code,'1.0.0' AS revision,'e8683d2fcfc79f217efa3c42ed5b643c58beaed08d2b0703dd3ba0d20592f33d' AS digest UNION ALL
  SELECT 'aid.previz.file-read' AS code,'1.0.0' AS revision,'187ae01b07ab2005fffa00af9a671f2fcb806a1d24f155249f594508345042c8' AS digest UNION ALL
  SELECT 'aid.previz.file-write' AS code,'1.0.0' AS revision,'c9f51535d11f8d782dc57b59caf2801040fa7281d167fcf345bbc95a890e7820' AS digest UNION ALL
  SELECT 'aid.previz.progress-list' AS code,'1.0.0' AS revision,'b794084a167fa6ec23c7c97aa1f86890b52a46714926eb445a74190e2a94be6f' AS digest UNION ALL
  SELECT 'aid.previz.render-preview' AS code,'1.0.0' AS revision,'eb9b4fb98308307de2427d8e9bb2ff58ea61cd85e29fc741bd082de90401d98d' AS digest UNION ALL
  SELECT 'aid.previz.resource-read' AS code,'1.0.0' AS revision,'652d96a34f3d28fc8978a0dd795f49cbbb41f6fbe846b15cb46f4e3e092bfd83' AS digest UNION ALL
  SELECT 'aid.previz.scene-edit' AS code,'1.0.0' AS revision,'682aba6055c01e8dd450ae4546018b0ccd7900575cdf59fab0b2972031afbdc5' AS digest UNION ALL
  SELECT 'aid.previz.scene-inspect' AS code,'1.0.0' AS revision,'934e061403c180aa9c1bbe38b87b242084ecfc4df57de722f3c2a318372f5aa6' AS digest UNION ALL
  SELECT 'aid.previz.source-edit' AS code,'1.0.0' AS revision,'d9f829532f818ba4761da17c99567e154dfdce3150d14943e90909f206f15485' AS digest UNION ALL
  SELECT 'aid.previz.source-glob' AS code,'1.0.0' AS revision,'caebf849ede7f14bd9017e5bd03acae5d96f59638590764c51c1d75d130b4caf' AS digest UNION ALL
  SELECT 'aid.previz.source-grep' AS code,'1.0.0' AS revision,'b3811c88fa7f4771e10d8b34b7379927cd02df5faa5a036b403f7a90fd2e1e0f' AS digest UNION ALL
  SELECT 'aid.previz.source-import' AS code,'1.0.0' AS revision,'ec160f5b62848e145f9f671893ba16f290e3216b54b3cb942e6490cf69298d0c' AS digest UNION ALL
  SELECT 'aid.previz.source-inspect' AS code,'1.0.0' AS revision,'7a2e7a12caf9344f9aff68be3c0cc39bd83e93b2f36ee613d4a42fd0f214c55d' AS digest UNION ALL
  SELECT 'aid.previz.source-list' AS code,'1.0.0' AS revision,'97205e93575aa31f0c32f41696e1ad9b595d8fed8608cd31f8bb29ac689c7f84' AS digest UNION ALL
  SELECT 'aid.previz.source-read' AS code,'1.0.0' AS revision,'c72c6092a1bc619cf8b8269f8b69f4cb3bb9c466f2e16ec6f2bd6f7f2fdc5515' AS digest UNION ALL
  SELECT 'aid.previz.source-read-page' AS code,'1.0.0' AS revision,'d7e365d73b7676dd2a87a6b4bdb7a6750fcb8763237c2f6ec8dbed70120ebf56' AS digest UNION ALL
