PREPARE aid_canvas_feature_stmt FROM @aid_canvas_feature_ddl;
EXECUTE aid_canvas_feature_stmt;
DEALLOCATE PREPARE aid_canvas_feature_stmt;
SET @aid_canvas_feature_ddl = NULL;

-- Shared media task scheduling state used by canvas. Structure only.
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS `aid_media_task_anomaly_config` (
  `id` bigint NOT NULL COMMENT '固定配置ID',
  `enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用异常治理',
  `anomaly_threshold_seconds` int NOT NULL DEFAULT '1800' COMMENT '连续异常进入待处理清单的阈值秒数',
  `auto_recheck_interval_seconds` int NOT NULL DEFAULT '300' COMMENT '异常任务低频复查间隔秒数',
  `admin_refresh_seconds` int NOT NULL DEFAULT '60' COMMENT '后台摘要刷新间隔秒数',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='统一媒体异常任务治理配置';

CREATE TABLE IF NOT EXISTS `aid_media_task_anomaly` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '异常任务记录ID',
  `task_id` bigint NOT NULL COMMENT '统一媒体任务ID',
  `status` varchar(32) NOT NULL DEFAULT 'OBSERVING' COMMENT 'OBSERVING/PENDING/WAITING/COMPENSATION_PENDING/CLOSED',
  `anomaly_type` varchar(64) NOT NULL COMMENT '异常类型',
  `failure_count` int NOT NULL DEFAULT '1' COMMENT '连续查询异常次数',
  `last_provider_status` varchar(128) DEFAULT NULL COMMENT '最近可信上游状态',
  `last_error_message` varchar(500) DEFAULT NULL COMMENT '最近安全查询错误',
  `first_detected_time` datetime NOT NULL COMMENT '首次连续异常时间',
  `last_detected_time` datetime NOT NULL COMMENT '最近异常时间',
  `last_recheck_time` datetime DEFAULT NULL COMMENT '最近人工复查时间',
  `next_recheck_time` datetime DEFAULT NULL COMMENT '下次自动或人工复查时间',
  `wait_reason` varchar(500) DEFAULT NULL COMMENT '继续等待原因',
  `resolution_type` varchar(64) DEFAULT NULL COMMENT '关闭原因',
  `resolved_time` datetime DEFAULT NULL COMMENT '关闭时间',
  `version` bigint NOT NULL DEFAULT '1' COMMENT '状态乐观锁版本',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_media_task_anomaly_task` (`task_id`),
  KEY `idx_media_task_anomaly_admin` (`status`,`last_detected_time`,`id`),
  KEY `idx_media_task_anomaly_waiting` (`status`,`first_detected_time`,`id`),
  KEY `idx_media_task_anomaly_recheck` (`status`,`next_recheck_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='统一媒体异常任务治理';

CREATE TABLE IF NOT EXISTS `aid_media_task_anomaly_audit` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '异常操作审计ID',
  `anomaly_id` bigint DEFAULT NULL COMMENT '异常记录ID，配置审计可为空',
  `task_id` bigint DEFAULT NULL COMMENT '统一媒体任务ID',
  `action` varchar(64) NOT NULL COMMENT '审计动作',
  `operator_id` bigint DEFAULT NULL COMMENT '操作管理员ID',
  `operator_name` varchar(100) DEFAULT NULL COMMENT '操作管理员账号',
  `reason` varchar(500) DEFAULT NULL COMMENT '操作原因',
  `before_status` varchar(32) DEFAULT NULL COMMENT '操作前异常状态',
  `after_status` varchar(32) DEFAULT NULL COMMENT '操作后异常状态',
  `detail_json` longtext COMMENT '安全审计详情JSON',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  KEY `idx_media_task_anomaly_audit` (`anomaly_id`,`id`),
  KEY `idx_media_task_anomaly_task_audit` (`task_id`,`create_time`,`id`),
  KEY `idx_media_task_anomaly_operator` (`operator_id`,`create_time`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='统一媒体异常任务操作审计';


-- Add eligible model/capability choices without replacing pool order or configured defaults.
DROP PROCEDURE IF EXISTS aid_seed_model_business_choices;
DELIMITER $$
CREATE PROCEDURE aid_seed_model_business_choices()
BEGIN
    DECLARE done BOOLEAN DEFAULT FALSE;
    DECLARE selected_func VARCHAR(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE selected_model BIGINT;
    DECLARE selected_cap VARCHAR(96) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
    DECLARE selected_rank INT;
    DECLARE choices CURSOR FOR
        SELECT f.func_code, m.id, c.capability_code, s.sort_order
        FROM (
            SELECT 'openai' AS provider_code, 'image26' AS model_group, 'main_character_image' AS func_code, 'text_to_image' AS capability_code, 0 AS sort_order
            UNION ALL SELECT 'openai', 'image26', 'main_character_image', 'image_to_image', 1
            UNION ALL SELECT 'openai', 'image26', 'main_scene_image', 'text_to_image', 0
            UNION ALL SELECT 'openai', 'image26', 'main_scene_image', 'image_to_image', 1
            UNION ALL SELECT 'openai', 'image26', 'main_prop_image', 'text_to_image', 0
            UNION ALL SELECT 'openai', 'image26', 'main_prop_image', 'image_to_image', 1
            UNION ALL SELECT 'openai', 'image26', 'main_storyboard_image', 'text_to_image', 0
            UNION ALL SELECT 'openai', 'image26', 'main_storyboard_image', 'image_to_image', 1
            UNION ALL SELECT 'openai', 'image26', 'main_character_card_image', 'image_to_image', 0
            UNION ALL SELECT 'openai', 'image26', 'image_multi_grid', 'image_to_image', 0
            UNION ALL SELECT 'openai', 'image26', 'image_multi_view', 'image_to_image', 0
            UNION ALL SELECT 'openai', 'image26', 'image_edit', 'image_to_image', 0
            UNION ALL SELECT 'openai', 'image26', 'image_edit', 'text_to_image', 1
            UNION ALL SELECT 'openai', 'image26', 'image_edit', 'image_edit', 2
            UNION ALL SELECT 'openai', 'image26', 'image_edit', 'image_inpainting', 3
            UNION ALL SELECT 'openai', 'image26', 'image_edit', 'image_outpainting', 4
            UNION ALL SELECT 'openai', 'image26', 'canvas.image.emotion', 'image_edit', 0
            UNION ALL SELECT 'openai', 'image26', 'canvas.image.erase', 'image_inpainting', 0
            UNION ALL SELECT 'openai', 'image26', 'canvas.image.expand', 'image_outpainting', 0
            UNION ALL SELECT 'openai', 'image26', 'canvas.image.multi_view', 'image_edit', 0
            UNION ALL SELECT 'openai', 'image26', 'canvas.image.portrait_texture', 'image_edit', 0
            UNION ALL SELECT 'openai', 'image26', 'canvas.image.redraw', 'image_edit', 0
            UNION ALL SELECT 'openai', 'image26', 'canvas.image.redraw', 'image_inpainting', 1
            UNION ALL SELECT 'openai', 'image26', 'canvas.image.relight', 'image_edit', 0
            UNION ALL SELECT 'openai', 'image26', 'canvas.image.style_apply', 'image_edit', 0
            UNION ALL SELECT 'openai', 'image26', 'canvas.image.touch_edit', 'image_edit', 0
            UNION ALL SELECT 'openai', 'text', f.func_code, 'text', 0
                FROM aid_ai_model_func_config f
                WHERE f.func_code IN (
                    'main_character_extract', 'main_scene_extract', 'main_prop_extract',
                    'main_character_form', 'main_scene_form', 'main_prop_form',
                    'main_storyboard_script', 'main_storyboard_stylist', 'main_storyboard_video_prompt_image',
                    'main_storyboard_video_prompt', 'main_storyboard_script_two', 'main_storyboard_stylist_two',
                    'main_storyboard_video_prompt_image_two', 'main_storyboard_video_prompt_two',
                    'main_storyboard_video_prompt_grid_two', 'main_storyboard_video_prompt_dub_two',
                    'main_storyboard_video_prompt_grid'
                )
            UNION ALL SELECT 'deepseek', 'creative', 'ASSISTANT_CREATIVE_TEXT', 'text', 0
            UNION ALL SELECT 'topaz', 'upscale', 'image_upscale', 'image_upscale', 0
        ) s
        JOIN aid_ai_provider p ON p.provider_code = s.provider_code AND p.del_flag = '0'
        JOIN aid_ai_model m ON m.provider_id = p.id AND m.del_flag = '0'
        JOIN aid_ai_model_func_config f ON f.func_code = s.func_code AND f.del_flag = '0' AND f.model_type = m.model_type
        JOIN aid_ai_model_capability c ON c.model_id = m.id AND c.capability_code = s.capability_code
          AND JSON_UNQUOTE(JSON_EXTRACT(c.definition_json, '$.enabled')) = 'true'
        WHERE
            (s.model_group = 'image26' AND m.model_code IN ('gpt-image-2.6-flare', 'gpt-image-2.6-sunburst'))
            OR (s.model_group = 'text' AND m.model_code IN ('gpt-6-astra', 'gpt-6-sol', 'gpt-6-luna', 'gpt-5.6-terra', 'gpt-5.6-luna')
                AND m.supports_text_input = 1 AND m.supports_system_prompt = 1 AND m.supports_image_input = 1)
            OR (s.model_group = 'creative' AND m.model_code = 'deepseek-flash')
            OR (s.model_group = 'upscale' AND m.model_code = 'topaz-standard-2')
        ORDER BY f.func_code, m.id, s.sort_order;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

    START TRANSACTION;
    OPEN choices;
    add_choice: LOOP
        FETCH choices INTO selected_func, selected_model, selected_cap, selected_rank;
        IF done THEN LEAVE add_choice; END IF;

        INSERT INTO aid_ai_business_model_binding
            (func_code, model_id, capability_code, default_capability, sort_order, create_by, create_time)
        SELECT selected_func, selected_model, selected_cap, selected_rank = 0 AND NOT EXISTS (
            SELECT 1 FROM aid_ai_business_model_binding
            WHERE func_code = selected_func AND model_id = selected_model AND default_capability = 1
        ), selected_rank, 'system', NOW()
        WHERE NOT EXISTS (
            SELECT 1 FROM aid_ai_business_model_binding
            WHERE func_code = selected_func AND model_id = selected_model AND capability_code = selected_cap
        );

        UPDATE aid_ai_model_func_config
        SET model_ids = JSON_ARRAY_APPEND(COALESCE(model_ids, JSON_ARRAY()), '$', selected_model)
        WHERE func_code = selected_func AND del_flag = '0'
          AND JSON_CONTAINS(COALESCE(model_ids, JSON_ARRAY()), CAST(selected_model AS JSON)) = 0
          AND JSON_CONTAINS(COALESCE(model_ids, JSON_ARRAY()), JSON_QUOTE(CAST(selected_model AS CHAR))) = 0;
    END LOOP;
    CLOSE choices;
    COMMIT;
END$$
DELIMITER ;

CALL aid_seed_model_business_choices();
DROP PROCEDURE aid_seed_model_business_choices;


-- 自由画布后台、白模管理与异常任务的缺失结构及权限。普通角色继续由管理员单独授权。
CREATE TABLE IF NOT EXISTS `aid_entitlement_definition` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '权益定义ID',
  `scope_code` varchar(32) NOT NULL COMMENT '权益所属通用业务域',
  `entitlement_code` varchar(64) NOT NULL COMMENT '权益稳定编码',
  `entitlement_name` varchar(100) NOT NULL COMMENT '权益名称',
  `value_type` varchar(16) NOT NULL COMMENT '权益值类型',
  `entitlement_value` varchar(512) NOT NULL COMMENT '默认权益值',
  `enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用',
  `description` varchar(500) DEFAULT NULL COMMENT '权益说明',
  `subject_strategy` varchar(32) NOT NULL DEFAULT 'ACTOR' COMMENT '默认权益主体解析策略',
  `period_type` varchar(16) NOT NULL DEFAULT 'NONE' COMMENT '额度周期类型',
  `consumable` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否为可消耗额度',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '显示顺序',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_entitlement_scope_code` (`scope_code`,`entitlement_code`),
  KEY `idx_entitlement_scope_sort` (`scope_code`,`enabled`,`sort_order`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='通用可配置权益定义';

CREATE TABLE IF NOT EXISTS `aid_entitlement_user_override` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '用户权益覆盖ID',
  `scope_code` varchar(32) NOT NULL COMMENT '权益所属通用业务域',
  `subject_type` varchar(16) NOT NULL COMMENT '权益主体类型',
  `subject_id` bigint(20) NOT NULL COMMENT '权益主体ID',
  `entitlement_code` varchar(64) NOT NULL COMMENT '权益稳定编码',
  `mode` varchar(16) NOT NULL COMMENT '覆盖模式',
  `entitlement_value` varchar(512) DEFAULT NULL COMMENT '覆盖值',
  `start_time` datetime DEFAULT NULL COMMENT '生效时间',
  `end_time` datetime DEFAULT NULL COMMENT '结束时间',
  `status` varchar(16) NOT NULL DEFAULT 'ACTIVE' COMMENT '记录状态',
  `reason` varchar(500) NOT NULL COMMENT '授权原因',
  `create_by` varchar(64) NOT NULL COMMENT '创建人账号',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `revoke_by` varchar(64) DEFAULT NULL COMMENT '撤销人账号',
  `revoke_time` datetime DEFAULT NULL COMMENT '撤销时间',
  `revoke_reason` varchar(500) DEFAULT NULL COMMENT '撤销原因',
  PRIMARY KEY (`id`),
  KEY `idx_entitlement_override_effective` (`scope_code`,`subject_type`,`subject_id`,`status`,`start_time`,`end_time`,`id`),
  KEY `idx_entitlement_override_admin` (`scope_code`,`entitlement_code`,`status`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='通用用户权益覆盖';

