-- BEGIN SYSTEM NOTIFICATION
CREATE TABLE IF NOT EXISTS aid_system_notification (
  id bigint NOT NULL AUTO_INCREMENT COMMENT '通知编号',
  title varchar(100) NOT NULL COMMENT '通知标题',
  summary varchar(500) NOT NULL COMMENT '通知摘要',
  content mediumtext NOT NULL COMMENT '通知正文',
  content_format varchar(16) NOT NULL DEFAULT 'MARKDOWN' COMMENT '正文格式',
  message_type varchar(16) NOT NULL DEFAULT 'SYSTEM' COMMENT '消息类型',
  recipient_type varchar(16) NOT NULL COMMENT '收件类型 ALL/USERS',
  recipient_count bigint NOT NULL DEFAULT 0 COMMENT '发布时记录或选定收件人数',
  status varchar(16) NOT NULL DEFAULT 'DRAFT' COMMENT 'DRAFT/SCHEDULED/PUBLISHED/WITHDRAWN',
  scheduled_time datetime NULL DEFAULT NULL COMMENT '计划发布时间',
  publish_time datetime NULL DEFAULT NULL COMMENT '实际发布时间',
  publish_seq bigint NULL DEFAULT NULL COMMENT '严格发布序号',
  version bigint NOT NULL DEFAULT 1 COMMENT '乐观锁版本',
  creator_id bigint NOT NULL COMMENT '创建人编号',
  creator_name varchar(64) NOT NULL COMMENT '创建人名称',
  updater_id bigint NOT NULL COMMENT '更新人编号',
  updater_name varchar(64) NOT NULL COMMENT '更新人名称',
  create_time datetime NOT NULL COMMENT '创建时间',
  update_time datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (id),
  UNIQUE KEY uk_aid_notification_publish_seq (publish_seq),
  KEY idx_aid_notification_schedule (status,scheduled_time,id),
  KEY idx_aid_notification_visible (status,recipient_type,publish_time,publish_seq,id),
  KEY idx_aid_notification_unread (status,recipient_type,publish_seq,id),
  KEY idx_aid_notification_admin (status,update_time,id),
  KEY idx_aid_notification_admin_publish (publish_time,publish_seq,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='站内系统通知';

CREATE TABLE IF NOT EXISTS aid_notification_recipient (
  notification_id bigint NOT NULL COMMENT '通知编号',
  user_id bigint NOT NULL COMMENT '收件用户编号',
  publish_time datetime NULL DEFAULT NULL COMMENT '实际发布时间',
  publish_seq bigint NULL DEFAULT NULL COMMENT '实际发布序号',
  create_time datetime NOT NULL COMMENT '创建时间',
  PRIMARY KEY (notification_id,user_id),
  KEY idx_aid_notification_recipient_user (user_id,publish_time,publish_seq,notification_id),
  KEY idx_aid_notification_recipient_unread (user_id,publish_seq,notification_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='选定用户通知收件关系';

CREATE TABLE IF NOT EXISTS aid_notification_read (
  user_id bigint NOT NULL COMMENT '用户编号',
  notification_id bigint NOT NULL COMMENT '通知编号',
  read_time datetime NOT NULL COMMENT '阅读时间',
  PRIMARY KEY (user_id,notification_id),
  KEY idx_aid_notification_read_message (notification_id,user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通知单条阅读记录';

CREATE TABLE IF NOT EXISTS aid_notification_user_state (
  user_id bigint NOT NULL COMMENT '用户编号',
  read_all_publish_seq bigint NOT NULL DEFAULT 0 COMMENT '全读发布水位',
  read_all_time datetime NULL DEFAULT NULL COMMENT '最近全读时间',
  read_revision bigint NOT NULL DEFAULT 0 COMMENT '用户阅读修订',
  update_time datetime NOT NULL COMMENT '更新时间',
  PRIMARY KEY (user_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户通知阅读状态';

CREATE TABLE IF NOT EXISTS aid_notification_sequence (
  id tinyint NOT NULL COMMENT '固定序列行',
  publish_seq bigint NOT NULL DEFAULT 0 COMMENT '最后发布序号',
  visibility_revision bigint NOT NULL DEFAULT 0 COMMENT '可见性修订',
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通知发布序列';

INSERT INTO aid_notification_sequence(id,publish_seq,visibility_revision)
VALUES(1,0,0)
ON DUPLICATE KEY UPDATE id=VALUES(id);

CREATE TABLE IF NOT EXISTS aid_notification_operation (
  id bigint NOT NULL AUTO_INCREMENT COMMENT '操作编号',
  operator_id bigint NOT NULL COMMENT '管理员编号',
  action_type varchar(32) NOT NULL COMMENT '操作类型',
  client_request_id varchar(64) NOT NULL COMMENT '客户端请求编号',
  request_hash char(64) NOT NULL COMMENT '请求摘要',
  notification_id bigint NULL DEFAULT NULL COMMENT '通知编号',
  response_version bigint NULL DEFAULT NULL COMMENT '响应版本',
  create_time datetime NOT NULL COMMENT '创建时间',
  complete_time datetime NULL DEFAULT NULL COMMENT '完成时间',
  PRIMARY KEY (id),
  UNIQUE KEY uk_aid_notification_operation_request (operator_id,action_type,client_request_id),
  KEY idx_aid_notification_operation_time (create_time,id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='通知管理幂等操作';

SET @notification_parent_id := (
  SELECT menu_id FROM sys_menu
  WHERE parent_id=0 AND menu_type='M' AND path='asset'
  ORDER BY menu_id LIMIT 1
);
SET @notification_menu_id := (
  SELECT menu_id FROM sys_menu
  WHERE component='aid/notification/index' OR perms='system:notification:list'
  ORDER BY menu_id LIMIT 1
);
INSERT INTO sys_menu
  (menu_name,parent_id,order_num,path,component,query,route_name,is_frame,is_cache,menu_type,
   visible,status,perms,icon,create_by,create_time,update_by,update_time,remark)
SELECT '站内通知',@notification_parent_id,5,'notification','aid/notification/index',NULL,'',
       1,0,'C','0','0','system:notification:list','message','system',NOW(),'system',NOW(),'站内系统通知管理'
WHERE @notification_parent_id IS NOT NULL AND @notification_menu_id IS NULL;
SET @notification_menu_id := (
  SELECT menu_id FROM sys_menu
  WHERE component='aid/notification/index' OR perms='system:notification:list'
  ORDER BY menu_id LIMIT 1
);
UPDATE sys_menu
SET menu_name='站内通知',parent_id=@notification_parent_id,order_num=5,path='notification',
    component='aid/notification/index',visible='0',status='0',perms='system:notification:list',
    icon='message',update_by='system',update_time=NOW(),remark='站内系统通知管理'
WHERE menu_id=@notification_menu_id AND @notification_parent_id IS NOT NULL;

INSERT INTO sys_menu
  (menu_name,parent_id,order_num,path,component,query,route_name,is_frame,is_cache,menu_type,
   visible,status,perms,icon,create_by,create_time,update_by,update_time,remark)
SELECT permission_name,@notification_menu_id,order_num,'#',NULL,NULL,'',1,0,'F','0','0',
       permission_code,'#','system',NOW(),'system',NOW(),''
FROM (
  SELECT '通知保存' permission_name,1 order_num,'system:notification:save' permission_code
  UNION ALL SELECT '通知发布',2,'system:notification:publish'
  UNION ALL SELECT '通知撤回',3,'system:notification:withdraw'
  UNION ALL SELECT '取消定时',4,'system:notification:cancelSchedule'
  UNION ALL SELECT '选择收件人',5,'system:notification:recipients'
) notification_permissions
WHERE @notification_menu_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM sys_menu existing WHERE existing.perms=notification_permissions.permission_code);

INSERT IGNORE INTO sys_role_menu(role_id,menu_id)
SELECT 1,menu_id FROM sys_menu
WHERE menu_id=@notification_menu_id OR parent_id=@notification_menu_id;
