-- 发现内容浏览、投稿与后台审核。
CREATE TABLE IF NOT EXISTS `aid_discovery_media` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '投稿或创建用户ID',
  `source_type` varchar(16) NOT NULL COMMENT '来源：USER/ADMIN',
  `media_type` varchar(16) NOT NULL COMMENT '媒体类型：video/image',
  `name` varchar(100) NOT NULL COMMENT '内容名称',
  `description` varchar(1000) NOT NULL COMMENT '内容描述',
  `cover_url` varchar(500) NOT NULL COMMENT '封面地址；图片内容使用本字段保存图片',
  `media_url` varchar(500) NULL DEFAULT NULL COMMENT '视频地址；图片内容为空',
  `preview_video_url` varchar(500) NULL DEFAULT NULL COMMENT '视频预览地址',
  `media_width` int(11) NOT NULL COMMENT '媒体宽度',
  `media_height` int(11) NOT NULL COMMENT '媒体高度',
  `aspect_ratio` varchar(32) NOT NULL COMMENT '服务端归一化画幅比例',
  `ratio_source` varchar(16) NOT NULL DEFAULT 'declared' COMMENT '比例来源：measured/declared',
  `prompt_text` varchar(4000) NULL DEFAULT NULL COMMENT '后台预留提示词',
  `review_status` varchar(16) NOT NULL COMMENT '审核状态：PENDING/APPROVED/REJECTED/REVOKED',
  `review_reason` varchar(500) NULL DEFAULT NULL COMMENT '最近审核说明',
  `review_by` varchar(64) NULL DEFAULT NULL COMMENT '最近审核人',
  `review_time` datetime NULL DEFAULT NULL COMMENT '最近审核时间',
  `publish_time` datetime NULL DEFAULT NULL COMMENT '发布时间',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序值，越小越靠前',
  `status` char(1) NOT NULL DEFAULT '0' COMMENT '展示状态：0启用 1停用',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志：0正常 1删除',
  `create_by` varchar(64) NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  INDEX `idx_discovery_public` (`review_status`, `status`, `del_flag`, `sort_order`, `publish_time`, `id`),
  INDEX `idx_discovery_user` (`user_id`, `source_type`, `del_flag`, `create_time`, `id`),
  INDEX `idx_discovery_review` (`review_status`, `source_type`, `media_type`, `del_flag`, `create_time`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='发现内容投稿与发布';

CREATE TABLE IF NOT EXISTS `aid_discovery_media_review_log` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `media_id` bigint(20) NOT NULL COMMENT '发现内容ID',
  `action` varchar(24) NOT NULL COMMENT 'SUBMIT/RESUBMIT/APPROVE/REJECT/REVOKE/ADMIN_CREATE/UPDATE/DELETE',
  `before_status` varchar(16) NULL DEFAULT NULL COMMENT '变更前审核状态',
  `after_status` varchar(16) NULL DEFAULT NULL COMMENT '变更后审核状态',
  `reason` varchar(500) NULL DEFAULT NULL COMMENT '操作说明',
  `operator_type` varchar(16) NOT NULL COMMENT '操作人类型：USER/ADMIN',
  `operator_id` bigint(20) NULL DEFAULT NULL COMMENT '操作人ID',
  `operator_name` varchar(64) NULL DEFAULT NULL COMMENT '操作人名称',
  `del_flag` char(1) NOT NULL DEFAULT '0' COMMENT '删除标志：0正常 1删除',
  `create_by` varchar(64) NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`),
  INDEX `idx_discovery_log_media` (`media_id`, `create_time`, `id`),
  INDEX `idx_discovery_log_operator` (`operator_id`, `create_time`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='发现内容审核操作记录';

SET @discovery_audit_root := (SELECT MIN(menu_id) FROM sys_menu WHERE menu_type='M' AND parent_id=0 AND menu_name='审核管理');
SET @discovery_menu := (SELECT MIN(menu_id) FROM sys_menu WHERE menu_type='C' AND
    (component IN ('aid/discovery/index','commercial/discovery/index') OR perms='commercial:discovery:list'));
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,component,menu_type,visible,status,perms,icon,create_by,create_time)
SELECT '发现审核',@discovery_audit_root,2,'discovery','commercial/discovery/index','C','0','0','commercial:discovery:list','star','system',NOW()
WHERE @discovery_audit_root IS NOT NULL AND @discovery_menu IS NULL;
UPDATE sys_menu
SET parent_id=@discovery_audit_root, menu_name='发现审核', component='commercial/discovery/index',
    perms='commercial:discovery:list', order_num=2
WHERE menu_id=@discovery_menu AND @discovery_audit_root IS NOT NULL
  AND perms='aid:discovery:list'
  AND NOT EXISTS (
      SELECT 1 FROM (
          SELECT menu_id FROM sys_menu WHERE perms='commercial:discovery:list'
      ) AS migrated_discovery
  );
SET @discovery_menu := (SELECT MIN(menu_id) FROM sys_menu WHERE menu_type='C' AND perms='commercial:discovery:list');
INSERT INTO sys_menu(menu_name,parent_id,order_num,path,menu_type,visible,status,perms,icon,create_by,create_time)
SELECT p.name,@discovery_menu,p.order_num,'#','F','0','0',p.perms,'#','system',NOW()
FROM (SELECT '发现内容详情' name,1 order_num,'commercial:discovery:query' perms
    UNION ALL SELECT '发现内容新增',2,'commercial:discovery:add'
    UNION ALL SELECT '发现内容修改',3,'commercial:discovery:edit'
    UNION ALL SELECT '发现投稿审核',4,'commercial:discovery:review'
    UNION ALL SELECT '发现内容删除',5,'commercial:discovery:remove') p
WHERE @discovery_menu IS NOT NULL AND NOT EXISTS (SELECT 1 FROM sys_menu m WHERE m.perms=p.perms);


-- 新手引导的通用步骤和个人进度结构。
CREATE TABLE IF NOT EXISTS `aid_onboarding_tour_config`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tour_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Tour 标识',
  `tour_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Tour 名称',
  `tour_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Tour 类型：overview=概览向导 / highlight=页面高亮',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT 'Tour 说明',
  `is_enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用：0否 1是',
  `sort_order` int(11) NOT NULL DEFAULT 0 COMMENT '排序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tour_id`(`tour_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '引导配置' ROW_FORMAT = Dynamic;

CREATE TABLE IF NOT EXISTS `aid_user_onboarding_profile`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID（关联 sys_user.user_id）',
  `global_dismissed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '是否全局关闭引导：0否 1是',
  `dismissed_at` datetime NULL DEFAULT NULL COMMENT '最后一次设置全局关闭（global_dismissed=1）的时间',
  `schema_version` int(11) NOT NULL DEFAULT 1 COMMENT '协议版本，与前端 schemaVersion 对齐',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 1代表删除）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '创建者',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '用户引导-全局配置' ROW_FORMAT = Dynamic;

CREATE TABLE IF NOT EXISTS `aid_user_onboarding_tour`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint(20) NOT NULL COMMENT '用户ID',
  `tour_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'Tour 标识，来自 aid_onboarding_tour_config',
  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT 'completed/skipped/in_progress',
  `tour_version` int(11) NOT NULL DEFAULT 1 COMMENT '用户完成/跳过时该 Tour 的前端版本号',
  `last_step_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '进行中时最后一步 stepId',
  `client_updated_at` datetime NOT NULL COMMENT '客户端上报时间（冲突合并依据）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_user_tour`(`user_id`, `tour_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '引导进度' ROW_FORMAT = Dynamic;

